/**
 * 01.amazon白抜きベース（Drive）の正本候補画像一覧。
 * Property SET_MAIN_AMAZON_BASE_FOLDER_ID があれば優先。無ければフォルダ名検索。
 * @return {{ok:boolean, files:Array<{name:string,rel:string}>, error?:string, hint?:string}}
 */
function listAmazonBaseTruthImageFiles_() {
  var fn = 'listAmazonBaseTruthImageFiles_';
  var t0 = Date.now();
  var out = { ok: false, files: [], error: '', hint: '' };
  try {
    var resolved = resolveAmazonBaseTruthFolderDetailed_();
    b4DiagLog_(
      fn,
      t0,
      'AFTER_RESOLVE',
      'via=' + String(resolved.via || 'none') + (resolved.folderId ? ' id=' + resolved.folderId : '')
    );
    var folder = resolved.folder;
    if (!folder) {
      out.error =
        'フォルダ「01.amazon白抜きベース」が見つかりません。Driveでフォルダを開き、URLのIDを Script Properties「SET_MAIN_AMAZON_BASE_FOLDER_ID」へ。';
      out.hint = 'SET_MAIN_AMAZON_BASE_FOLDER_ID を設定してください';
      b4DiagLog_(fn, t0, 'FAIL', 'reason=no_folder');
      return out;
    }
    out.hint = 'Drive: ' + folder.getName() + ' (via=' + resolved.via + ')';
    var files = [];
    collectImageFilesFromFolder_(folder, '', files);
    var nRoot = files.length;
    var processed = folder.getFoldersByName('処理済み');
    var nProc = 0;
    if (processed.hasNext()) {
      collectImageFilesFromFolder_(processed.next(), '処理済み/', files);
      nProc = files.length - nRoot;
    }
    out.files = files;
    out.ok = true;
    b4DiagLog_(fn, t0, 'DONE', 'root=' + nRoot + ' processed=' + nProc + ' total=' + files.length);
    return out;
  } catch (e) {
    out.error = String(e);
    b4DiagLog_(fn, t0, 'EXCEPTION', String(e).slice(0, 160));
    return out;
  }
}

/**
 * @return {{folder:GoogleAppsScript.Drive.Folder|null, via:string, folderId?:string}}
 */
function resolveAmazonBaseTruthFolderDetailed_() {
  var prop = PropertiesService.getScriptProperties().getProperty(
    'SET_MAIN_AMAZON_BASE_FOLDER_ID'
  );
  if (prop && String(prop).trim()) {
    var id = String(prop).trim();
    return { folder: DriveApp.getFolderById(id), via: 'property', folderId: id };
  }
  var parents = DriveApp.getFoldersByName('05.画像生成（セットMAIN）');
  while (parents.hasNext()) {
    var p = parents.next();
    var kids = p.getFoldersByName('01.amazon白抜きベース');
    if (kids.hasNext()) {
      var kid = kids.next();
      return { folder: kid, via: 'name_under_05', folderId: kid.getId() };
    }
  }
  var direct = DriveApp.getFoldersByName('01.amazon白抜きベース');
  if (direct.hasNext()) {
    var d = direct.next();
    return { folder: d, via: 'name_direct', folderId: d.getId() };
  }
  return { folder: null, via: 'none' };
}

function resolveAmazonBaseTruthFolder_() {
  return resolveAmazonBaseTruthFolderDetailed_().folder;
}

function collectImageFilesFromFolder_(folder, prefix, into) {
  var it = folder.getFiles();
  while (it.hasNext()) {
    var f = it.next();
    var n = f.getName();
    if (!/\.(png|jpe?g|webp)$/i.test(n)) continue;
    if (n.indexOf('.') === 0) continue;
    into.push({ name: n, rel: String(prefix || '') + n });
  }
}

/**
 * B-③から JAN → 商品名（代表）を返す。
 * @param {string[]} jans
 * @return {Object.<string,string>}
 */
function collectB3ProductNamesForJans_(jans) {
  var map = {};
  var want = {};
  for (var i = 0; i < (jans || []).length; i++) want[String(jans[i])] = true;
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var b3 = ss.getSheetByName(COMPETITOR_IMAGE_B3_OUTPUT_SHEET_NAME);
  if (!b3 || b3.getLastRow() < 2) return map;
  var values = b3.getDataRange().getValues();
  var header = values[0];
  var iJan = header.indexOf('JAN');
  var iName = header.indexOf('商品名');
  if (iJan < 0) return map;
  for (var r = 1; r < values.length; r++) {
    var jan = String(values[r][iJan] || '').trim();
    if (!want[jan] || map[jan]) continue;
    var nm = iName >= 0 ? String(values[r][iName] || '').trim() : '';
    map[jan] = nm;
  }
  return map;
}

/**
 * B-③のサブ採用CK、無ければ採用ログから JAN 一覧を返す。
 * @return {{jans:string[], counts:Object.<string,number>, totalImages:number, source:string}}
 */
function collectB3SubAdoptedJansForPrompt_() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var counts = {};
  var source = 'none';
  var b3 = ss.getSheetByName(COMPETITOR_IMAGE_B3_OUTPUT_SHEET_NAME);
  if (b3 && b3.getLastRow() >= 2) {
    var values = b3.getDataRange().getValues();
    var header = values[0];
    var iJan = header.indexOf('JAN');
    var iUrl = header.indexOf('画像URL');
    var iCk = header.indexOf(B3_SUB_ADOPT_CK_HEADER);
    if (iJan >= 0 && iUrl >= 0 && iCk >= 0) {
      for (var i = 1; i < values.length; i++) {
        var ck = values[i][iCk];
        var on = ck === true || String(ck).toUpperCase() === 'TRUE';
        if (!on) continue;
        var jan = String(values[i][iJan] || '').trim();
        var url = String(values[i][iUrl] || '').trim();
        if (!jan || url.indexOf('http') !== 0) continue;
        counts[jan] = (counts[jan] || 0) + 1;
      }
      if (Object.keys(counts).length) source = 'b3_sheet';
    }
  }
  if (!Object.keys(counts).length) {
    var logSh = ss.getSheetByName(COMPETITOR_IMAGE_SUB_ADOPT_LOG_SHEET_NAME);
    if (logSh && logSh.getLastRow() >= 2) {
      var lv = logSh.getDataRange().getValues();
      var lh = lv[0];
      var lj = lh.indexOf('JAN');
      var lu = lh.indexOf('画像URL');
      if (lj >= 0 && lu >= 0) {
        for (var r = 1; r < lv.length; r++) {
          var j2 = String(lv[r][lj] || '').trim();
          var u2 = String(lv[r][lu] || '').trim();
          if (!j2 || u2.indexOf('http') !== 0) continue;
          counts[j2] = (counts[j2] || 0) + 1;
        }
        if (Object.keys(counts).length) source = 'adopt_log';
      }
    }
  }
  var jans = Object.keys(counts).sort();
  var total = 0;
  for (var k = 0; k < jans.length; k++) total += counts[jans[k]];
  return { jans: jans, counts: counts, totalImages: total, source: source };
}

/**
 * B-③ マスタレ点行の競合画像取得（必要時のみ）。確認ダイアログ後に一覧を出力。
 */
function menuB3MasterCheckedCompetitorImages() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var ui = SpreadsheetApp.getUi();
  var masterSheet = ss.getSheetByName(MASTER_SHEET_NAME);
  if (!masterSheet) {
    ui.alert('▼商品マスタ(人間作業用) シートが見つかりません。');
    return;
  }
  var masterValues = masterSheet.getDataRange().getValues();
  var headerRowIdx = -1;
  for (var hr = 0; hr < Math.min(masterValues.length, 20); hr++) {
    if (masterValues[hr].indexOf(ANCHOR_HEADER_NAME) !== -1) { headerRowIdx = hr; break; }
  }
  if (headerRowIdx === -1) {
    ui.alert('マスタのヘッダー行が見つかりません。');
    return;
  }
  var masterColMap = getColumnIndexMap(masterValues[headerRowIdx]);
  if (masterColMap['JANコード'] === undefined || masterColMap[CHECKBOX_HEADER_NAME] === undefined) {
    ui.alert('マスタに JANコード・' + CHECKBOX_HEADER_NAME + ' が必要です。');
    return;
  }
  var checkedJans = getUniqueCheckedJansFromMasterForImage_(masterValues, headerRowIdx, masterColMap);
  if (checkedJans.length === 0) {
    ui.alert('出品CK（レ点）が付いた行に有効な JANコード がありません。');
    return;
  }
  if (!ensureCrossMallSheetCoversJansForB3_(ss, ui, checkedJans)) {
    ui.alert('モール横断シートの更新がキャンセルされたか、未実行です。レ点・JAN・モール横断を確認してから再度 B-③ を実行してください。');
    return;
  }

  var ryMsg =
    '楽天・Yahoo! の競合画像のみ取得しますか？\n\n' +
    '「はい」＝Amazon(Keepa)の画像は出力しません。\n' +
    '「いいえ」＝Amazon も含めます（追加の確認があります）。';
  var ryResp = ui.alert('B-③', ryMsg, ui.ButtonSet.YES_NO);
  if (ryResp !== ui.Button.YES && ryResp !== ui.Button.NO) {
    return;
  }
  var ryOnly = ryResp === ui.Button.YES;

  if (!ryOnly) {
    var reviewedMsg =
      'Amazon(Keepa)用の評価「◎」の内容を目視確認済みですか？\n\n' +
      '「はい」＝「' + TARGET_SHEET_NAME + '」・ASIN貼り付けの確認に進みます（精査済みルート）。\n' +
      '「いいえ」＝Keepa取得（全件）を自動実行したうえで、そのまま画像一覧の出力に進みます（◎の誤り等は運用側の責任です）。';
    var revResp = ui.alert('B-③｜Amazon', reviewedMsg, ui.ButtonSet.YES_NO);
    if (revResp !== ui.Button.YES && revResp !== ui.Button.NO) {
      return;
    }
    if (revResp === ui.Button.NO) {
      var discMsg =
        'Keepa取得（全件）後、評価◎は自動付与される場合があります。誤った候補が混ざるリスクを理解したうえで、自動実行により画像一覧の出力まで進めますか？';
      if (ui.alert('B-③｜運用免責', discMsg, ui.ButtonSet.YES_NO) !== ui.Button.YES) {
        return;
      }
      try {
        runKeepaFetchAsinPasteSheet(0);
      } catch (eKeepa) {
        return;
      }
    } else {
      var q1Msg =
        '「' + TARGET_SHEET_NAME + '」に、画像取得対象の JAN を入力済みですか？\n（該当JANの ASIN貼り付け用ブロック作成の前提になります）';
      if (ui.alert('B-③｜準備①', q1Msg, ui.ButtonSet.YES_NO) !== ui.Button.YES) {
        return;
      }
      var q2Msg =
        '「' + ASIN_PASTE_SHEET_NAME + '」に当該 JAN のブロックがあり、Keepa 取得済みで対象品と判断された行（評価「◎」）の ASIN が含まれる状態を確認しましたか？\n（◎は通常Keepa取得後に自動付与。内容の精査は人が行います）';
      if (ui.alert('B-③｜準備②', q2Msg, ui.ButtonSet.YES_NO) !== ui.Button.YES) {
        var prepMsg =
          'メニュー「A → 3. Keepa取得（全件）」相当の処理（全件取得）を実行しますか？\n\n実行後、シート上の◎を精査し、改めて B-③ を実行してください。';
        if (ui.alert('B-③｜Keepa取得', prepMsg, ui.ButtonSet.YES_NO) === ui.Button.YES) {
          try {
            runKeepaFetchAsinPasteSheet(0);
          } catch (ePrep) {
            return;
          }
        }
        ui.alert('◎の精査が終わったら、再度「B-③ マスタレ点行の競合画像取得」を実行してください。');
        return;
      }
    }
  }

  menuTestCompetitorImageUrlsOutputImpl_({
    outputSheetName: COMPETITOR_IMAGE_B3_OUTPUT_SHEET_NAME,
    skipAmazonBlock: ryOnly,
    menuTag: 'B-③'
  });
}

/**
 * 競合画像URL一覧の本体。opt: outputSheetName, skipAmazonBlock, menuTag
 * 出品CK（レ点）付きマスタ行のJANについて、Amazonはログ◎→貼付◎→マスタ親子の順で解決し、
 * ◎/候補ASINは全件Keepa画像取得（画像≥1で段確定、0件なら次段）。Amazon0件でも楽天・Yahooは実行。
 * @param {Object} [opt]
 */
function menuTestCompetitorImageUrlsOutputImpl_(opt) {
  opt = opt || {};
  var outputSheetName = opt.outputSheetName || COMPETITOR_IMAGE_B3_OUTPUT_SHEET_NAME;
  var skipAmazonBlock = !!opt.skipAmazonBlock;
  var menuTag = opt.menuTag || '競合画像';
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var ui = SpreadsheetApp.getUi();
  var masterSheet = ss.getSheetByName(MASTER_SHEET_NAME);
  if (!masterSheet) {
    ui.alert('▼商品マスタ(人間作業用) シートが見つかりません。');
    return;
  }
  var crossSheet = ss.getSheetByName(CROSS_MALL_SET_COUNT_SHEET_NAME);
  if (!crossSheet) {
    ui.alert('シート「' + CROSS_MALL_SET_COUNT_SHEET_NAME + '」が見つかりません。先にモール横断セット数統合判定を実行してください。');
    return;
  }
  var crossValues = crossSheet.getDataRange().getValues();
  var crossFormulas = crossSheet.getDataRange().getFormulas();
  if (crossValues.length < 2) {
    ui.alert('シート「' + CROSS_MALL_SET_COUNT_SHEET_NAME + '」にデータがありません。');
    return;
  }
  var masterValues = masterSheet.getDataRange().getValues();
  var headerRowIdx = -1;
  for (var hr = 0; hr < Math.min(masterValues.length, 20); hr++) {
    if (masterValues[hr].indexOf(ANCHOR_HEADER_NAME) !== -1) { headerRowIdx = hr; break; }
  }
  if (headerRowIdx === -1) {
    ui.alert('マスタのヘッダー行が見つかりません。');
    return;
  }
  var masterColMap = getColumnIndexMap(masterValues[headerRowIdx]);
  var colJan = masterColMap['JANコード'];
  var colSetQty = masterColMap[COL_MASTER_TOTAL_QTY];
  var colCheckbox = masterColMap[CHECKBOX_HEADER_NAME];
  if (colJan === undefined || colSetQty === undefined || colCheckbox === undefined) {
    ui.alert('マスタに JANコード・' + COL_MASTER_TOTAL_QTY + '・' + CHECKBOX_HEADER_NAME + ' が必要です。');
    return;
  }
  var props = PropertiesService.getScriptProperties();
  var keepaKey = (props.getProperty('KEEPA_API_KEY') || '').trim();
  var rakutenAppId = (props.getProperty('RAKUTEN_APP_ID') || '').trim();
  var rakutenAccess = (props.getProperty('RAKUTEN_ACCESS_KEY') || '').trim();
  var yahooClientId = (props.getProperty('YAHOO_SHOPPING_CLIENT_ID') || '').trim();
  var rakutenOk = !!(rakutenAppId && rakutenAccess);
  var yahooOk = !!yahooClientId;
  if (!rakutenOk) Logger.log('[競合画像テスト] RAKUTEN_APP_ID / RAKUTEN_ACCESS_KEY 未設定のため楽天ブロックをスキップ');
  if (!yahooOk) Logger.log('[競合画像テスト] YAHOO_SHOPPING_CLIENT_ID 未設定のため Yahoo! API（itemLookup JSON/V3・採用候補）をスキップ');

  var parsedCross = parseCrossMallSheetToByJan_(crossValues, {
    excludeImageGuard: false,
    includeImageCells: true,
    allowUnknownIntegratedSetForImages: true
  }, crossSheet, crossFormulas);
  var byJan = parsedCross.byJan;
  Logger.log('[競合画像テスト] モール横断パース完了（不明セット許容） シート行(values)=' + crossValues.length + ' (formulas)=' + (crossFormulas ? crossFormulas.length : 0) + ' JANブロック数=' + Object.keys(byJan).length);

  var targetRows = [];
  for (var mr = headerRowIdx + 1; mr < masterValues.length; mr++) {
    var rowJan = String(masterValues[mr][colJan] || '').trim();
    if (!masterValues[mr][colCheckbox]) continue;
    if (!byJan[rowJan]) continue;
    targetRows.push({ rowNum: mr + 1, jan: rowJan, dataIdx: mr });
  }
  if (targetRows.length === 0) {
    ui.alert('出品CK（レ点）が付き、かつモール横断シートにデータがあるJANの行がありません。');
    return;
  }

  var asinPasteSheet = ss.getSheetByName(ASIN_PASTE_SHEET_NAME);
  var amazonResolved = { byJan: {}, keepaMap: {} };
  if (!skipAmazonBlock && keepaKey) {
    var jansForAmazon = [];
    var janSeenAmz = {};
    for (var tc = 0; tc < targetRows.length; tc++) {
      var janT = targetRows[tc].jan;
      if (!janSeenAmz[janT]) {
        janSeenAmz[janT] = true;
        jansForAmazon.push(janT);
      }
    }
    amazonResolved = resolveAmazonCompetitorAsinsCascade_(
      ss, jansForAmazon, asinPasteSheet, masterValues, headerRowIdx, masterColMap, keepaKey
    );
    Logger.log('[競合画像テスト] Amazon解決完了 JAN数=' + jansForAmazon.length +
      ' keepaMap=' + Object.keys(amazonResolved.keepaMap || {}).length +
      (asinPasteSheet ? '' : '（ASIN貼り付けシート無し・段1スキップ）'));
  } else if (!skipAmazonBlock && !keepaKey) {
    Logger.log('[競合画像テスト] KEEPA_API_KEY 未設定のため Amazon/Keepa ブロックをスキップ');
  }

  function imageFormula_(u) {
    if (!u || String(u).indexOf('http') !== 0) return '';
    return '=IMAGE("' + String(u).replace(/"/g, '""') + '",2)';
  }

  var out = [];
  /** @type {Object.<string, {idx:number, score:number}>} */
  var seenImageMeta = {};

  function pushImageRowIfNew_(kind, rowVals, rawUrlForDedup) {
    var u = String(rawUrlForDedup || '').trim();
    if (!u || u.indexOf('http') !== 0) {
      out.push(rowVals);
      return true;
    }
    var key = normalizeCompetitorImageUrlKey_(u);
    if (!key) {
      out.push(rowVals);
      return true;
    }
    var score = estimateCompetitorImagePixelScore_(u);
    var prev = seenImageMeta[key];
    if (prev) {
      if (score > prev.score) {
        out[prev.idx] = rowVals;
        seenImageMeta[key] = { idx: prev.idx, score: score };
        Logger.log('[競合画像テスト] 重複置換(高画素優先) 区分=' + kind + ' マスタ行=' + rowVals[0] + ' JAN=' + rowVals[1] +
          ' urlKey=' + key + ' score=' + score + '（旧' + prev.score + '）');
        return true;
      }
      Logger.log('[競合画像テスト] 重複除外 区分=' + kind + ' マスタ行=' + rowVals[0] + ' JAN=' + rowVals[1] +
        ' urlKey=' + key + ' score=' + score + '≤' + prev.score);
      return false;
    }
    seenImageMeta[key] = { idx: out.length, score: score };
    out.push(rowVals);
    return true;
  }

  out.push(['マスタ行', 'JAN', 'A.セット商品数', '区分', 'ASINまたは商品URL', '画像番号', '画像URL', 'プレビュー']);

  var yahooItemLookupCallIndex = 0;

  for (var ti = 0; ti < targetRows.length; ti++) {
    var tr = targetRows[ti];
    var jan = tr.jan;
    var setQtyVal = masterValues[tr.dataIdx][colSetQty];
    var setQty = (setQtyVal !== '' && setQtyVal != null) ? (typeof setQtyVal === 'number' ? setQtyVal : parseInt(String(setQtyVal).replace(/[^0-9]/g, ''), 10)) : null;
    if (isNaN(setQty) || setQty < 1) setQty = null;
    var setKey = setQty != null ? String(setQty) : '';

    if (!skipAmazonBlock && keepaKey) {
      var resAmz = (amazonResolved.byJan && amazonResolved.byJan[jan])
        ? amazonResolved.byJan[jan]
        : { asins: [], source: 'none' };
      var keepaMap = amazonResolved.keepaMap || {};
      var asins2 = resAmz.asins || [];
      var srcLabel = 'Amazon(なし)';
      if (resAmz.source === 'keepa_log') srcLabel = 'Amazon(Keepa・ログ◎)';
      else if (resAmz.source === 'asin_paste') srcLabel = 'Amazon(Keepa・貼付◎)';
      else if (resAmz.source === 'master') srcLabel = 'Amazon(Keepa・マスタ)';
      if (asins2.length === 0) {
        out.push([tr.rowNum, jan, setQty != null ? setQty : '', srcLabel, '', '', '候補ASINなし（ログ◎→貼付◎→マスタ）', '']);
        Logger.log('[競合画像テスト] Amazonなし JAN=' + jan + ' マスタ行=' + tr.rowNum + '（楽天・Yahooは続行）');
      } else {
        for (var aj = 0; aj < asins2.length; aj++) {
          var asin = asins2[aj];
          var prod = keepaMap[asin];
          var urls = prod ? getKeepaProductImageUrlsMaxForCompetitorTest_(prod) : [];
          if (urls.length === 0) {
            out.push([tr.rowNum, jan, setQty != null ? setQty : '', srcLabel, asin, '', '(画像0件)', '']);
            Logger.log('[競合画像テスト] ' + srcLabel + ' 画像0件 JAN=' + jan + ' ASIN=' + asin + ' マスタ行=' + tr.rowNum);
          } else {
            for (var uk = 0; uk < urls.length; uk++) {
              pushImageRowIfNew_(srcLabel, [tr.rowNum, jan, setQty != null ? setQty : '', srcLabel, asin, uk + 1, urls[uk], imageFormula_(urls[uk])], urls[uk]);
            }
          }
        }
      }
    }

    if (rakutenOk) {
      if (!byJan[jan] || !byJan[jan].rakutenBySet) {
        out.push([tr.rowNum, jan, setQty != null ? setQty : '', '楽天(採用候補)', '', '', 'モール横断に当該JANなし', '']);
        Logger.log('[競合画像テスト] 楽天(採用候補) モール横断にJANなし マスタ行=' + tr.rowNum + ' JAN=' + jan);
      } else {
        var rReps = pickCrossMallRepresentativesPerShopByPrice_(byJan[jan].rakutenBySet, COMPETITOR_IMAGE_TEST_MAX_SHOPS_PER_MALL, extractRakutenShopIdFromItemUrl_);
        if (rReps.length === 0) {
          out.push([tr.rowNum, jan, setQty != null ? setQty : '', '楽天(採用候補)', '', '', '店舗単位候補なし（URL未取得）', '']);
          Logger.log('[競合画像テスト] 楽天(採用候補) 店舗代表0件 マスタ行=' + tr.rowNum + ' JAN=' + jan);
        } else {
          Logger.log('[競合画像テスト] 楽天(採用候補) 店舗代表=' + rReps.length + '／上限' + COMPETITOR_IMAGE_TEST_MAX_SHOPS_PER_MALL + '（税込昇順） JAN=' + jan + ' マスタ行=' + tr.rowNum);
          for (var rjx = 0; rjx < rReps.length; rjx++) {
            var rRep = rReps[rjx];
            var rDataR = rRep.data;
            var setDispR = parseInt(rRep.setKey, 10);
            var setColR = !isNaN(setDispR) ? setDispR : rRep.setKey;
            var imgRR = extractImageUrlFromCrossMallImageCell_(rDataR.imageCell);
            var icPrevRR = String(rDataR.imageCell || '').substring(0, 120);
            Logger.log('[競合画像テスト] 楽天(採用候補) shop=' + rRep.shopId + ' setKey=' + rRep.setKey + ' priceIncl=' + rDataR.priceIncl + ' マスタ行=' + tr.rowNum + ' JAN=' + jan + ' imageCell先頭=' + icPrevRR);
            var rApiR = fetchRakutenIchibaItemImageUrlsForCompetitorTest_(rakutenAppId, rakutenAccess, rDataR.url, jan);
            if (rApiR.error) Logger.log('[競合画像テスト] 楽天 Ichiba: ' + rApiR.error + ' shop=' + rRep.shopId);
            if (rApiR.urls && rApiR.urls.length > 0) {
              Logger.log('[競合画像テスト] 楽天 Ichiba 画像(_ex=' + RAKUTEN_COMPETITOR_IMAGE_EX_MAX + ') 件数=' + rApiR.urls.length + ' shop=' + rRep.shopId);
              for (var rir = 0; rir < rApiR.urls.length; rir++) {
                pushImageRowIfNew_('楽天(採用候補)', [tr.rowNum, jan, setColR, '楽天(採用候補)', rDataR.url, rir + 1, rApiR.urls[rir], imageFormula_(rApiR.urls[rir])], rApiR.urls[rir]);
              }
            } else if (imgRR) {
              var imgRRMax = rakutenImageUrlPreferMaxEx_(imgRR);
              pushImageRowIfNew_('楽天(採用候補)', [tr.rowNum, jan, setColR, '楽天(採用候補)', rDataR.url, 1, imgRRMax, imageFormula_(imgRRMax)], imgRRMax);
            } else {
              out.push([tr.rowNum, jan, setColR, '楽天(採用候補)', rDataR.url, 1, '(シートからURL抽出なし・Ichiba APIも0件)', '']);
            }
            Utilities.sleep(120);
          }
        }
      }
    }

    if (!byJan[jan] || !byJan[jan].yahooBySet) {
      if (yahooOk) {
        out.push([tr.rowNum, jan, setQty != null ? setQty : '', 'Yahoo!(採用候補)', '', '', 'モール横断に当該JANなし', '']);
        Logger.log('[競合画像テスト] Yahoo!(採用候補) モール横断にJANなし マスタ行=' + tr.rowNum + ' JAN=' + jan);
      }
    } else {
      var yReps = pickCrossMallRepresentativesPerShopByPrice_(byJan[jan].yahooBySet, COMPETITOR_IMAGE_TEST_MAX_SHOPS_PER_MALL, extractYahooStoreIdFromShoppingUrl_);
      if (yReps.length === 0) {
        if (yahooOk) {
          out.push([tr.rowNum, jan, setQty != null ? setQty : '', 'Yahoo!(採用候補)', '', '', '店舗単位候補なし（URL未取得）', '']);
        }
        Logger.log('[競合画像テスト] Yahoo!(採用候補) 店舗代表0件 マスタ行=' + tr.rowNum + ' JAN=' + jan);
      } else {
        Logger.log('[競合画像テスト] Yahoo!(採用候補) 店舗代表=' + yReps.length + '／上限' + COMPETITOR_IMAGE_TEST_MAX_SHOPS_PER_MALL + '（税込昇順） JAN=' + jan + ' マスタ行=' + tr.rowNum);
        for (var yjx = 0; yjx < yReps.length; yjx++) {
          var yRep = yReps[yjx];
          var yDataY = yRep.data;
          var setDispY = parseInt(yRep.setKey, 10);
          var setColY = !isNaN(setDispY) ? setDispY : yRep.setKey;
          var imgYY = extractImageUrlFromCrossMallImageCell_(yDataY.imageCell);
          var icPrevYY = String(yDataY.imageCell || '').substring(0, 120);
          var yItemCodeY = extractYahooShoppingItemCodeFromUrl_(yDataY.url);
          Logger.log('[競合画像テスト] Yahoo shop=' + yRep.shopId + ' setKey=' + yRep.setKey + ' priceIncl=' + yDataY.priceIncl + ' マスタ行=' + tr.rowNum + ' JAN=' + jan + ' imageCell先頭=' + icPrevYY);
          if (yahooOk && yItemCodeY) {
            if (yahooItemLookupCallIndex > 0) Utilities.sleep(1100);
            yahooItemLookupCallIndex++;
            var yLookupY = fetchYahooShoppingItemLookupImageUrls_(yahooClientId, yItemCodeY);
            if (yLookupY.error) Logger.log('[競合画像テスト] Yahoo itemLookup JSON: ' + yLookupY.error + ' itemcode=' + yItemCodeY + ' shop=' + yRep.shopId);
            var yApiUrlsY = yLookupY.urls || [];
            if (yApiUrlsY.length) Logger.log('[競合画像テスト] Yahoo itemLookup(JSON/V3・600) 件数=' + yApiUrlsY.length + ' shop=' + yRep.shopId);
            if (yApiUrlsY.length > 0) {
              for (var yiy = 0; yiy < yApiUrlsY.length; yiy++) {
                pushImageRowIfNew_('Yahoo!(採用候補)', [tr.rowNum, jan, setColY, 'Yahoo!(採用候補)', yDataY.url, yiy + 1, yApiUrlsY[yiy], imageFormula_(yApiUrlsY[yiy])], yApiUrlsY[yiy]);
              }
            } else if (imgYY) {
              pushImageRowIfNew_('Yahoo!(採用候補)', [tr.rowNum, jan, setColY, 'Yahoo!(採用候補)', yDataY.url, 1, imgYY, imageFormula_(imgYY)], imgYY);
            } else {
              out.push([tr.rowNum, jan, setColY, 'Yahoo!(採用候補)', yDataY.url, 1, '(シートからURL抽出なし・itemLookupも0件)', '']);
            }
          } else if (yahooOk && !yItemCodeY) {
            if (imgYY) {
              pushImageRowIfNew_('Yahoo!(採用候補)', [tr.rowNum, jan, setColY, 'Yahoo!(採用候補)', yDataY.url, 1, imgYY, imageFormula_(imgYY)], imgYY);
            } else {
              out.push([tr.rowNum, jan, setColY, 'Yahoo!(採用候補)', yDataY.url, 1, '(シートからURL抽出なし・itemLookupも0件)', '']);
            }
          } else if (!yahooOk) {
            if (imgYY) {
              pushImageRowIfNew_('Yahoo!(採用候補)', [tr.rowNum, jan, setColY, 'Yahoo!(採用候補)', yDataY.url, 1, imgYY, imageFormula_(imgYY)], imgYY);
            } else {
              out.push([tr.rowNum, jan, setColY, 'Yahoo!(採用候補)', yDataY.url, 1, '(YAHOO_SHOPPING_CLIENT_ID未設定・シートからURL抽出なし)', '']);
            }
          }
        }
      }
    }
  }

  // サブ採用レ点の復元: 採用ログ ＋（破棄前の）現行B-③レ点をマージ
  var adoptMap = loadSubImageAdoptKeysFromLog_(ss);
  var existingOutSheet = ss.getSheetByName(outputSheetName);
  if (existingOutSheet) {
    adoptMap = mergeSubAdoptKeysFromB3Sheet_(existingOutSheet, adoptMap);
  }
  var enriched = enrichCompetitorImageOutWithSubAdoptColumns_(out, adoptMap);
  var nCols = (enriched[0] && enriched[0].length) ? enriched[0].length : 8;

  var outSheet = existingOutSheet || ss.insertSheet(outputSheetName);
  outSheet.clear();
  if (enriched.length > 1) {
    outSheet.getRange(1, 1, enriched.length, nCols).setValues(enriched);
    outSheet.setFrozenRows(1);
    try {
      var ckCol = enriched[0].indexOf(B3_SUB_ADOPT_CK_HEADER) + 1;
      if (ckCol > 0) {
        outSheet.getRange(2, ckCol, enriched.length - 1, 1).insertCheckboxes();
      }
    } catch (eCk) {
      Logger.log('[競合画像] サブ採用CKチェックボックス設定スキップ: ' + eCk);
    }
    try { outSheet.autoResizeColumns(1, Math.min(nCols, 15)); } catch (e2) {}
  } else {
    outSheet.getRange(1, 1, 1, nCols).setValues([enriched[0]]);
    outSheet.setFrozenRows(1);
  }
  // 採用のみログへ書き戻し（新一覧に残ったレ点だけ＝軽い）
  try {
    rewriteSubImageAdoptLogFromB3Out_(ss, enriched);
  } catch (eLog) {
    Logger.log('[競合画像] サブ画像採用ログ更新スキップ: ' + eLog);
  }
  Logger.log('[競合画像] 出力データ行数=' + (enriched.length - 1) + ' 画像一意キー数=' + Object.keys(seenImageMeta).length + ' シート=' + outputSheetName +
    ' サブ採用復元キー=' + Object.keys(adoptMap).length);
  ui.alert('「' + outputSheetName + '」に出力しました（データ行: ' + Math.max(0, enriched.length - 1) + '）。サブ採用CKは採用ログから復元しています。');
  try { SpreadsheetApp.getActive().toast(menuTag + ' 完了（' + Math.max(0, enriched.length - 1) + ' 行）', menuTag, 8); } catch (toastE) {}
}

/** @param {string} jan
 *  @param {string} url
 *  @return {string} */
function b3SubAdoptKey_(jan, url) {
  return String(jan || '').trim() + '\t' + String(url || '').trim();
}

/**
 * サブ画像採用ログから (JAN+URL) → true のマップを読む。
 * @param {Spreadsheet} ss
 * @return {Object.<string, boolean>}
 */
function loadSubImageAdoptKeysFromLog_(ss) {
  var map = {};
  var sh = ss.getSheetByName(COMPETITOR_IMAGE_SUB_ADOPT_LOG_SHEET_NAME);
  if (!sh || sh.getLastRow() < 2) return map;
  var values = sh.getDataRange().getValues();
  var header = values[0];
  var iJan = header.indexOf('JAN');
  var iUrl = header.indexOf('画像URL');
  if (iJan < 0 || iUrl < 0) return map;
  for (var i = 1; i < values.length; i++) {
    var jan = String(values[i][iJan] || '').trim();
    var url = String(values[i][iUrl] || '').trim();
    if (jan && url.indexOf('http') === 0) {
      map[b3SubAdoptKey_(jan, url)] = true;
    }
  }
  Logger.log('[競合画像] サブ画像採用ログ読込 件数=' + Object.keys(map).length);
  return map;
}

/**
 * B-③シート上のサブ採用CKレ点を map にマージ。
 * @param {Sheet} sheet
 * @param {Object.<string, boolean>} map
 * @return {Object.<string, boolean>}
 */
function mergeSubAdoptKeysFromB3Sheet_(sheet, map) {
  map = map || {};
  if (!sheet || sheet.getLastRow() < 2) return map;
  var values = sheet.getDataRange().getValues();
  var header = values[0];
  var iJan = header.indexOf('JAN');
  var iUrl = header.indexOf('画像URL');
  var iCk = header.indexOf(B3_SUB_ADOPT_CK_HEADER);
  if (iJan < 0 || iUrl < 0 || iCk < 0) return map;
  var n = 0;
  for (var i = 1; i < values.length; i++) {
    var ck = values[i][iCk];
    var on = (ck === true || String(ck).toUpperCase() === 'TRUE');
    if (!on) continue;
    var jan = String(values[i][iJan] || '').trim();
    var url = String(values[i][iUrl] || '').trim();
    if (jan && url.indexOf('http') === 0) {
      map[b3SubAdoptKey_(jan, url)] = true;
      n++;
    }
  }
  Logger.log('[競合画像] B-③既存サブ採用CKマージ 件数=' + n);
  return map;
}

/**
 * out (A–H) に右列を付け、採用ログに合う行はサブ採用CK=true。
 * @param {Array.<Array>} out
 * @param {Object.<string, boolean>} adoptMap
 * @return {Array.<Array>}
 */
function enrichCompetitorImageOutWithSubAdoptColumns_(out, adoptMap) {
  adoptMap = adoptMap || {};
  if (!out || !out.length) return out;
  var header = (out[0] || []).slice(0, 8).concat(B3_SUB_EXTRA_HEADERS);
  var enriched = [header];
  for (var ri = 1; ri < out.length; ri++) {
    var row = (out[ri] || []).slice(0, 8);
    while (row.length < 8) row.push('');
    var jan = String(row[1] || '').trim();
    var url = String(row[6] || '').trim();
    var adopted = (url.indexOf('http') === 0 && adoptMap[b3SubAdoptKey_(jan, url)]) ? true : false;
    // 商品名〜参照clusterは空（Python curate が埋める）。メモ空。
    // EXTRA: 商品名,自動判定,自動理由,意図ラベル,OCR要約,参照themeId,参照phaseOrder,参照cluster,サブ採用CK,メモ
    enriched.push(row.concat(['', '', '', '', '', '', '', '', adopted, '']));
  }
  return enriched;
}

/**
 * 採用レ点のみを「サブ画像採用ログ」へ書き出す（全候補は残さない）。
 * @param {Spreadsheet} ss
 * @param {Array.<Array>} enrichedOut ヘッダー付きB-③相当
 */
function rewriteSubImageAdoptLogFromB3Out_(ss, enrichedOut) {
  if (!enrichedOut || enrichedOut.length < 2) {
    var emptySh = ss.getSheetByName(COMPETITOR_IMAGE_SUB_ADOPT_LOG_SHEET_NAME);
    if (emptySh) {
      emptySh.clear();
      emptySh.getRange(1, 1, 1, 8).setValues([['JAN', '商品名', '区分', 'ASINまたは商品URL', '画像番号', '画像URL', 'メモ', '更新日時']]);
    }
    return;
  }
  var header = enrichedOut[0];
  var iJan = header.indexOf('JAN');
  var iName = header.indexOf('商品名');
  var iKind = header.indexOf('区分');
  var iKey = header.indexOf('ASINまたは商品URL');
  var iIdx = header.indexOf('画像番号');
  var iUrl = header.indexOf('画像URL');
  var iCk = header.indexOf(B3_SUB_ADOPT_CK_HEADER);
  var iMemo = header.indexOf('メモ');
  if (iJan < 0 || iUrl < 0 || iCk < 0) return;

  var now = Utilities.formatDate(new Date(), Session.getScriptTimeZone() || 'Asia/Tokyo', 'yyyy-MM-dd HH:mm:ss');
  var logRows = [['JAN', '商品名', '区分', 'ASINまたは商品URL', '画像番号', '画像URL', 'メモ', '更新日時']];
  for (var i = 1; i < enrichedOut.length; i++) {
    var r = enrichedOut[i];
    var ck = r[iCk];
    var on = (ck === true || String(ck).toUpperCase() === 'TRUE');
    if (!on) continue;
    var url = String(r[iUrl] || '').trim();
    if (url.indexOf('http') !== 0) continue;
    logRows.push([
      String(r[iJan] || '').trim(),
      iName >= 0 ? String(r[iName] || '') : '',
      iKind >= 0 ? String(r[iKind] || '') : '',
      iKey >= 0 ? String(r[iKey] || '') : '',
      iIdx >= 0 ? r[iIdx] : '',
      url,
      iMemo >= 0 ? String(r[iMemo] || '') : '',
      now
    ]);
  }

  var logSh = ss.getSheetByName(COMPETITOR_IMAGE_SUB_ADOPT_LOG_SHEET_NAME);
  if (!logSh) logSh = ss.insertSheet(COMPETITOR_IMAGE_SUB_ADOPT_LOG_SHEET_NAME);
  else logSh.clear();
  logSh.getRange(1, 1, logRows.length, 8).setValues(logRows);
  logSh.setFrozenRows(1);
  try { logSh.autoResizeColumns(1, 8); } catch (e3) {}
  Logger.log('[競合画像] サブ画像採用ログ更新 採用行=' + (logRows.length - 1));
}

/**
 * 開発用: 出力先「競合画像取得テスト」。通常UIの99メニューからは削除済み。GASエディタやカスタムメニューから呼ぶ。
 */
function menuTestCompetitorImageUrlsOutput() {
  menuTestCompetitorImageUrlsOutputImpl_({
    outputSheetName: COMPETITOR_IMAGE_TEST_OUTPUT_SHEET_NAME,
    skipAmazonBlock: false,
    menuTag: '競合画像(開発)'
  });
}

/**
 * モール横断セット数判定シートの結果を元に、マスタでレ点のJANについて「抜けている統合セット数」の行を挿入する。
 * 挿入位置は既存のレ点行のセット数並びの間（抜けセット数より大きい最初の行の上）。
 * 新規行には「2行目」（子SKU用テンプレート）をテンプレートとして反映: A,B,D はその行の数式、C はレ点、Q列以降はその行の数式。JAN・A.セット商品数も設定。
 * 事前に「モール横断 セット数統合判定」を実行し、続けて「抜けセット数行の挿入」を実行する想定。
 */
function menuInsertMissingSetCountRows() {
  Logger.log('[抜けセット数行] ========== 開始 ==========');
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var bScopeIns = getBRunScope_(ss);
  var masterSheet = ss.getSheetByName(MASTER_SHEET_NAME);
  var crossSheet = ss.getSheetByName(CROSS_MALL_SET_COUNT_SHEET_NAME);
  Logger.log('[抜けセット数行] シート取得 マスタ=' + (masterSheet ? MASTER_SHEET_NAME : 'null') + ' モール横断=' + (crossSheet ? CROSS_MALL_SET_COUNT_SHEET_NAME : 'null'));
  if (!masterSheet) {
    bAlertSafe_('▼商品マスタ(人間作業用) シートが見つかりません。');
    return;
  }
  if (!crossSheet) {
    bAlertSafe_('シート「' + CROSS_MALL_SET_COUNT_SHEET_NAME + '」が見つかりません。先にモール横断 セット数統合判定を実行してください。');
    return;
  }
  try {
  var crossValues = crossSheet.getDataRange().getValues();
  Logger.log('[抜けセット数行] モール横断シート 取得行数=' + (crossValues ? crossValues.length : 0));
  if (crossValues.length < 2) {
    bAlertSafe_('シート「' + CROSS_MALL_SET_COUNT_SHEET_NAME + '」にデータがありません。');
    return;
  }
  var masterValues = masterSheet.getDataRange().getValues();
  Logger.log('[抜けセット数行] マスタシート 取得行数=' + (masterValues ? masterValues.length : 0));
  var headerRowIdx = -1;
  for (var hr = 0; hr < Math.min(masterValues.length, 20); hr++) {
    if (masterValues[hr].indexOf(ANCHOR_HEADER_NAME) !== -1) { headerRowIdx = hr; break; }
  }
  if (headerRowIdx === -1) {
    Logger.log('[抜けセット数行] ヘッダー未検出 アンカー=' + ANCHOR_HEADER_NAME);
    bAlertSafe_('マスタのヘッダー行（ASINコード）が見つかりません。');
    return;
  }
  Logger.log('[抜けセット数行] ヘッダー検出 行(0-based)=' + headerRowIdx + ' 行(1-based)=' + (headerRowIdx + 1));
  var masterColMap = getColumnIndexMap(masterValues[headerRowIdx]);
  var colJan = masterColMap['JANコード'];
  var colSetQty = masterColMap[COL_MASTER_TOTAL_QTY];
  var colCheckbox = masterColMap[CHECKBOX_HEADER_NAME];
  if (colJan === undefined || colSetQty === undefined || colCheckbox === undefined) {
    bAlertSafe_('マスタに JANコード または ' + COL_MASTER_TOTAL_QTY + ' または ' + CHECKBOX_HEADER_NAME + ' がありません。');
    return;
  }
  var numMasterCols = (masterValues[headerRowIdx] || []).length;
  Logger.log('[抜けセット数行] マスタ 総行数=' + masterValues.length + ' ヘッダー行(0-based)=' + headerRowIdx + ' colJan=' + colJan + ' colSetQty=' + colSetQty + ' colCheckbox=' + colCheckbox + ' numMasterCols=' + numMasterCols);
  Logger.log('[抜けセット数行] 列(1-based) JAN=' + (colJan + 1) + ' セット数=' + (colSetQty + 1) + ' レ点=' + (colCheckbox + 1));

  // モール横断シートから JAN → 統合セット数（ユニーク・数値）のマップを構築
  Logger.log('[抜けセット数行] --- モール横断シート解析 ---');
  var integratedSetByJan = {};
  var currentJan = '';
  for (var r = 0; r < crossValues.length; r++) {
    var row = crossValues[r];
    var cell0 = (row[0] != null) ? String(row[0]).trim() : '';
    if (cell0.indexOf('JAN:') === 0) {
      currentJan = cell0.replace(/^JAN:\s*/, '').trim();
      if (currentJan.length >= 8 && !integratedSetByJan[currentJan]) integratedSetByJan[currentJan] = {};
      continue;
    }
    if ((row[1] != null) && String(row[1]).trim() === 'モール') continue;
    if (currentJan.length < 8) continue;
    var is24Col = (row.length >= 24);
    var colSetCount = is24Col ? 17 : 16;
    var setCount = (row[colSetCount] !== '' && row[colSetCount] != null) ? parseInt(Number(row[colSetCount]), 10) : NaN;
    if (!isNaN(setCount) && setCount >= 1 && setCount <= 999) {
      if (!integratedSetByJan[currentJan]) integratedSetByJan[currentJan] = {};
      integratedSetByJan[currentJan][setCount] = true;
    }
  }
  var integratedJans = Object.keys(integratedSetByJan);
  Logger.log('[抜けセット数行] モール横断シート解析済み JAN数=' + integratedJans.length);
  for (var ij = 0; ij < integratedJans.length; ij++) {
    var jj = integratedJans[ij];
    var sets = Object.keys(integratedSetByJan[jj]).map(function (k) { return parseInt(k, 10); }).sort(function (a, b) { return a - b; });
    Logger.log('[抜けセット数行] JAN=' + jj + ' 統合セット数=[' + sets.join(',') + ']');
  }
  Logger.log('[抜けセット数行] --- マスタレ点行収集 ---');

  // マスタでレ点行を JAN ごとに収集（rowNum 1-based, setQty 昇順）
  var rowsByJan = {};
  for (var mr = headerRowIdx + 1; mr < masterValues.length; mr++) {
    if (!bRunAllowMasterRow_(mr, masterValues[mr][colCheckbox], bScopeIns)) continue;
    var jan = String(masterValues[mr][colJan] || '').trim();
    if (!jan || !integratedSetByJan[jan]) continue;
    var sq = masterValues[mr][colSetQty];
    var setQty = (sq !== '' && sq != null) ? (typeof sq === 'number' ? sq : parseInt(String(sq).replace(/[^0-9]/g, ''), 10)) : null;
    if (isNaN(setQty) || setQty < 1) setQty = null;
    if (!rowsByJan[jan]) rowsByJan[jan] = [];
    rowsByJan[jan].push({ rowNum: mr + 1, setQty: setQty });
  }
  for (var j in rowsByJan) {
    rowsByJan[j].sort(function (a, b) {
      var na = (a.setQty != null) ? a.setQty : 999999;
      var nb = (b.setQty != null) ? b.setQty : 999999;
      return na - nb;
    });
  }
  var rowsByJanKeys = Object.keys(rowsByJan);
  Logger.log('[抜けセット数行] マスタレ点行 対象JAN数=' + rowsByJanKeys.length);
  for (var rj = 0; rj < rowsByJanKeys.length; rj++) {
    var jn = rowsByJanKeys[rj];
    var lst = rowsByJan[jn];
    var qtys = lst.map(function (x) { return x.setQty != null ? x.setQty : 'null'; });
    Logger.log('[抜けセット数行] JAN=' + jn + ' 行数=' + lst.length + ' 行番号(1-based)=' + lst.map(function (x) { return x.rowNum; }).join(',') + ' setQty=' + qtys.join(','));
  }
  Logger.log('[抜けセット数行] --- 挿入位置決定 ---');

  // 抜けセット数ごとに挿入位置を決定（安定性優先: 末尾追記）
  var inserts = [];
  var insertedJanSet = {};
  var jans = Object.keys(rowsByJan);
  for (var ji = 0; ji < jans.length; ji++) {
    var jan = jans[ji];
    var existing = {};
    var list = rowsByJan[jan];
    for (var li = 0; li < list.length; li++) {
      var q = list[li].setQty;
      if (q != null) existing[q] = true;
    }
    var integrated = Object.keys(integratedSetByJan[jan]).map(function (k) { return parseInt(k, 10); }).filter(function (n) { return !isNaN(n) && n >= 1; });
    // 末尾追記の基準: JANブロック（レ点行）の最大行の次
    var maxRowNum = null;
    for (var li = 0; li < list.length; li++) {
      var rn = list[li].rowNum;
      if (maxRowNum == null || rn > maxRowNum) maxRowNum = rn;
    }
    if (maxRowNum == null) continue;
    var appendBeforeRow = maxRowNum + 1;
    for (var ii = 0; ii < integrated.length; ii++) {
      var n = integrated[ii];
      if (existing[n]) continue;
      inserts.push({ insertBeforeRow: appendBeforeRow, jan: jan, setCount: n });
      insertedJanSet[jan] = true;
    }
  }
  if (inserts.length === 0) {
    Logger.log('[抜けセット数行] 挿入対象0件のため終了');
    SpreadsheetApp.getActive().toast('抜けているセット数はありませんでした。', '抜けセット数行', 4);
    return;
  }
  // insertBeforeRow が同じ（末尾追記）の場合は setCount を大きい順に挿入すると、最終的に小さい順で並ぶ
  inserts.sort(function (a, b) {
    if (b.insertBeforeRow !== a.insertBeforeRow) return b.insertBeforeRow - a.insertBeforeRow;
    return b.setCount - a.setCount;
  });
  Logger.log('[抜けセット数行] 挿入リスト 件数=' + inserts.length + ' (下の行から挿入)');
  for (var is = 0; is < inserts.length; is++) {
    var x = inserts[is];
    Logger.log('[抜けセット数行]   [' + (is + 1) + '] insertBeforeRow=' + x.insertBeforeRow + ' JAN=' + x.jan + ' setCount=' + x.setCount);
  }
  Logger.log('[抜けセット数行] --- 行挿入・テンプレコピー ---');

  var templateRow1Based = 2;
  // テンプレ2行目の数式を「⇒AI作業エリア」まで全コピー（列追加で右側にSKU列があっても壊れない）
  var colAiArea = masterColMap['⇒AI作業エリア'];
  var FORMULA_TMPL_COL_START = 1;
  var FORMULA_TMPL_COL_END = (colAiArea !== undefined) ? (colAiArea + 1) : numMasterCols;
  FORMULA_TMPL_COL_END = Math.min(FORMULA_TMPL_COL_END, numMasterCols);
  var formulaTmplNumCols = FORMULA_TMPL_COL_END - FORMULA_TMPL_COL_START + 1;
  Logger.log('[抜けセット数行] テンプレート行 1-based=' + templateRow1Based + ' (子SKU用・2行目)');
  var EP_COL_START = 5;
  var EP_COL_END = 16;
  var epNumCols = EP_COL_END - EP_COL_START + 1;
  Logger.log('[抜けセット数行] コピー範囲 A-B: 直前行参照の連番数式(挿入行+以下も更新), C-D: テンプレ数式, E-P: 数式はテンプレ/値は同JAN他子SKU(直前行), Q-HJ: テンプレ数式。最後にJAN・セット数・レ点を設定');
  for (var ii = 0; ii < inserts.length; ii++) {
    var ins = inserts[ii];
    Logger.log('[抜けセット数行] 挿入 ' + (ii + 1) + '/' + inserts.length + ' insertBeforeRow=' + ins.insertBeforeRow + ' JAN=' + ins.jan + ' setCount=' + ins.setCount + ' templateRow=' + templateRow1Based);
    masterSheet.insertRowsBefore(ins.insertBeforeRow, 1);
    var newRow = ins.insertBeforeRow;
    Logger.log('[抜けセット数行]   行' + ins.insertBeforeRow + 'の上に1行挿入 → 新規行(1-based)=' + newRow);

    // まずテンプレ2行目の数式を「⇒AI作業エリア」まで全コピー（子SKU/親SKU列が右側でも空にならない）
    if (FORMULA_TMPL_COL_END >= FORMULA_TMPL_COL_START) {
      var srcAll = masterSheet.getRange(templateRow1Based, FORMULA_TMPL_COL_START, 1, formulaTmplNumCols);
      var dstAll = masterSheet.getRange(newRow, FORMULA_TMPL_COL_START, 1, formulaTmplNumCols);
      srcAll.copyTo(dstAll, SpreadsheetApp.CopyPasteType.PASTE_FORMULA, false);
      Logger.log('[抜けセット数行]   テンプレ行' + templateRow1Based + 'から 列' + FORMULA_TMPL_COL_START + '-' + FORMULA_TMPL_COL_END + ' を数式コピー（⇒AI作業エリアまで）');
    }

    // A-B: 挿入行は直前行参照の連番数式を直接設定。挿入行の下は1回の範囲書きで連番数式を設定。
    masterSheet.getRange(newRow, 1).setFormula('=A' + (newRow - 1) + '+1');
    masterSheet.getRange(newRow, 2).setFormula('="No."&A' + newRow);
    var lastRow = masterSheet.getLastRow();
    if (newRow + 1 <= lastRow) {
      var numRowsBelow = lastRow - newRow;
      var abFormulas = [];
      for (var r = 0; r < numRowsBelow; r++) {
        var rowNum = newRow + 1 + r;
        abFormulas.push(['=A' + (newRow + r) + '+1', '="No."&A' + rowNum]);
      }
      masterSheet.getRange(newRow + 1, 1, numRowsBelow, 2).setFormulas(abFormulas);
      Logger.log('[抜けセット数行]   A-B列 行' + (newRow + 1) + '-' + lastRow + ' を1回の範囲書きで更新(行数=' + numRowsBelow + ')');
    }
    // C列（レ点）は値で上書き（テンプレの式/値に依存しない）
    masterSheet.getRange(newRow, 3).setValue(true);
    // E-P: 数式はテンプレ2行目から、値のみの列は同JANの他子SKU（挿入直前の行）からコピー
    var sourceRow = newRow - 1;
    var rEp = masterSheet.getRange(templateRow1Based, EP_COL_START, 1, epNumCols);
    var formulasEp = rEp.getFormulas();
    var valuesSource = (sourceRow >= 1) ? masterSheet.getRange(sourceRow, EP_COL_START, 1, epNumCols).getValues()[0] : [];
    var epFormulaCount = 0;
    var epValueCount = 0;
    for (var ec = 0; ec < epNumCols; ec++) {
      if (formulasEp && formulasEp[0] && formulasEp[0][ec]) {
        masterSheet.getRange(newRow, EP_COL_START + ec).setFormula(formulasEp[0][ec]);
        epFormulaCount++;
      } else if (valuesSource[ec] !== undefined && valuesSource[ec] !== null && valuesSource[ec] !== '') {
        masterSheet.getRange(newRow, EP_COL_START + ec).setValue(valuesSource[ec]);
        epValueCount++;
      }
    }
    if (epFormulaCount > 0 || epValueCount > 0) Logger.log('[抜けセット数行]   E-P(5-16列) テンプレ数式' + epFormulaCount + '件・同JAN他子SKU(行' + sourceRow + ')値' + epValueCount + '件コピー');
    // 全コピー後にJAN・セット数・レ点を設定（上書きで正しい値にする）
    masterSheet.getRange(newRow, colJan + 1).setValue(ins.jan);
    masterSheet.getRange(newRow, colSetQty + 1).setValue(ins.setCount);
    Logger.log('[抜けセット数行]   新規行 列' + (colJan + 1) + '(JAN)=' + ins.jan + ' 列' + (colSetQty + 1) + '(セット数)=' + ins.setCount + ' を設定');
    if (colCheckbox !== undefined) {
      masterSheet.getRange(newRow, colCheckbox + 1).setValue(true);
      Logger.log('[抜けセット数行]   列' + (colCheckbox + 1) + ' レ点をONに設定');
    }
  }
  Logger.log('[抜けセット数行] ========== 挿入完了 挿入行数=' + inserts.length + ' ==========');
  SpreadsheetApp.getActive().toast('抜けセット数行を ' + inserts.length + ' 行挿入しました。', '抜けセット数行', 4);
  if (inserts.length > 0) {
    // 追加行の amazon カテゴリー空欄を先に埋める（誤商品価格確定の後工程切り分けを早めるため）
    var fillAmazonCat = getBoolScriptProperty_('B_CROSSMALL_FILL_AMAZON_CATEGORY_AFTER_INSERT_ENABLED', true);
    if (fillAmazonCat) {
      try {
        var onlyJans = Object.keys(insertedJanSet);
        Logger.log('[抜けセット数行] Amazonカテゴリー自動入力 onlyJans=' + onlyJans.length);
        SpreadsheetApp.getActive().toast('Amazonカテゴリー自動入力中...', '抜けセット数行', 3);
        menuFillAmazonCategoryByGemini(onlyJans);
      } catch (e) {
        Logger.log('[抜けセット数行] Amazonカテゴリー自動入力エラー: ' + (e && e.message));
      }
    } else {
      Logger.log('[抜けセット数行] Amazonカテゴリー自動入力スキップ（フラグOFF）');
    }

    Logger.log('[抜けセット数行] モール横断セット数判定シートの既存データをマスタに反映します');
    SpreadsheetApp.getActive().toast('モール横断結果をマスタに反映します...', '抜けセット数行', 3);
    try {
      menuApplyCrossMallResultToRakutenYahooMaster();
      SpreadsheetApp.getActive().toast('抜けセット数行の挿入と反映が完了しました。', '抜けセット数行', 5);
    } catch (e) {
      Logger.log('[抜けセット数行] モール横断/反映でエラー: ' + (e && e.message));
      if (e && e.stack) Logger.log('[抜けセット数行] スタック: ' + e.stack);
      SpreadsheetApp.getActive().toast('挿入は完了しましたが、モール横断反映でエラー: ' + (e && e.message), '抜けセット数行', 8);
    }
  }
  } catch (e) {
    Logger.log('[抜けセット数行] エラー: ' + (e && e.message));
    if (e && e.stack) Logger.log('[抜けセット数行] スタック: ' + e.stack);
    throw e;
  }
}

/**
 * ④楽天Yahoo!リサーチ一括（競合価格⇒セット数抜け追加）: モール横断 → 抜けセット数行挿入 → モール横断結果をマスタに反映。
 * 価格提案は含めない。確認・修正後に「楽天Yahoo!販売価格を提案（CPO）」を別メニューで実行する。
 * レ点を付けた状態で実行。30分制限を考慮し、JAN数が多い場合は分割実行を推奨。
 */
function menuResearchBatchCrossMallAndPropose() {
  var ui = bTryUi_();
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var scope = getBRunScope_(ss);
  if (scope.active && scope.emptyHalt) {
    Logger.log('[B.SCOPE] Step2 skip emptyHalt');
    return;
  }
  var onlyJans = null;
  if (scope.active) {
    onlyJans = [];
    var masterSheet = ss.getSheetByName(MASTER_SHEET_NAME);
    if (masterSheet) {
      var mv = masterSheet.getDataRange().getValues();
      var headerRowIdx = -1;
      for (var hr = 0; hr < Math.min(mv.length, 25); hr++) {
        if ((mv[hr] || []).indexOf(ANCHOR_HEADER_NAME) !== -1) { headerRowIdx = hr; break; }
      }
      if (headerRowIdx >= 0) {
        var cmap = getColumnIndexMap(mv[headerRowIdx]);
        var colJan = cmap['JANコード'];
        if (colJan !== undefined) {
          var seen = {};
          for (var r0 in scope.parentRowSet) {
            if (!scope.parentRowSet.hasOwnProperty(r0)) continue;
            var jan = String(mv[Number(r0)][colJan] || '').trim();
            if (jan.length >= 8 && !seen[jan]) { seen[jan] = true; onlyJans.push(jan); }
          }
        }
      }
    }
    Logger.log('[B.SCOPE] Step2 onlyJans=' + onlyJans.join(','));
    if (onlyJans.length === 0) {
      Logger.log('[B.SCOPE] Step2 skip no JAN in inserted parents');
      return;
    }
  }
  try { SpreadsheetApp.getActive().toast('1/3 モール横断 セット数統合判定を実行中...', '楽天Yahoo!リサーチ一括', 3); } catch (t1) {}
  try {
    menuTestCrossMallSetCountJudge(onlyJans);
  } catch (e) {
    if (ui) ui.alert('モール横断 セット数統合判定でエラー: ' + (e && e.message));
    else Logger.log('[モール横断] ' + (e && e.message));
    return;
  }
  try { SpreadsheetApp.getActive().toast('2/3 抜けセット数行の挿入を実行中...', '楽天Yahoo!リサーチ一括', 3); } catch (t2) {}
  try {
    menuInsertMissingSetCountRows();
  } catch (e) {
    if (ui) ui.alert('抜けセット数行の挿入でエラー: ' + (e && e.message));
    else Logger.log('[抜けセット] ' + (e && e.message));
    return;
  }
  try { SpreadsheetApp.getActive().toast('3/3 モール横断結果をマスタに反映中...', '楽天Yahoo!リサーチ一括', 3); } catch (t3) {}
  try {
    menuApplyCrossMallResultToRakutenYahooMaster();
  } catch (e) {
    if (ui) ui.alert('モール横断結果の反映でエラー: ' + (e && e.message));
    else Logger.log('[横断反映] ' + (e && e.message));
    return;
  }
  try { SpreadsheetApp.getActive().toast('リサーチ一括が完了しました。競合・セット数を確認し、対象行を選択して「楽天Yahoo!販売価格を提案」を実行してください。', '楽天Yahoo!リサーチ一括', 8); } catch (t4) {}
}

/**
 * Yahoo! ショッピング 商品検索 API v3 で jan_code 検索し 1 件目の価格を取得する。
 * Script Properties: YAHOO_SHOPPING_CLIENT_ID。
 * @param {string} clientId - appid（Client ID）
 * @param {string} janCode - JAN コード
 * @return {{ price: number|null, error: string|null, rawCount: number }}
 */
function fetchYahooShoppingItemPriceByJan(clientId, janCode) {
  var result = { price: null, error: null, rawCount: 0 };
  if (!clientId || !clientId.trim()) {
    result.error = 'YAHOO_SHOPPING_CLIENT_ID が未設定です。';
    return result;
  }
  var url = 'https://shopping.yahooapis.jp/ShoppingWebService/V3/itemSearch?appid=' + encodeURIComponent(clientId) + '&jan_code=' + encodeURIComponent(janCode) + '&results=1';
  try {
    var res = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
    var code = res.getResponseCode();
    var text = res.getContentText();
    if (code !== 200) {
      result.error = 'HTTP ' + code + ' ' + (text ? text.substring(0, 200) : '');
      Logger.log('[Yahoo!API] ' + result.error);
      return result;
    }
    var json = JSON.parse(text);
    var hits = (json.hits || []);
    result.rawCount = hits.length;
    if (hits.length > 0 && hits[0].price != null) {
      result.price = parseInt(hits[0].price, 10);
      if (isNaN(result.price)) result.price = null;
    }
    return result;
  } catch (e) {
    result.error = e.message || String(e);
    Logger.log('[Yahoo!API] 例外: ' + result.error);
    return result;
  }
}

/**
 * Yahoo! ショッピング API v3 で query（キーワード）検索し、複数件（最大 maxResults）を取得する。
 * JAN検索で0件のときのフォールバック用。ログは [Yahoo!セット数] で検索可能。
 * @param {string} clientId - appid（Client ID）
 * @param {string} query - 検索キーワード（商品名など）
 * @param {number} [maxResults=20] - 取得件数（最大50）
 * @return {{ error: string|null, hits: Array<{ name: string, price: number|null, url: string, imageUrl: string, shippingCode: number }> }}
 */
function fetchYahooShoppingItemsByQuery(clientId, query, maxResults) {
  var result = { error: null, hits: [] };
  if (!clientId || !clientId.trim()) {
    result.error = 'YAHOO_SHOPPING_CLIENT_ID が未設定です。';
    return result;
  }
  if (!query || !String(query).trim()) {
    result.error = 'query が空です。';
    return result;
  }
  var limit = Math.min(Math.max(Number(maxResults) || 20, 1), 50);
  var url = 'https://shopping.yahooapis.jp/ShoppingWebService/V3/itemSearch?appid=' + encodeURIComponent(clientId) + '&query=' + encodeURIComponent(String(query).trim()) + '&results=' + limit;
  try {
    var res = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
    var code = res.getResponseCode();
    var text = res.getContentText();
    if (code !== 200) {
      result.error = 'HTTP ' + code + ' ' + (text ? text.substring(0, 200) : '');
      Logger.log('[Yahoo!セット数] API query="' + (String(query).substring(0, 50) + (query.length > 50 ? '...' : '')) + '" ' + result.error);
      return result;
    }
    var json = JSON.parse(text);
    var rawHits = (json.hits || []);
    for (var i = 0; i < rawHits.length; i++) {
      var h = rawHits[i];
      var name = (h.name != null) ? String(h.name) : '';
      var price = (h.price != null) ? parseInt(h.price, 10) : null;
      if (isNaN(price)) price = null;
      var itemUrl = (h.url != null) ? String(h.url) : '';
      var imageUrl = '';
      if (h.image && h.image.medium != null) imageUrl = String(h.image.medium || '');
      if (!imageUrl && h.image && h.image.small != null) imageUrl = String(h.image.small || '');
      if (!imageUrl && h.image && h.image.id != null) imageUrl = String(h.image.id || '');
      var shippingCode = (h.shipping && h.shipping.code != null) ? parseInt(h.shipping.code, 10) : 1;
      if (isNaN(shippingCode)) shippingCode = 1;
      result.hits.push({ name: name, price: price, url: itemUrl, imageUrl: imageUrl, shippingCode: shippingCode });
    }
    Logger.log('[Yahoo!セット数] API query="' + (String(query).substring(0, 50) + (query.length > 50 ? '...' : '')) + '" 取得件数=' + result.hits.length);
    return result;
  } catch (e) {
    result.error = e.message || String(e);
    Logger.log('[Yahoo!セット数] API 例外 query="' + (String(query).substring(0, 30) + '...") ') + result.error);
    return result;
  }
}

/**
 * Yahoo! ショッピング API v3 itemSearch（カテゴリ／ブランド選定用）。
 * genreCategory / parentGenreCategories / brand / price / review を返す。
 * sort 例: -review_count（売れ筋近似） / +price（安い順）。sold 順は API 非対応。
 * @param {string} clientId
 * @param {{mode:string, value:string, results?:number, sort?:string, genreCategoryId?:string|number}} opts
 * @return {{error:string|null, hits:Array}}
 */
function fetchYahooShoppingItemSearchRich_(clientId, opts) {
  var result = { error: null, hits: [] };
  opts = opts || {};
  if (!clientId || !String(clientId).trim()) {
    result.error = 'YAHOO_SHOPPING_CLIENT_ID が未設定です。';
    return result;
  }
  var value = opts.value != null ? String(opts.value).trim() : '';
  if (!value) {
    result.error = 'query/jan が空です。';
    return result;
  }
  var limit = Math.min(Math.max(Number(opts.results) || 20, 1), 50);
  var url = 'https://shopping.yahooapis.jp/ShoppingWebService/V3/itemSearch?appid=' +
    encodeURIComponent(String(clientId).trim());
  if (opts.mode === 'jan') {
    url += '&jan_code=' + encodeURIComponent(value);
  } else {
    url += '&query=' + encodeURIComponent(value);
  }
  url += '&results=' + limit;
  if (opts.sort) {
    url += '&sort=' + encodeURIComponent(String(opts.sort));
  }
  if (opts.genreCategoryId != null && String(opts.genreCategoryId).trim() !== '') {
    url += '&genre_category_id=' + encodeURIComponent(String(opts.genreCategoryId).trim());
  }
  try {
    var res = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
    var code = res.getResponseCode();
    var text = res.getContentText();
    if (code !== 200) {
      result.error = 'HTTP ' + code + ' ' + (text ? text.substring(0, 200) : '');
      Logger.log('[Yahoo!Rich] ' + result.error);
      return result;
    }
    var json = JSON.parse(text);
    var rawHits = json.hits || [];
    for (var i = 0; i < rawHits.length; i++) {
      var h = rawHits[i] || {};
      var price = (h.price != null) ? parseInt(h.price, 10) : null;
      if (isNaN(price)) price = null;
      var gc = h.genreCategory || {};
      var brand = h.brand || {};
      var review = h.review || {};
      var parents = [];
      var rawParents = h.parentGenreCategories || [];
      for (var pi = 0; pi < rawParents.length; pi++) {
        var pg = rawParents[pi] || {};
        parents.push({
          depth: pg.depth != null ? Number(pg.depth) : 0,
          id: pg.id != null ? String(pg.id) : '',
          name: pg.name != null ? String(pg.name) : ''
        });
      }
      result.hits.push({
        name: h.name != null ? String(h.name) : '',
        price: price,
        genreCategoryId: gc.id != null ? String(gc.id) : '',
        genreCategoryName: gc.name != null ? String(gc.name) : '',
        genreCategoryDepth: gc.depth != null ? Number(gc.depth) : 0,
        parentGenreCategories: parents,
        brandId: brand.id != null ? String(brand.id) : '',
        brandName: brand.name != null ? String(brand.name) : '',
        reviewCount: review.count != null ? Number(review.count) : 0
      });
    }
    return result;
  } catch (e) {
    result.error = e.message || String(e);
    Logger.log('[Yahoo!Rich] 例外: ' + result.error);
    return result;
  }
}

/**
 * Yahoo! ショッピング API v3 で jan_code 検索し、複数件（最大 maxResults）を取得する。セット別価格テスト用。
 * @param {string} clientId - appid（Client ID）
 * @param {string} janCode - JAN コード
 * @param {number} [maxResults=20] - 取得件数（最大50）
 * @return {{ error: string|null, hits: Array<{ name: string, price: number|null, url: string, imageUrl: string, shippingCode: number }> }}
 */
function fetchYahooShoppingItemsByJan(clientId, janCode, maxResults) {
  var result = { error: null, hits: [] };
  if (!clientId || !clientId.trim()) {
    result.error = 'YAHOO_SHOPPING_CLIENT_ID が未設定です。';
    return result;
  }
  var limit = Math.min(Math.max(Number(maxResults) || 20, 1), 50);
  var url = 'https://shopping.yahooapis.jp/ShoppingWebService/V3/itemSearch?appid=' + encodeURIComponent(clientId) + '&jan_code=' + encodeURIComponent(janCode) + '&results=' + limit;
  try {
    var res = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
    var code = res.getResponseCode();
    var text = res.getContentText();
    if (code !== 200) {
      result.error = 'HTTP ' + code + ' ' + (text ? text.substring(0, 200) : '');
      Logger.log('[Yahoo!API] ' + result.error);
      return result;
    }
    var json = JSON.parse(text);
    var rawHits = (json.hits || []);
    for (var i = 0; i < rawHits.length; i++) {
      var h = rawHits[i];
      var name = (h.name != null) ? String(h.name) : '';
      var price = (h.price != null) ? parseInt(h.price, 10) : null;
      if (isNaN(price)) price = null;
      var itemUrl = (h.url != null) ? String(h.url) : '';
      var imageUrl = '';
      if (h.image && h.image.medium != null) imageUrl = String(h.image.medium || '');
      if (!imageUrl && h.image && h.image.small != null) imageUrl = String(h.image.small || '');
      if (!imageUrl && h.image && h.image.id != null) imageUrl = String(h.image.id || '');
      var shippingCode = (h.shipping && h.shipping.code != null) ? parseInt(h.shipping.code, 10) : 1;
      if (isNaN(shippingCode)) shippingCode = 1;
      result.hits.push({ name: name, price: price, url: itemUrl, imageUrl: imageUrl, shippingCode: shippingCode });
    }
    return result;
  } catch (e) {
    result.error = e.message || String(e);
    Logger.log('[Yahoo!API] 例外: ' + result.error);
    return result;
  }
}

/**
 * Yahoo 商品ページURLまたは item-shopping CDN URL から itemLookup 用 itemcode（ストアID_商品キー）を抽出する。
 * @param {string} url
 * @return {string}
 */
function extractYahooShoppingItemCodeFromUrl_(url) {
  var s = String(url || '').trim();
  var m = s.match(/store\.shopping\.yahoo\.co\.jp\/([^\/]+)\/([^\/\?#]+)/i);
  if (m) return m[1] + '_' + m[2].replace(/\.html?$/i, '');
  m = s.match(/paypaymall\.yahoo\.co\.jp\/store\/([^\/]+)\/([^\/\?#]+)/i);
  if (m) return m[1] + '_' + m[2].replace(/\.html?$/i, '');
  m = s.match(/paypaymall\.yahoo\.co\.jp\/([^\/]+)\/([^\/\?#]+)/i);
  if (m && String(m[1]).toLowerCase() !== 'store') return m[1] + '_' + m[2].replace(/\.html?$/i, '');
  m = s.match(/item-shopping\.c\.yimg\.jp\/i\/[a-z]\/([^\/\?#]+)/i);
  if (m) return m[1];
  return '';
}

/**
 * itemLookup JSON の Hit を取り出す（キー名・ネストのゆれに対応）。
 * @param {*} json
 * @return {Object|null}
 */
function parseYahooJsonItemLookupHit_(json) {
  if (!json || typeof json !== 'object') return null;
  if (json.Error || json.error) return null;
  var rs = json.ResultSet || json.resultSet;
  if (!rs) return null;

  var res = rs.Result || rs.result;
  if (res != null) {
    var rList = Array.isArray(res) ? res : [res];
    for (var ri = 0; ri < rList.length; ri++) {
      var r0 = rList[ri];
      if (!r0 || typeof r0 !== 'object') continue;
      var hit = r0.Hit || r0.hit;
      if (hit) {
        if (Array.isArray(hit)) return hit[0] || null;
        return hit;
      }
      if (r0.Name != null || r0.name != null || r0.Url != null || r0.url != null || r0.Image != null || r0.image != null) {
        return r0;
      }
    }
  }
  var hitTop = rs.Hit || rs.hit;
  if (hitTop) {
    if (Array.isArray(hitTop)) return hitTop[0] || null;
    return hitTop;
  }
  return null;
}

/**
 * Hit オブジェクト配下の文字列だけを走査し、Yahoo!ショッピング商品画像っぽい URL を集める（JSON スキーマ差分のフォールバック）。
 * @param {*} node
 * @param {number} depth
 * @return {string[]}
 */
function collectYahooProductImageUrlsFromHitSubtree_(node, depth) {
  var out = [];
  if (depth > 14 || node == null) return out;
  function isProductImageUrl(u) {
    if (!u || typeof u !== 'string') return false;
    var s = u.trim();
    if (s.indexOf('http') !== 0) return false;
    if (!/yimg\.jp|yahoo\.co\.jp/i.test(s)) return false;
    if (/review\/|\/store\/|seller|logo|banner|120x30/i.test(s)) return false;
    return /\/i\/[a-z]\/|shopping\.c\.yimg\.jp\/lib\/|item-shopping\.c\.yimg\.jp/i.test(s);
  }
  if (typeof node === 'string') {
    if (isProductImageUrl(node)) out.push(node.trim());
    return out;
  }
  if (Array.isArray(node)) {
    for (var i = 0; i < node.length; i++) {
      var sub = collectYahooProductImageUrlsFromHitSubtree_(node[i], depth + 1);
      for (var j = 0; j < sub.length; j++) out.push(sub[j]);
    }
    return out;
  }
  if (typeof node === 'object') {
    for (var k in node) {
      if (!Object.prototype.hasOwnProperty.call(node, k)) continue;
      var v = node[k];
      if (typeof v === 'string' && isProductImageUrl(v)) out.push(v.trim());
      else if (typeof v === 'object') {
        var sub2 = collectYahooProductImageUrlsFromHitSubtree_(v, depth + 1);
        for (var t = 0; t < sub2.length; t++) out.push(sub2[t]);
      }
    }
  }
  return out;
}

function collectYahooItemLookupImageUrlsFromHit_(hit) {
  var urls = [];
  var seen = {};
  function add(u) {
    if (!u || String(u).trim() === '') return;
    var uu = String(u).trim();
    if (uu.indexOf('http') !== 0) return;
    if (!seen[uu]) {
      seen[uu] = true;
      urls.push(uu);
    }
  }
  function addImgNode(img) {
    if (!img) return;
    add(img.Medium);
    add(img.medium);
    add(img.Small);
    add(img.small);
    add(img.Id);
    add(img.id);
  }
  if (!hit) return urls;
  addImgNode(hit.Image || hit.image);
  var ex = hit.ExImage || hit.exImage;
  if (ex) {
    add(ex.Url);
    add(ex.url);
  }
  var rel = hit.RelatedImages || hit.relatedImages;
  if (rel) {
    var imgs = rel.Image || rel.image;
    if (imgs) {
      if (!Array.isArray(imgs)) imgs = [imgs];
      for (var i = 0; i < imgs.length; i++) addImgNode(imgs[i]);
    }
  }
  if (urls.length === 0) {
    var deep = collectYahooProductImageUrlsFromHitSubtree_(hit, 0);
    for (var d = 0; d < deep.length; d++) add(deep[d]);
  }
  return urls;
}

/**
 * Yahoo CDN 推測用: レスポンスボディが JPEG/PNG/GIF/BMP/WEBP のいずれかに見えるか（マジックバイト＋最小サイズ）。
 * @param {number[]} bytes
 * @return {boolean}
 */
function isYahooCdnGuessImageBodyBytes_(bytes) {
  if (!bytes || bytes.length < YAHOO_CDN_GUESS_MIN_BYTES) return false;
  var b0 = bytes[0] & 0xff;
  var b1 = bytes[1] & 0xff;
  var b2 = bytes[2] & 0xff;
  var b3 = bytes[3] & 0xff;
  if (b0 === 0xff && b1 === 0xd8 && b2 === 0xff) return true;
  if (b0 === 0x89 && b1 === 0x50 && b2 === 0x4e && b3 === 0x47) return true;
  if (b0 === 0x47 && b1 === 0x49 && b2 === 0x46 && b3 === 0x38) return true;
  if (b0 === 0x42 && b1 === 0x4d) return true;
  if (bytes.length >= 12 && b0 === 0x52 && b1 === 0x49 && b2 === 0x46 && b3 === 0x46
      && (bytes[8] & 0xff) === 0x57 && (bytes[9] & 0xff) === 0x45 && (bytes[10] & 0xff) === 0x42 && (bytes[11] & 0xff) === 0x50) {
    return true;
  }
  return false;
}

/**
 * item-shopping CDN の命名仮説でメイン＋サブ画像 URL を列挙。
 * GET で 200、Content-Type が明らかに HTML/テキストでないこと、ボディが YAHOO_CDN_GUESS_MIN_BYTES 以上かつ画像マジックバイト一致のときのみ採用（プレースホルダ・誤 200 を抑止）。
 * @param {string} itemCode - store_productkey（例: nenrin_hatomugi50p-sb）
 * @param {number} [optMaxSub] - _1〜_N の N 上限（省略時 YAHOO_CDN_GUESS_MAX_SUB_INDEX）
 * @return {{ urls: string[], error: string|null }}
 */
function fetchYahooShoppingCdnGuessImageUrls_(itemCode, optMaxSub) {
  var result = { urls: [], error: null };
  var ic = String(itemCode || '').trim();
  if (!ic) {
    result.error = 'empty';
    return result;
  }
  var maxSub = (optMaxSub != null && optMaxSub > 0) ? Math.min(parseInt(optMaxSub, 10), 30) : YAHOO_CDN_GUESS_MAX_SUB_INDEX;
  if (isNaN(maxSub) || maxSub < 1) maxSub = YAHOO_CDN_GUESS_MAX_SUB_INDEX;
  var base = 'https://item-shopping.c.yimg.jp/i/g/' + ic;
  var seen = {};
  function add(u) {
    if (!u || seen[u]) return;
    seen[u] = true;
    result.urls.push(u);
  }
  function getContentTypeLower_(res) {
    var h = res.getHeaders();
    if (!h) return '';
    var ct = (h['Content-Type'] || h['content-type'] || h['Content-type'] || '') + '';
    return String(ct).toLowerCase().split(';')[0].trim();
  }
  function contentTypeBlocksImage_(ctLow) {
    if (!ctLow) return false;
    if (ctLow.indexOf('text/html') >= 0) return true;
    if (ctLow.indexOf('text/') === 0) return true;
    if (ctLow.indexOf('application/json') >= 0) return true;
    if (ctLow.indexOf('application/xml') >= 0) return true;
    return false;
  }
  function probe(u) {
    try {
      var res = UrlFetchApp.fetch(u, { muteHttpExceptions: true, followRedirects: true });
      if (res.getResponseCode() !== 200) return;
      var ctLow = getContentTypeLower_(res);
      if (contentTypeBlocksImage_(ctLow)) return;
      if (ctLow && ctLow.indexOf('image/') !== 0 && ctLow.indexOf('application/octet-stream') !== 0) return;
      var bytes = res.getBlob().getBytes();
      if (!isYahooCdnGuessImageBodyBytes_(bytes)) return;
      add(u);
    } catch (pe) {
      /* ignore */
    }
  }
  probe(base);
  Utilities.sleep(YAHOO_CDN_GUESS_SLEEP_MS);
  for (var i = 1; i <= maxSub; i++) {
    probe(base + '_' + i);
    Utilities.sleep(YAHOO_CDN_GUESS_SLEEP_MS);
  }
  return result;
}

/**
 * itemLookup（XML）で画像 URL を収集。RelatedImages / Image 等のテキストノードから yimg 系 URL を拾う。
 * @param {string} clientId
 * @param {string} itemCode
 * @return {{ urls: string[], error: string|null }}
 */
function fetchYahooShoppingItemLookupXmlImageUrls_(clientId, itemCode) {
  var result = { urls: [], error: null };
  if (!clientId || !String(itemCode).trim()) {
    result.error = 'empty';
    return result;
  }
  var ic = String(itemCode).trim();
  var url = 'https://shopping.yahooapis.jp/ShoppingWebService/V1/itemLookup?appid=' + encodeURIComponent(clientId) + '&itemcode=' + encodeURIComponent(ic) + '&responsegroup=large&image_size=600';
  try {
    var res = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
    var code = res.getResponseCode();
    var text = res.getContentText() || '';
    if (code !== 200) {
      result.error = 'HTTP ' + code;
      return result;
    }
    if (text.indexOf('<Error') >= 0 || text.indexOf('<error') >= 0) {
      var shortErr = text.replace(/\s+/g, ' ').substring(0, 240);
      result.error = 'API Error ' + shortErr;
      return result;
    }
    var doc = XmlService.parse(text);
    var collected = collectYahooProductImageUrlsFromXmlElement_(doc.getRootElement());
    var seen = {};
    for (var ci = 0; ci < collected.length; ci++) {
      var u = collected[ci];
      if (!seen[u]) {
        seen[u] = true;
        result.urls.push(u);
      }
    }
    return result;
  } catch (xe) {
    result.error = xe.message || String(xe);
    return result;
  }
}

/**
 * @param {GoogleAppsScript.XML.Element} element
 * @return {string[]}
 */
function collectYahooProductImageUrlsFromXmlElement_(element) {
  var out = [];
  function isProductImageUrl(u) {
    if (!u || typeof u !== 'string') return false;
    var s = u.trim();
    if (s.indexOf('http') !== 0) return false;
    if (!/yimg\.jp|yahoo\.co\.jp/i.test(s)) return false;
    if (/review\/|\/store\/|seller|logo|banner|120x30/i.test(s)) return false;
    return /\/i\/[a-z]\/|item-shopping\.c\.yimg\.jp/i.test(s);
  }
  function walk(el) {
    if (!el) return;
    var t = el.getText();
    if (t) {
      var s = String(t).trim();
      if (isProductImageUrl(s)) out.push(s);
    }
    var kids = el.getChildren();
    for (var i = 0; i < kids.length; i++) walk(kids[i]);
  }
  walk(element);
  return out;
}

/**
 * itemLookup が 0 件・未対応のとき、V3 itemSearch で itemcode（hits.code）一致の商品から画像を取る。
 * @param {string} clientId
 * @param {string} itemCode
 * @return {string[]}
 */
function fetchYahooShoppingV3ImageUrlsForItemCode_(clientId, itemCode) {
  var urls = [];
  var seen = {};
  function add(u) {
    if (!u || String(u).trim() === '') return;
    var uu = String(u).trim();
    if (uu.indexOf('http') !== 0) return;
    if (!seen[uu]) {
      seen[uu] = true;
      urls.push(uu);
    }
  }
  function addFromHit(h) {
    if (!h) return;
    if (h.image) {
      add(h.image.medium);
      add(h.image.small);
      add(h.image.id);
    }
    if (h.exImage) {
      add(h.exImage.url);
      add(h.exImage.medium);
    }
  }
  if (!clientId || !String(itemCode).trim()) return urls;
  var q = String(itemCode).trim();
  var tryUrls = [
    'https://shopping.yahooapis.jp/ShoppingWebService/V3/itemSearch?appid=' + encodeURIComponent(clientId) + '&query=' + encodeURIComponent(q) + '&results=30'
  ];
  var udm = q.indexOf('_');
  if (udm > 0) {
    var sid = q.substring(0, udm);
    var rest = q.substring(udm + 1);
    tryUrls.push('https://shopping.yahooapis.jp/ShoppingWebService/V3/itemSearch?appid=' + encodeURIComponent(clientId) + '&seller_id=' + encodeURIComponent(sid) + '&query=' + encodeURIComponent(rest) + '&results=30');
  }
  for (var ti = 0; ti < tryUrls.length; ti++) {
    try {
      Utilities.sleep(120);
      var res = UrlFetchApp.fetch(tryUrls[ti], { muteHttpExceptions: true });
      if (res.getResponseCode() !== 200) continue;
      var json = JSON.parse(res.getContentText());
      var rawHits = json.hits || [];
      var matched = null;
      for (var i = 0; i < rawHits.length; i++) {
        var c = rawHits[i].code != null ? String(rawHits[i].code) : '';
        if (c === q) {
          matched = rawHits[i];
          break;
        }
      }
      if (!matched && rawHits.length > 0) matched = rawHits[0];
      if (matched) {
        addFromHit(matched);
        Logger.log('[競合画像テスト] Yahoo V3 フォールバック 画像URL数=' + urls.length + ' itemcode=' + q + ' matchCode=' + (matched.code != null ? String(matched.code) : '(先頭ヒット)'));
        if (urls.length > 0) return urls;
      }
    } catch (e) {
      Logger.log('[競合画像テスト] Yahoo V3 フォールバック 例外: ' + (e && e.message));
    }
  }
  return urls;
}

/**
 * Yahoo Shopping 商品コード検索 itemLookup（JSON）でメイン＋関連画像URLを取得。responsegroup=large で RelatedImages を含む。
 * itemLookup で Hit が取れない・画像0件のときは V3 itemSearch にフォールバックする。
 * @return {{ urls: string[], error: string|null, debug?: string }}
 */
function fetchYahooShoppingItemLookupImageUrls_(clientId, itemCode) {
  var result = { urls: [], error: null };
  if (!clientId || !String(itemCode).trim()) {
    result.error = 'empty';
    return result;
  }
  var ic = String(itemCode).trim();
  var url = 'https://shopping.yahooapis.jp/ShoppingWebService/V1/json/itemLookup?appid=' + encodeURIComponent(clientId) + '&itemcode=' + encodeURIComponent(ic) + '&responsegroup=large&image_size=600';
  try {
    var res = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
    var code = res.getResponseCode();
    var text = res.getContentText();
    if (code !== 200) {
      result.error = 'HTTP ' + code;
      result.urls = fetchYahooShoppingV3ImageUrlsForItemCode_(clientId, ic);
      if (result.urls.length > 0) result.error = null;
      return result;
    }
    var json = JSON.parse(text);
    if (json.Error || json.error) {
      result.error = 'API ' + JSON.stringify(json.Error || json.error).substring(0, 200);
      result.urls = fetchYahooShoppingV3ImageUrlsForItemCode_(clientId, ic);
      if (result.urls.length > 0) result.error = null;
      return result;
    }
    var hit = parseYahooJsonItemLookupHit_(json);
    if (!hit) {
      result.debug = 'Hitなし itemcode=' + ic + ' topKeys=' + Object.keys(json).join(',');
      Logger.log('[競合画像テスト] Yahoo itemLookup Hit なし → V3 試行 ' + (result.debug || ''));
      result.urls = fetchYahooShoppingV3ImageUrlsForItemCode_(clientId, ic);
      return result;
    }
    result.urls = collectYahooItemLookupImageUrlsFromHit_(hit);
    if (result.urls.length === 0) {
      Logger.log('[競合画像テスト] Yahoo itemLookup 画像0件 → V3 試行 itemcode=' + ic);
      result.urls = fetchYahooShoppingV3ImageUrlsForItemCode_(clientId, ic);
    }
    return result;
  } catch (e) {
    result.error = e.message || String(e);
    result.urls = fetchYahooShoppingV3ImageUrlsForItemCode_(clientId, ic);
    if (result.urls.length > 0) result.error = null;
    return result;
  }
}

/**
 * 商品名からセット数（個数・袋数など）を推定する。表記ゆれに対応するため複数パターンを試す。
 * @param {string} name - 商品名（タイトル）
 * @return {number|null} 推定セット数（1〜999）。取れなければ null
 */
function parseSetCountFromItemName(name) {
  var r = parseSetCountFromItemNameWithSource(name);
  return r ? r.setCount : null;
}

/**
 * 商品名からセット数を推定し、どのパターンでマッチしたかも返す。数字+P（4P等）は内容量の可能性があるため、fromP=true のときは Gemini 判定を推奨。
 * @param {string} name - 商品名（タイトル）
 * @return {{ setCount: number|null, fromP: boolean }|null} 取れなければ null
 */
function parseSetCountFromItemNameWithSource(name) {
  if (!name || typeof name !== 'string') return null;
  var s = name.trim();
  var patterns = [
    { re: /×\s*(\d+)\s*缶\s*セット/i, fromP: false },
    { re: /(\d+)\s*缶\s*セット/i, fromP: false },
    { re: /×\s*(\d+)\s*個\s*セット/i, fromP: false },
    { re: /×\s*(\d+)\s*個\s*入/i, fromP: false },
    { re: /(\d+)\s*個\s*セット/i, fromP: false },
    { re: /(\d+)\s*個\s*入/i, fromP: false },
    { re: /(\d+)\s*食\s*入/i, fromP: false },
    { re: /(\d+)\s*[Pp]\s*(?:セット)?/, fromP: true }
  ];
  for (var i = 0; i < patterns.length; i++) {
    var m = s.match(patterns[i].re);
    if (m) {
      var n = parseInt(m[1], 10);
      if (n >= 1 && n <= 999) return { setCount: n, fromP: patterns[i].fromP };
    }
  }
  if (/\[1袋\]|1\s*袋|1\s*個(?:セット)?|1\s*食\s*入?/i.test(s)) return { setCount: 1, fromP: false };
  return null;
}

/**
 * 楽天の商品名から「販売単位のセット数」を Gemini で判定する。4P が内容量かセット数かなど曖昧な場合に使用。
 * @param {string} itemName - 楽天 API の itemName
 * @return {number|null} 販売セット数（1〜999）。不明・内容量のみの場合は null
 */
function inferSetCountFromItemNameByGemini(itemName) {
  if (!itemName || typeof itemName !== 'string' || itemName.trim().length === 0) return null;
  var key = getGeminiApiKey();
  if (!key) return null;
  var prompt = '以下の楽天商品名から、**販売単位のセット数**（何個セット・何袋セットで売っているか）を1つの整数だけで答えてください。\n'
    + '・「16g×4P」「4袋入」などは内容量（1袋あたりのパック数等）なのでセット数に含めません。\n'
    + '・「2袋・5袋・10袋」のように複数オプションがある場合は、そのいずれかではなく「この1商品としての最小販売単位」が不明なら 0 と答えてください。\n'
    + '・「×3個セット」「10個セット」のように明確にセット数が一つに決まる場合はその整数を返してください。\n'
    + '回答は数字のみ（0＝不明）。説明は不要。\n\n商品名:\n' + itemName.substring(0, 500);
  try {
    var url = 'https://generativelanguage.googleapis.com/v1beta/models/' + (typeof MODEL_GEMINI !== 'undefined' ? MODEL_GEMINI : 'gemini-2.0-flash') + ':generateContent?key=' + encodeURIComponent(key);
    var body = { contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0.1, maxOutputTokens: 64 } };
    var res = UrlFetchApp.fetch(url, { method: 'post', contentType: 'application/json', muteHttpExceptions: true, payload: JSON.stringify(body) });
    if (res.getResponseCode() !== 200) {
      Logger.log('[楽天セット別] inferSetCountFromItemNameByGemini HTTP ' + res.getResponseCode());
      return null;
    }
    var json = JSON.parse(res.getContentText());
    var text = (json.candidates && json.candidates[0] && json.candidates[0].content && json.candidates[0].content.parts && json.candidates[0].content.parts[0]) ? json.candidates[0].content.parts[0].text : '';
    text = String(text).replace(/\s/g, '').replace(/[^\d]/g, '');
    var n = parseInt(text, 10);
    if (isNaN(n) || n < 1 || n > 999) return null;
    Logger.log('[楽天セット別] Gemini セット数 商品名先頭40字=' + itemName.substring(0, 40) + ' → ' + n);
    return n;
  } catch (e) {
    Logger.log('[楽天セット別] inferSetCountFromItemNameByGemini 例外: ' + (e && e.message));
    return null;
  }
}

/**
 * 複数の楽天商品名を一括で Gemini に送り、文脈を踏まえて各商品の販売セット数を判定する。内容量とセット数の区別を一覧全体から推測させる。
 * @param {string[]} itemNames - 商品名の配列（同一JANで取得した一覧）
 * @return {number[]} 各商品のセット数（不明は0）。件数は itemNames.length と同一。失敗時は空配列。
 */
function inferSetCountBatchByGemini(itemNames) {
  if (!itemNames || itemNames.length === 0) return [];
  var key = getGeminiApiKey();
  if (!key) {
    Logger.log('[楽天セット数一括] Gemini API キー未設定');
    return [];
  }
  var listText = '';
  for (var i = 0; i < itemNames.length; i++) {
    listText += (i + 1) + '. ' + (itemNames[i] || '').substring(0, 300) + '\n';
  }
  var prompt = '以下は同一JANで取得した楽天の商品名一覧です。各商品について、**販売単位のセット数**（何個セット・何袋セットで売っているか）を、一覧全体の文脈（他商品の表記との整合）を踏まえて判断し、1つの整数で答えてください。\n'
    + '・「16g×4P」「4袋入」などは内容量（1袋あたりのパック数等）のことが多いです。同一シリーズに「10個セット」「2袋・5袋・10袋」などがあれば、4Pは内容量と判断してください。\n'
    + '・不明・複数オプションで特定できない場合は0。\n'
    + '・回答は1行に1つ、行番号と同順で整数のみ。説明や記号は不要。\n\n商品名一覧:\n' + listText + '\n上記1番目〜' + itemNames.length + '番目のセット数（0=不明）を、1行1整数で' + itemNames.length + '行答えてください。';
  try {
    var url = 'https://generativelanguage.googleapis.com/v1beta/models/' + (typeof MODEL_GEMINI !== 'undefined' ? MODEL_GEMINI : 'gemini-2.0-flash') + ':generateContent?key=' + encodeURIComponent(key);
    var body = { contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0.1, maxOutputTokens: 512 } };
    var res = UrlFetchApp.fetch(url, { method: 'post', contentType: 'application/json', muteHttpExceptions: true, payload: JSON.stringify(body) });
    if (res.getResponseCode() !== 200) {
      Logger.log('[楽天セット数一括] Gemini HTTP ' + res.getResponseCode());
      return [];
    }
    var json = JSON.parse(res.getContentText());
    var text = (json.candidates && json.candidates[0] && json.candidates[0].content && json.candidates[0].content.parts && json.candidates[0].content.parts[0]) ? json.candidates[0].content.parts[0].text : '';
    var lines = String(text).split(/\r?\n/);
    var result = [];
    for (var j = 0; j < itemNames.length; j++) {
      var num = 0;
      if (j < lines.length) {
        var match = lines[j].replace(/\s/g, '').match(/\d+/);
        if (match) {
          var n = parseInt(match[0], 10);
          num = (n >= 1 && n <= 999) ? n : 0;
        }
      }
      result.push(num);
    }
    Logger.log('[楽天セット数一括] Gemini 一括判定 件数=' + itemNames.length + ' 取得=' + result.length);
    return result;
  } catch (e) {
    Logger.log('[楽天セット数一括] 例外: ' + (e && e.message));
    return [];
  }
}

/**
 * メニュー「Yahoo! セット別価格 取得テスト」の処理。
 * 固定 JAN で Yahoo! API を複数件取得し、商品名からセット数を推定してセット数ごとの最安価格をログ・トーストで表示する。
 */
function menuTestYahooSetPrices() {
  var clientId = (PropertiesService.getScriptProperties().getProperty('YAHOO_SHOPPING_CLIENT_ID') || '').trim();
  if (!clientId) {
    SpreadsheetApp.getUi().alert('Script Properties に YAHOO_SHOPPING_CLIENT_ID を設定してください。');
    return;
  }
  var jan = TEST_RAKUTEN_YAHOO_JAN;
  var res = fetchYahooShoppingItemsByJan(clientId, jan, 20);
  if (res.error) {
    Logger.log('[Yahoo!セット別テスト] エラー: ' + res.error);
    SpreadsheetApp.getActive().toast('エラー: ' + res.error, 'Yahoo! セット別テスト', 6);
    return;
  }
  var hits = res.hits || [];
  Logger.log('[Yahoo!セット別テスト] JAN=' + jan + ' 取得件数=' + hits.length);
  var setToMinPrice = {};
  for (var i = 0; i < hits.length; i++) {
    var name = hits[i].name;
    var price = hits[i].price;
    Logger.log('[Yahoo!セット別テスト] hit[' + i + '] name=' + (name ? name.substring(0, 60) : '') + '... price=' + price);
    var setCount = parseSetCountFromItemName(name);
    if (setCount != null && price != null && price > 0) {
      if (setToMinPrice[setCount] == null || price < setToMinPrice[setCount]) {
        setToMinPrice[setCount] = price;
      }
    }
  }
  var setCounts = Object.keys(setToMinPrice).map(function(k) { return parseInt(k, 10); }).sort(function(a, b) { return a - b; });
  var summary = 'JAN=' + jan + ' 取得=' + hits.length + '件 セット数推定=' + setCounts.length + '種';
  for (var j = 0; j < setCounts.length; j++) {
    var sc = setCounts[j];
    summary += ' ' + sc + '→' + setToMinPrice[sc] + '円';
    Logger.log('[Yahoo!セット別テスト] セット数=' + sc + ' 最安=' + setToMinPrice[sc] + '円');
  }
  Logger.log('[Yahoo!セット別テスト] ' + summary);
  SpreadsheetApp.getActive().toast(summary, 'Yahoo! セット別テスト', 10);
}

/**
 * Google Custom Search JSON API で 1 クエリ実行し、結果を共通形式で返す。
 * Script Properties: GOOGLE_CSE_API_KEY, GOOGLE_CSE_CX。
 * @param {string} apiKey - API キー
 * @param {string} cx - 検索エンジン ID
 * @param {string} query - 検索クエリ
 * @param {{ num?: number }} [opt] - num: 取得件数（最大10、省略時5）
 * @return {{ error: string|null, items: Array<{ title: string, snippet: string, link: string }> }}
 */
function fetchGoogleCustomSearch(apiKey, cx, query, opt) {
  var result = { error: null, items: [] };
  if (!apiKey || !cx || !query) {
    result.error = 'GOOGLE_CSE_API_KEY / GOOGLE_CSE_CX または query が未設定です。';
    return result;
  }
  var num = (opt && opt.num != null) ? Math.min(Math.max(parseInt(opt.num, 10) || 5, 1), 10) : 5;
  var url = 'https://www.googleapis.com/customsearch/v1?key=' + encodeURIComponent(apiKey)
    + '&cx=' + encodeURIComponent(cx)
    + '&q=' + encodeURIComponent(String(query).trim())
    + '&num=' + num;
  Logger.log('[Google CSE] リクエスト cx=' + cx + ' q(先頭30字)=' + (String(query).trim().substring(0, 30)) + (String(query).trim().length > 30 ? '...' : ''));
  try {
    var res = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
    var code = res.getResponseCode();
    var text = res.getContentText();
    if (code !== 200) {
      result.error = 'HTTP ' + code + ' ' + (text ? text.substring(0, 300) : '');
      Logger.log('[Google CSE] HTTP ' + code + ' 応答本文(先頭600字): ' + (text ? text.substring(0, 600) : '(空)'));
      if (text && text.length > 600) Logger.log('[Google CSE] 応答本文 続き: ' + text.substring(600, 1000));
      return result;
    }
    var json = JSON.parse(text);
    var items = json.items || [];
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      result.items.push({
        title: (it.title != null) ? String(it.title) : '',
        snippet: (it.snippet != null) ? String(it.snippet) : '',
        link: (it.link != null) ? String(it.link) : ''
      });
    }
    Logger.log('[Google CSE] query="' + (String(query).length > 50 ? String(query).substring(0, 50) + '...' : query) + '" 取得件数=' + result.items.length);
    return result;
  } catch (e) {
    result.error = (e && e.message) || String(e);
    Logger.log('[Google CSE] 例外: ' + result.error);
    return result;
  }
}

/**
 * SerpAPI (engine=google) で 1 クエリ実行し、結果を共通形式で返す。
 * Script Properties: SERPAPI_API_KEY。
 * @param {string} apiKey - SerpAPI の API キー
 * @param {string} query - 検索クエリ
 * @param {{ num?: number }} [opt] - num: 取得件数（最大10、省略時5）
 * @return {{ error: string|null, items: Array<{ title: string, snippet: string, link: string, imageUrl: string }> }}
 */
function fetchSerpApiGoogleSearch(apiKey, query, opt) {
  var result = { error: null, items: [], tokenQuotaError: false };
  if (!apiKey || !query) {
    result.error = 'SERPAPI_API_KEY または query が未設定です。';
    return result;
  }
  var q = String(query).trim();
  if (!q) {
    result.error = 'query が空です。';
    return result;
  }
  var num = (opt && opt.num != null) ? Math.min(Math.max(parseInt(opt.num, 10) || 5, 1), 10) : 5;
  var url = 'https://serpapi.com/search.json'
    + '?engine=google'
    + '&q=' + encodeURIComponent(q)
    + '&num=' + num
    + '&api_key=' + encodeURIComponent(apiKey);
  Logger.log('[SerpAPI] リクエスト engine=google q(先頭30字)=' + q.substring(0, 30) + (q.length > 30 ? '...' : '') + ' num=' + num);
  try {
    var res = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
    var code = res.getResponseCode();
    var text = res.getContentText();
    if (code !== 200) {
      result.error = 'HTTP ' + code + ' ' + (text ? text.substring(0, 300) : '');
      result.tokenQuotaError = isTokenQuotaError(result.error);
      Logger.log('[SerpAPI] HTTP ' + code + ' 応答本文(先頭600字): ' + (text ? text.substring(0, 600) : '(空)'));
      if (text && text.length > 600) Logger.log('[SerpAPI] 応答本文 続き: ' + text.substring(600, 1000));
      return result;
    }
    var json = JSON.parse(text);
    var organic = json.organic_results || [];
    for (var i = 0; i < organic.length && result.items.length < num; i++) {
      var o = organic[i] || {};
      var snippet = '';
      if (o.snippet != null) snippet = String(o.snippet);
      else if (o.snippet_highlighted_words && o.snippet_highlighted_words.length) snippet = o.snippet_highlighted_words.join(' ');
      var imageUrl = (o.thumbnail != null && String(o.thumbnail).trim() !== '') ? String(o.thumbnail).trim() : '';
      result.items.push({
        title: (o.title != null) ? String(o.title) : '',
        snippet: snippet,
        link: (o.link != null) ? String(o.link) : '',
        imageUrl: imageUrl
      });
      if (imageUrl) Logger.log('[SerpAPI] 結果' + (result.items.length) + ' thumbnailあり: ' + imageUrl.substring(0, 60) + (imageUrl.length > 60 ? '...' : ''));
    }
    Logger.log('[SerpAPI] query="' + (q.length > 50 ? q.substring(0, 50) + '...' : q) + '" 取得件数=' + result.items.length);
    return result;
  } catch (e) {
    result.error = (e && e.message) || String(e);
    result.tokenQuotaError = isTokenQuotaError(result.error);
    Logger.log('[SerpAPI] 例外: ' + result.error);
    Logger.log('[SerpAPI] 例外詳細 name=' + (e && e.name) + ' toString=' + (e ? e.toString().substring(0, 200) : ''));
    Logger.log('[SerpAPI] 調査用 リクエストURL長(api_key除く)=' + (url ? url.replace(/api_key=[^&]+/, 'api_key=***').length : 0));
    return result;
  }
}

/**
 * 共通 Web 検索：現在は SerpAPI のみ使用。呼び出し側はプロバイダを意識しない。
 * 不具合調査用に provider・query・件数/エラーをログ出力する。
 * @param {string} query - 検索クエリ
 * @param {{ num?: number }} [opt] - num: 取得件数（省略時5）
 * @return {{ error: string|null, items: Array<{ title: string, snippet: string, link: string, imageUrl: string }> }}
 */
function runWebSearch(query, opt) {
  var result = { error: null, items: [], tokenQuotaError: false };
  var provider = 'SerpAPI';
  var apiKey = (PropertiesService.getScriptProperties().getProperty('SERPAPI_API_KEY') || '').trim();
  if (!apiKey) {
    result.error = 'SERPAPI_API_KEY が未設定です。';
    Logger.log('[runWebSearch] provider=' + provider + ' query(先頭30字)=' + (query ? String(query).trim().substring(0, 30) : '') + ' エラー: ' + result.error);
    return result;
  }
  var q = String(query).trim();
  if (!q) {
    result.error = 'query が空です。';
    Logger.log('[runWebSearch] provider=' + provider + ' エラー: ' + result.error);
    return result;
  }
  var r = fetchSerpApiGoogleSearch(apiKey, q, opt);
  result.error = r.error;
  result.items = r.items || [];
  result.tokenQuotaError = r.tokenQuotaError || false;
  if (r.error) {
    Logger.log('[runWebSearch] provider=' + provider + ' query(先頭40字)=' + q.substring(0, 40) + (q.length > 40 ? '...' : '') + ' エラー: ' + r.error);
  } else {
    Logger.log('[runWebSearch] provider=' + provider + ' query(先頭40字)=' + q.substring(0, 40) + (q.length > 40 ? '...' : '') + ' 取得件数=' + result.items.length);
  }
  return result;
}

/**
 * テキスト（スニペットやHTML）から「商品コード：000312」形式を抽出する。先頭0を保持。
 * @param {string} text
 * @return {string|null} 最初にマッチした商品コード（2文字以上）。なしなら null
 */
function extractProductCodeFromText(text) {
  if (!text || typeof text !== 'string') return null;
  var m = text.match(/商品コード[：:\s]*([0-9]+)/);
  if (m && m[1] && m[1].length >= 2) return m[1];
  m = text.match(/型番[：:\s]*([0-9]+)/);
  if (m && m[1] && m[1].length >= 2) return m[1];
  return null;
}

/**
 * URL のページを取得し、HTML から商品コードを抽出する。
 * @param {string} url
 * @return {string|null} 商品コード。取得失敗・未検出は null
 */
function fetchProductCodeFromUrl(url) {
  if (!url || typeof url !== 'string' || url.indexOf('http') !== 0) return null;
  try {
    var res = UrlFetchApp.fetch(url, { muteHttpExceptions: true, headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; rv:91.0) Gecko/20100101 Firefox/91.0' } });
    if (res.getResponseCode() !== 200) return null;
    var html = res.getContentText();
    return extractProductCodeFromText(html);
  } catch (e) {
    Logger.log('[メーカー品番][fetchURL] 例外: ' + (e && e.message));
    return null;
  }
}

/**
 * API エラーがトークン・クォータ不足系かどうか。
 * @param {string} err - エラーメッセージ
 * @return {boolean}
 */
function isTokenQuotaError(err) {
  if (!err || typeof err !== 'string') return false;
  var lower = err.toLowerCase();
  return (lower.indexOf('quota') >= 0 || lower.indexOf('rate limit') >= 0 || lower.indexOf('429') >= 0 || lower.indexOf('resource exhausted') >= 0 || lower.indexOf('limit exceeded') >= 0 || lower.indexOf('token') >= 0);
}

/**
 * URL が小売・モール・卸サイトかどうか。メーカー公式フォールバックで除外するため。
 * @param {string} url
 * @return {boolean} 小売等なら true
 */
function isRetailerUrl(url) {
  if (!url || typeof url !== 'string') return false;
  var lower = url.toLowerCase();
  var patterns = ['rakuten.co.jp', 'amazon.co.jp', 'yahoo.co.jp', 'shopping.yahoo', 'store.shopping.yahoo', 'kaldi.co.jp', 'superdelivery.com', 'the-fuji.net', 'netton.kokubu', 'goooods.com', 'adachi-jozo', 'urecon.jp', 'monolog.r-n-i', 'item.rakuten', 'store.shopping.yahoo'];
  for (var i = 0; i < patterns.length; i++) {
    if (lower.indexOf(patterns[i]) >= 0) return true;
  }
  return false;
}

/**
 * Web 検索結果（title / snippet）から型番・メーカー品番らしき文字列を抽出する。
 * 単一文字は除外する（誤検出防止）。
 * @param {Array<{ title: string, snippet: string }>} items - runWebSearch 等の items
 * @return {string[]} 重複除く・2文字以上の候補配列
 */
function extractModelNumbersFromSearchItems(items) {
  if (!items || !Array.isArray(items)) return [];
  var seen = {};
  var out = [];
  var patterns = [
    /型番[：:\s]*([^\s、。\n\r]+)/g,
    /メーカー型番[：:\s]*([^\s、。\n\r]+)/g,
    /品番[：:\s]*([^\s、。\n\r]+)/g,
    /商品コード[：:\s]*([^\s、。\n\r\d]*\d+[^\s、。\n\r]*)/g,
    /（型番[：:\s]*([^）]+)）/g
  ];
  for (var i = 0; i < items.length; i++) {
    var text = ((items[i].title || '') + ' ' + (items[i].snippet || '')).trim();
    if (!text) continue;
    for (var p = 0; p < patterns.length; p++) {
      var re = new RegExp(patterns[p].source, patterns[p].flags);
      var m;
      while ((m = re.exec(text)) !== null) {
        var val = String(m[1]).trim();
        if (val.length >= 2 && !seen[val]) {
          seen[val] = true;
          out.push(val);
        }
      }
    }
  }
  Logger.log('[メーカー品番][Web] 検索結果から抽出 候補数=' + out.length + ' 候補=' + (out.length ? out.join(', ') : '(なし)'));
  return out;
}

