const ASIN_PASTE_BLOCK_HEADERS = ['画像', 'ASIN', '商品名', '評価', '競合価格(Amazon)', 'セット数', '商品URL', 'セット数_AI根拠', '参考画像URL', '卸値(税込)'];
/** シート作成時の商品ブロック数。最大10商品＝60列。1行目にAI情報取得dataの商品名を式で表示 */
const ASIN_PASTE_DEFAULT_BLOCKS = 10;
