  // 空白・記号・括弧類を除去（文字・数字は残す）
  s = s.replace(/[\s\u3000]/g, '');
  s = s.replace(/[!"#$%&'()*+,\-./:;<=>?@[\\\]^_`{|}~「」『』【】〔〕（）()［］\[\]・×☆★※]/g, '');
