    var expectedJAN = (productNameRow[nameCol + 1] != null) ? String(productNameRow[nameCol + 1]).trim() : '';
    var expectedMaker = (productNameRow[nameCol + 2] != null) ? String(productNameRow[nameCol + 2]).trim() : '';
