        packageLCm: res.packageLCm != null ? res.packageLCm : '',
        packageWCm: res.packageWCm != null ? res.packageWCm : '',
        packageHCm: res.packageHCm != null ? res.packageHCm : '',
        packageWeightG: res.packageWeightG != null ? res.packageWeightG : ''
