// Gemini API呼び出し
// Gemini API呼び出し (JSON生成用・検索OFF)
function callGeminiVisionAPI(promptText, base64Image, mimeType) {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${MODEL_GEMINI}:generateContent?key=${getGeminiApiKey()}`;
  
  const parts = [{ text: promptText }];
  if (base64Image && mimeType) {
    parts.push({
      inline_data: { mime_type: mimeType, data: base64Image }
    });
  }
  
  const payload = {
    contents: [{ parts: parts }],
    // ★修正: 本番生成時は検索OFF (JSONモード優先)
    generationConfig: { response_mime_type: "application/json" }
  };
  
  const options = {
    method: 'post',
    contentType: 'application/json',
    payload: JSON.stringify(payload),
    muteHttpExceptions: true
  };
  
  const res = UrlFetchApp.fetch(url, options);
  const json = JSON.parse(res.getContentText());
  
  if (json.error) throw new Error(json.error.message);
  
  try {
    const rawText = json.candidates[0].content.parts[0].text;
    return JSON.parse(rawText);
  } catch (e) {
    // 調査用ログ: パース失敗 or candidates/parts なし
    var rawText = null;
    try {
      if (json.candidates && json.candidates[0] && json.candidates[0].content && json.candidates[0].content.parts && json.candidates[0].content.parts[0]) {
        rawText = json.candidates[0].content.parts[0].text;
      }
    } catch (e2) {}
    if (rawText != null) {
      Logger.log('[Gemini調査] JSONパース失敗 例外=' + (e && e.message) + ' 応答長=' + (String(rawText).length || 0) + ' 先頭300字=' + (String(rawText).substring(0, 300) || ''));
    } else {
      Logger.log('[Gemini調査] 応答構造異常 candidates数=' + (json.candidates ? json.candidates.length : 0) + ' promptFeedback=' + (json.promptFeedback ? JSON.stringify(json.promptFeedback) : 'なし'));
    }
    return { error: "JSON parse error", raw: json };
  }
}

// Gemini API呼び出し (検索調査用・JSONモードOFF)
function callGeminiSearchAPI(promptText) {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${MODEL_GEMINI}:generateContent?key=${getGeminiApiKey()}`;
  
  const payload = {
    contents: [{ parts: [{ text: promptText }] }],
    // ★修正: 最新モデルに対応したシンプル構文に変更 (これでエラーが消えます)
    tools: [{ google_search: {} }],
    generationConfig: {} 
  };
  
  const options = {
    method: 'post',
    contentType: 'application/json',
    payload: JSON.stringify(payload),
    muteHttpExceptions: true
  };
  
  const res = UrlFetchApp.fetch(url, options);
  const json = JSON.parse(res.getContentText());
  
  if (json.error) throw new Error("Search Error: " + json.error.message);
  
  try {
    return json.candidates[0].content.parts[0].text;
  } catch (e) {
    return "検索結果取得失敗";
  }
}

// OpenAI API呼び出し (復活)
function callOpenAIVisionAPI(promptText, base64Image, mimeType) {
  const url = 'https://api.openai.com/v1/chat/completions';
  const content = [{ type: "text", text: promptText }];
  if (base64Image && mimeType) {
    content.push({
      type: "image_url",
      image_url: { url: `data:${mimeType};base64,${base64Image}` }
    });
  }
  const payload = {
    model: MODEL_OPENAI,
    messages: [{ role: "user", content: content }],
    response_format: { type: "json_object" }
  };
  const options = {
    method: 'post',
    contentType: 'application/json',
    headers: { Authorization: `Bearer ${getOpenAiApiKey()}` },
    payload: JSON.stringify(payload),
    muteHttpExceptions: true
  };
  const res = UrlFetchApp.fetch(url, options);
  const json = JSON.parse(res.getContentText());
  if (json.error) throw new Error(json.error.message);
  return JSON.parse(json.choices[0].message.content);
}




