/**
 * 機能1: 画像をAI解析し、数字ロジックで振り分ける (メイン10列+サブ10列 安全版)
 */
/**
 * 楽天マトリクス: ファイル名に子SKUを含む画像を MAIN1／サブN へ先に自動投入（U2-ε 転用）。
 * @param {Array} displayRows Parent/Child 行オブジェクト
 * @param {GoogleAppsScript.Drive.File[]} fileList
 * @param {string} runId
 * @return {{usedIds:Object, main:number, sub:number, skippedExisting:number, candidateOnly:number, skippedOff:boolean}}
 */
function rakutenMatrixAutobindByFilename_(displayRows, fileList, runId) {
  var out = {
    usedIds: {},
    main: 0,
    sub: 0,
    skippedExisting: 0,
    candidateOnly: 0,
    skippedOff: false
  };
  if (!getBoolScriptProperty_(RAKUTEN_IMAGE_MAIN_AUTOBIND_PROP, true)) {
    out.skippedOff = true;
    Logger.log(
      '[rakutenFilenameAutobind] runId=' +
        runId +
        ' state=SKIP prop_off'
    );
    return out;
  }

  var childRows = [];
  var i;
  for (i = 0; i < displayRows.length; i++) {
    if (displayRows[i].type === 'Child' && displayRows[i].cCode) {
      childRows.push(displayRows[i]);
    }
  }

  for (i = 0; i < fileList.length; i++) {
    var file = fileList[i];
    var fileName = file.getName();
    var norm = rakutenImageNormalize_(fileName);
    var child = rakutenImageFindChildRow_(childRows, norm);
    if (!child) {
      var parentHit = rakutenImageFindParentRow_(displayRows, norm);
      if (parentHit) {
        var imageUrlP =
          'https://drive.google.com/uc?export=view&id=' + file.getId();
        var formulaP = '=IMAGE("' + imageUrlP + '", 2)';
        if (pushToEmptySlot(parentHit.assignedCandidates, formulaP)) {
          out.candidateOnly++;
          out.usedIds[file.getId()] = true;
        }
      }
      continue;
    }

    var imageUrl = 'https://drive.google.com/uc?export=view&id=' + file.getId();
    var formula = '=IMAGE("' + imageUrl + '", 2)';
    var subN = rakutenImageParseSubSlot_(fileName);

    if (subN !== null) {
      var subIdx = subN - 1;
      if (child.assignedSubs[subIdx]) {
        out.skippedExisting++;
        if (pushToEmptySlot(child.assignedCandidates, formula)) {
          out.candidateOnly++;
        }
        out.usedIds[file.getId()] = true;
        continue;
      }
      child.assignedSubs[subIdx] = formula;
      out.sub++;
      out.usedIds[file.getId()] = true;
      continue;
    }

    // MAIN: メイン1のみ自動（空き時）。既存あり／余りは候補
    if (child.assignedMains[0]) {
      out.skippedExisting++;
      if (pushToEmptySlot(child.assignedCandidates, formula)) {
        out.candidateOnly++;
      }
      out.usedIds[file.getId()] = true;
      continue;
    }
    child.assignedMains[0] = formula;
    out.main++;
    out.usedIds[file.getId()] = true;
  }

  Logger.log(
    '[rakutenFilenameAutobind] runId=' +
      runId +
      ' state=DONE main=' +
      out.main +
      ' sub=' +
      out.sub +
      ' skippedExisting=' +
      out.skippedExisting +
      ' candidateOnly=' +
      out.candidateOnly +
      ' used=' +
      Object.keys(out.usedIds).length
  );
  return out;
}

/** ファイル名・SKU比較用（小文字化＋英数字以外除去） */
function rakutenImageNormalize_(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

/** _subN または _pN → 1..10。無ければ null（MAIN） */
function rakutenImageParseSubSlot_(fileName) {
  var m = String(fileName || '').match(/_sub(\d+)/i);
  if (!m) m = String(fileName || '').match(/_p(\d+)/i);
  if (!m) return null;
  var n = parseInt(m[1], 10);
  if (isNaN(n) || n < 1 || n > 10) return null;
  return n;
}

/** ファイル名に子SKUを含む行（最長一致） */
function rakutenImageFindChildRow_(childRows, normalizedName) {
  var best = null;
  var bestLen = 0;
  var i;
  for (i = 0; i < childRows.length; i++) {
    var key = rakutenImageNormalize_(childRows[i].cCode);
    if (!key || normalizedName.indexOf(key) < 0) continue;
    if (key.length > bestLen) {
      best = childRows[i];
      bestLen = key.length;
    }
  }
  return best;
}

/** 親SKUのみ一致（候補配置用） */
function rakutenImageFindParentRow_(displayRows, normalizedName) {
  var i;
  for (i = 0; i < displayRows.length; i++) {
    if (displayRows[i].type !== 'Parent') continue;
    var key = rakutenImageNormalize_(displayRows[i].pCode);
    if (key && normalizedName.indexOf(key) >= 0) return displayRows[i];
  }
  return null;
}

function generateAiImageMatrix() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const masterSheet = ss.getSheetByName(MASTER_SHEET_NAME);
  const ui = SpreadsheetApp.getUi();

  // --- 1. マスタデータの読み込み ---
  const mValues = masterSheet.getDataRange().getValues();
  const headerRowIdx = getAnchorRowIndex(mValues); 

  if (headerRowIdx === -1) { 
    ui.alert(`マスタシートのヘッダー行が見つかりません。\n「${COL_NAME_PARENT_SKU}」と「${COL_NAME_CHECK}」の両方を含む行が必要です。`); 
    return; 
  }

  const headers = mValues[headerRowIdx];
  const colMap = getColumnIndexMap(headers);
  
  const idxP = colMap[COL_NAME_PARENT_SKU];
  const idxC = colMap[COL_NAME_CHILD_SKU];
  const idxName = colMap[COL_NAME_ITEM_NAME];
  const idxVar = colMap[COL_NAME_VAR_NAME];
  const idxRef = colMap['▼マスタ(参考情報(画像URL))'] !== undefined ? colMap['▼マスタ(参考情報(画像URL))'] : -1;
  const idxCheck = colMap[COL_NAME_CHECK];

  if (idxP === undefined || idxCheck === undefined) { 
    ui.alert('必須列（親SKU または 出品CK）が見つかりません'); return; 
  }

  function isMasterCheckTrue_(v) {
    return v === true || v === 1 || String(v).toUpperCase() === 'TRUE';
  }

  // --- 商品構造リスト作成 ---
  // 選定規則（2026-07-25）:
  // ・子にレ点あり → その親＋レ点子のみ（兄弟セットは出さない）
  // ・子レ点なし＆親のみレ点 → 従来どおり親＋全子（楽天運用互換）
  const productGroups = {};
  const displayRows = [];
  const CANDIDATE_LIMIT = 50;
  const parentMeta = {};

  for (let i = headerRowIdx + 1; i < mValues.length; i++) {
    const row = mValues[i];
    const pCode = String(row[idxP]).trim();
    const cCode = (idxC !== undefined) ? String(row[idxC]).trim() : '';
    if (pCode === '') continue;

    if (cCode === '') {
      const name = (idxName !== undefined) ? String(row[idxName]).trim() : '';
      let refUrl = (idxRef !== -1) ? String(row[idxRef]).trim() : '';
      if (!parentMeta[pCode]) {
        parentMeta[pCode] = { name: name, refImg: refUrl, parentChecked: false, children: [] };
      } else {
        if (name) parentMeta[pCode].name = name;
        if (refUrl) parentMeta[pCode].refImg = refUrl;
      }
      parentMeta[pCode].parentChecked = isMasterCheckTrue_(row[idxCheck]);
    } else {
      if (!parentMeta[pCode]) {
        parentMeta[pCode] = { name: '', refImg: '', parentChecked: false, children: [] };
      }
      parentMeta[pCode].children.push({
        cCode: cCode,
        varName: (idxVar !== undefined) ? String(row[idxVar]).trim() : '',
        checked: isMasterCheckTrue_(row[idxCheck])
      });
    }
  }

  function makeParentObj_(pCode, meta) {
    return {
      type: 'Parent',
      pCode: pCode,
      cCode: '',
      name: meta.name || '',
      varName: '',
      refImg: meta.refImg || '',
      assignedMains: new Array(10).fill(''),
      assignedSubs: new Array(10).fill(''),
      assignedCandidates: new Array(CANDIDATE_LIMIT).fill(''),
      children: []
    };
  }

  function makeChildObj_(parentObj, ch) {
    return {
      type: 'Child',
      pCode: parentObj.pCode,
      cCode: ch.cCode,
      name: parentObj.name,
      varName: ch.varName,
      refImg: '',
      assignedMains: new Array(10).fill(''),
      assignedSubs: new Array(10).fill(''),
      assignedCandidates: new Array(CANDIDATE_LIMIT).fill('')
    };
  }

  Object.keys(parentMeta).forEach(function (pCode) {
    const meta = parentMeta[pCode];
    const checkedChildren = meta.children.filter(function (ch) { return ch.checked; });
    let childrenToAdd = [];
    let include = false;

    if (checkedChildren.length > 0) {
      include = true;
      childrenToAdd = checkedChildren;
    } else if (meta.parentChecked) {
      include = true;
      childrenToAdd = meta.children.slice();
    }
    if (!include) return;

    const parentObj = makeParentObj_(pCode, meta);
    productGroups[pCode] = parentObj;
    displayRows.push(parentObj);
    childrenToAdd.forEach(function (ch) {
      const childObj = makeChildObj_(parentObj, ch);
      parentObj.children.push(childObj);
      displayRows.push(childObj);
    });
  });

  Logger.log(
    '[generateAiImageMatrix] selection parents=' +
      Object.keys(productGroups).length +
      ' displayRows=' +
      displayRows.length +
      ' (child-check優先 / 親のみレ点は全子)'
  );

  if (displayRows.length === 0) {
    ui.alert(
      '出品対象の商品がありません。\n' +
        '・子SKU行に出品CKを付ける（推奨・その子だけ出ます）\n' +
        '・または親行のみに出品CK（従来どおりその親の全子が出ます）'
    );
    return;
  }

  // --- 2. 画像ファイルの準備 ---
  let sourceFolder, workFolder;
  try {
    sourceFolder = DriveApp.getFolderById(DRIVE_IMAGE_SOURCE_FOLDER_ID);
    const folders = sourceFolder.getFoldersByName(WORK_FOLDER_NAME);
    if (folders.hasNext()) workFolder = folders.next();
    else workFolder = sourceFolder.createFolder(WORK_FOLDER_NAME);
    try { workFolder.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW); } catch(e){}
  } catch (e) {
    ui.alert(`フォルダエラー: ${e.message}`); return;
  }

  const files = sourceFolder.getFiles();
  const fileList = [];
  let limitCounter = 0;
  const PROCESS_LIMIT = 50; 

  while (files.hasNext()) {
    if (limitCounter >= PROCESS_LIMIT) break;
    const f = files.next();
    if (f.getMimeType().startsWith('image/')) {
      try {
        f.moveTo(workFolder);
        fileList.push(f);
      } catch(e) {
        fileList.push(f.makeCopy(f.getName(), workFolder));
      }
      limitCounter++;
    }
  }
  if (fileList.length === 0) {
    const wFiles = workFolder.getFiles();
    while (wFiles.hasNext()) {
      if (limitCounter >= PROCESS_LIMIT) break;
      fileList.push(wFiles.next());
      limitCounter++;
    }
  }
  if (fileList.length === 0) {
    if (!getBoolScriptProperty_('AMAZON_IMAGE_U2_ENABLED', false)) {
      ui.alert('画像が見つかりません');
      return;
    }
    Logger.log(
      '[generateAiImageMatrix] state=CONTINUE reason=no_rakuten_images ' +
        'AMAZON_IMAGE_U2_ENABLED=true（Amazon用の空マトリクスを生成）'
    );
  }

  // --- 3. シート準備 ---
  let sheet = ss.getSheetByName(SHEET_NAME_MATRIX);
  if (sheet) sheet.clear();
  else sheet = ss.insertSheet(SHEET_NAME_MATRIX);

  // ヘッダー作成 (固定枠20列 + 候補枠50列)
  const candidateHeaders = Array.from({length: CANDIDATE_LIMIT}, (_, i) => `候補${i+1}`);
  
  // 1行目: エリア説明
  const header1 = ['商品情報', '', '', '', '', '▼アップロード対象 (ここに移動)', ...new Array(19).fill(''), '▼未整理・候補 (ここから左へドラッグ)', ...new Array(CANDIDATE_LIMIT-1).fill('')];
  
  // 2行目: 項目名
  const header2 = ['親SKU', '子SKU', '商品名', 'バリエーション値', '参考画像', ...RAKUTEN_IMAGE_COLS, ...candidateHeaders];
  const totalCols = header2.length;

  sheet.getRange(1, 1, 1, totalCols).setValues([header1]).setFontWeight('bold').setFontColor('white');
  sheet.getRange(1, 1, 1, 5).setBackground('#4c1130'); // 商品情報
  sheet.getRange(1, 6, 1, 20).setBackground('#0b5394'); // アップロード対象
  sheet.getRange(1, 26, 1, CANDIDATE_LIMIT).setBackground('#666666'); // 候補エリア

  sheet.getRange(2, 1, 1, totalCols).setValues([header2]).setBackground('#d9d9d9').setFontWeight('bold');
  sheet.setFrozenRows(2);
  sheet.setFrozenColumns(5);

  // --- 4. ファイル名 SKU 自動投入（先）→ 余りは従来 AI 仕分け ---
  const parents = Object.values(productGroups);
  const productListText = parents.map((p, i) => `${i}: ${p.name} (ID: ${p.pCode})`).join('\n');
  const runId =
    Utilities.formatDate(new Date(), Session.getScriptTimeZone() || 'Asia/Tokyo', 'yyyyMMdd_HHmmss') +
    '_' +
    String(Math.floor(Math.random() * 1e6)).padStart(6, '0');
  Logger.log('[generateAiImageMatrix] runId=' + runId + ' state=RUNNING files=' + fileList.length);

  const skuBind = rakutenMatrixAutobindByFilename_(displayRows, fileList, runId);
  let aiAssigned = 0;
  let aiSkippedUsed = 0;

  for (const file of fileList) {
    if (skuBind.usedIds[file.getId()]) {
      aiSkippedUsed++;
      continue;
    }
    const fileName = file.getName();
    SpreadsheetApp.getActive().toast(`AI解析中... ${fileName}`);
    try { file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW); } catch(e){}

    const imageUrl = `https://drive.google.com/uc?export=view&id=${file.getId()}`;
    const imageFormula = `=IMAGE("${imageUrl}", 2)`; 

    const prompt = `
    Analyze this product image.
    Match it to one of the products below.
    [Product List]
    ${productListText}
    Task:
    1. Identify the matching product index.
    2. Does the image contain a NUMBER indicating quantity/set count? (e.g. "3" in "3袋", "10" in "10 sets").
    3. Is it a "Main" image (package/front) or "Sub" image (detail/cooking/back)?
    Output JSON: {"matched_index": 0, "quantity_number": 3, "type": "Main" or "Sub"}
    `;

    let assigned = false;
    try {
      const blob = file.getBlob();
      const base64 = Utilities.base64Encode(blob.getBytes());
      const res = callGeminiVision(prompt, base64, blob.getContentType());
      const result = JSON.parse(res.replace(/```json|```/g, '').trim());

      if (result.matched_index !== -1 && parents[result.matched_index]) {
        const parent = parents[result.matched_index];
        let targetObj = parent; // デフォルトは親

        // 数字判定があれば子SKUへターゲットを変更
        if (result.quantity_number !== null && String(result.quantity_number) !== "" && result.type === 'Main') {
          const targetChild = parent.children.find(c => extractNumbers(c.varName).includes(String(result.quantity_number)));
          if (targetChild) targetObj = targetChild;
        }

        // 配置ロジック: Main/Sub判定を尊重しつつ、空いている青枠に積極的に入れる
        let placed = false;
        
        // 1. Main判定の場合: メイン枠 -> サブ枠(親) の順でトライ
        if (result.type === 'Main') {
           placed = pushToEmptySlot(targetObj.assignedMains, imageFormula);
           if (!placed) placed = pushToEmptySlot(parent.assignedSubs, imageFormula);
        } 
        // 2. Sub判定(または不明)の場合: サブ枠(親) -> メイン枠 の順でトライ
        else {
           placed = pushToEmptySlot(parent.assignedSubs, imageFormula);
           if (!placed) placed = pushToEmptySlot(targetObj.assignedMains, imageFormula);
        }

        // 3. それでも満杯なら候補枠へ
        if (!placed) {
           pushToEmptySlot(targetObj.assignedCandidates, imageFormula);
        }
        assigned = true;
        aiAssigned++;
      }
    } catch (e) { console.warn(`AI Error: ${e.message}`); }

    // マッチしない画像は先頭行の「青枠(メイン/サブ)」へ優先的に入れる
    if (!assigned && displayRows.length > 0) {
       const firstRow = displayRows[0];
       // メイン -> サブ -> 候補 の順で空きを探して入れる
       if (!pushToEmptySlot(firstRow.assignedMains, imageFormula)) {
          if (!pushToEmptySlot(firstRow.assignedSubs, imageFormula)) {
             pushToEmptySlot(firstRow.assignedCandidates, imageFormula);
          }
       }
    }
  }

  Logger.log(
    '[generateAiImageMatrix] runId=' +
      runId +
      ' state=DONE skuMain=' +
      skuBind.main +
      ' skuSub=' +
      skuBind.sub +
      ' skuSkipExisting=' +
      skuBind.skippedExisting +
      ' aiAssigned=' +
      aiAssigned +
      ' aiSkippedUsed=' +
      aiSkippedUsed +
      ' propOff=' +
      skuBind.skippedOff
  );

  // --- 5. 出力 ---
  const outputRows = displayRows.map(row => {
    let refFunc = '';
    if (row.type === 'Parent' && row.refImg) refFunc = `=IMAGE("${row.refImg}", 2)`;
    else if (row.type === 'Child' && productGroups[row.pCode].refImg) refFunc = `=IMAGE("${productGroups[row.pCode].refImg}", 2)`;
    
    return [
      row.pCode, row.cCode, row.name, row.varName, refFunc, 
      ...row.assignedMains, 
      ...row.assignedSubs,
      ...row.assignedCandidates // 右端に追加
    ];
  });

  if (outputRows.length > 0) {
    const range = sheet.getRange(3, 1, outputRows.length, outputRows[0].length);
    range.setValues(outputRows);
    
    sheet.setRowHeights(3, outputRows.length, 100);
    sheet.setColumnWidth(5, 100);
    sheet.setColumnWidths(6, 20, 100); // メイン・サブエリア
    sheet.setColumnWidths(26, CANDIDATE_LIMIT, 60); // 候補エリアは狭く
    sheet.getRange(3, 1, outputRows.length, 4).setWrapStrategy(SpreadsheetApp.WrapStrategy.WRAP);
    
    // 青枠でアップロード対象を囲む
    sheet.getRange(3, 6, outputRows.length, 20).setBorder(true, true, true, true, true, true, '#0000ff', SpreadsheetApp.BorderStyle.SOLID_MEDIUM);
  }

  // U2: Amazon 枠（col76+）＋マスタから復元（ENABLED時のみ）
  try {
    amazonImageMatrixOnAfterGenerate_(ss, sheet);
  } catch (eAmz) {
    console.warn('[generateAiImageMatrix] Amazon U2 hook: ' + ((eAmz && eAmz.message) || eAmz));
  }

  ui.alert(
    '仕分け完了（runId=' +
      runId +
      '）。\n' +
      '・ファイル名SKU自動: MAIN ' +
      skuBind.main +
      ' / サブ ' +
      skuBind.sub +
      '（既存スキップ ' +
      skuBind.skippedExisting +
      '）\n' +
      '・青枠内：アップロード対象（楽天）\n' +
      '・右側のグレー枠：候補・未整理\n' +
      '・列76以降：Amazon MAIN/PT（U2・Property有効時）\n\n' +
      '必要な画像を右側から枠内へドラッグ移動してください。\n' +
      '戻し: RAKUTEN_IMAGE_MAIN_AUTOBIND_ENABLED=false'
  );
}


/**
 * マトリクスから R-Cabinet アップロード＋マスタ反映（UI なし呼び出し用）。
 * @param {GoogleAppsScript.Spreadsheet.Spreadsheet} ss
 * @param {{ skipConfirm?: boolean }} options
 * @returns {{ cancelled: boolean, blocked: string|null, successCount: number, errorCount: number, skipCount: number }}
 */
function executeRenameAndUploadFromMatrixProgrammatic_(ss, options) {
  options = options || {};
  var skipConfirm = options.skipConfirm === true;
  const matrixSheet = ss.getSheetByName(SHEET_NAME_MATRIX);
  const masterSheet = ss.getSheetByName(MASTER_SHEET_NAME);
  const settingSheet = ss.getSheetByName(SETTING_SHEET_NAME);
  var ui = null;
  try {
    ui = SpreadsheetApp.getUi();
  } catch (eU) {}

  console.log('🚀 アップロード処理を開始します...');
  console.log(
    '[R-Cabinet画像] ' +
      RAKUTEN_CABINET_IMAGE_PIPELINE_TAG +
      ' maxBytes=' +
      RAKUTEN_CABINET_MAX_IMAGE_BYTES +
      ' thumb=' +
      RAKUTEN_DRIVE_THUMB_FETCH_MODE
  );

  if (!matrixSheet) return { cancelled: false, blocked: 'NO_MATRIX', successCount: 0, errorCount: 0, skipCount: 0 };
  if (!masterSheet) return { cancelled: false, blocked: 'NO_MASTER_SHEET', successCount: 0, errorCount: 0, skipCount: 0 };

  let rcabinetId = '0';
  if (settingSheet) {
    const v = settingSheet.getRange('B9').getValue();
    if (v) rcabinetId = String(v).trim();
  }
  console.log('R-CabinetフォルダID: ' + rcabinetId);

  if (!skipConfirm && ui) {
    if (ui.alert('実行確認', '画像をアップロードし、マスタへURLを書き込みます。\nよろしいですか？', ui.ButtonSet.YES_NO) !== ui.Button.YES) {
      return { cancelled: true, blocked: null, successCount: 0, errorCount: 0, skipCount: 0 };
    }
  }

  const mValues = masterSheet.getDataRange().getValues();
  const mHeaderIdx = getAnchorRowIndex(mValues);
  if (mHeaderIdx === -1) return { cancelled: false, blocked: 'NO_MASTER_HEADER', successCount: 0, errorCount: 0, skipCount: 0 };

  const mHeaders = mValues[mHeaderIdx];
  const mColMap = getColumnIndexMap(mHeaders);
  const mPCodeIdx = mColMap[COL_NAME_PARENT_SKU];
  const mCCodeIdx = mColMap[COL_NAME_CHILD_SKU];

  const rowMap = {};
  for (let i = mHeaderIdx + 1; i < mValues.length; i++) {
    const p = String(mValues[i][mPCodeIdx]).trim();
    const c = mCCodeIdx !== undefined ? String(mValues[i][mCCodeIdx]).trim() : '';
    if (p) {
      const key = c ? p + '_' + c : p;
      rowMap[key] = i + 1;
    }
  }

  const lastRow = matrixSheet.getLastRow();
  if (lastRow < 3) return { cancelled: false, blocked: 'NO_MATRIX_DATA', successCount: 0, errorCount: 0, skipCount: 0 };

  const formulas = matrixSheet.getRange(3, 1, lastRow - 2, 25).getFormulas();
  const values = matrixSheet.getRange(3, 1, lastRow - 2, 25).getValues();

  console.log('対象行数: ' + formulas.length + ' 行');

  const archiveFolder = DriveApp.getFolderById(DRIVE_IMAGE_ARCHIVE_FOLDER_ID);
  let successCount = 0;
  let errorCount = 0;
  let skipCount = 0;
  const processedFileIds = new Set();
  const uploadedUrlMap = new Map();

  for (let r = 0; r < formulas.length; r++) {
    const pCode = String(values[r][0]).trim();
    const cCode = String(values[r][1]).trim();
    if (!pCode) {
      console.log('行' + (r + 3) + ': 親SKUがないためスキップ');
      continue;
    }

    const isChild = cCode !== '';
    const rowKey = isChild ? pCode + '_' + cCode : pCode;

    for (let c = 5; c < 25; c++) {
      const cellFormula = formulas[r][c];

      if (!cellFormula || !cellFormula.includes('IMAGE')) {
        continue;
      }

      const match = cellFormula.match(/id=([a-zA-Z0-9_-]+)/);
      if (!match) {
        console.warn('行' + (r + 3) + '列' + (c + 1) + ': 数式はあるがID抽出に失敗 -> ' + cellFormula);
        skipCount++;
        continue;
      }

      const fileId = match[1];
      const slotIndex = c - 5;

      console.log('>> 処理中: 行' + (r + 3) + ' / 画像枠' + slotIndex + ' (FileID: ' + fileId + ')');

      let targetFileName = '';
      let targetColName = '';

      if (slotIndex < 10) {
        const suffix = slotIndex;
        if (isChild) targetFileName = suffix === 0 ? cCode + '.jpg' : cCode + '_' + suffix + '.jpg';
        else targetFileName = suffix === 0 ? pCode + '.jpg' : pCode + '_' + suffix + '.jpg';
        targetColName = '楽天メイン画像' + (slotIndex + 1);
      } else {
        const subIdx = slotIndex - 9;
        targetFileName = pCode + '_sub' + subIdx + '.jpg';
        targetColName = '楽天サブ画像' + subIdx;
      }

      try {
        const file = DriveApp.getFileById(fileId);

        let imageUrl = '';
        let isNewUpload = false;

        if (uploadedUrlMap.has(fileId)) {
          imageUrl = uploadedUrlMap.get(fileId);
          console.log('   ♻️ キャッシュ利用(アップロード省略): ' + imageUrl);
        } else {
          file.setName(targetFileName);
          var blobToSend = prepareBlobForRakutenCabinetUpload_(file, targetFileName);
          console.log(
            '   [R-Cabinet送信/初回] bytes=' +
              blobToSend.getBytes().length +
              ' ct=' +
              (blobToSend.getContentType() || '') +
              ' name=' +
              targetFileName
          );
          var res = callRCabinetInsertFile(blobToSend, targetFileName, rcabinetId);
          if (!res.success && rakutenCabinetUploadShouldRetryWithShrunk_(res.message)) {
            var capList = [1600, 1280, 1024, 800, 640, 480];
            for (var capI = 0; capI < capList.length; capI++) {
              var capPx = capList[capI];
              var blobRetry = tryFetchDriveThumbnailBlobForRakuten_(
                file.getId(),
                targetFileName,
                RAKUTEN_CABINET_MAX_IMAGE_BYTES,
                capPx
              );
              if (!blobRetry) continue;
              console.log(
                '   🔁 再試行: サムネ capLongEdgePx=長辺≤' +
                  capPx +
                  ' JPEG bytes=' +
                  blobRetry.getBytes().length
              );
              res = callRCabinetInsertFile(blobRetry, targetFileName, rcabinetId);
              if (res.success) break;
            }
          }

          if (!res.success) {
            console.error('   ❌ アップロード失敗: ' + res.message);
            matrixSheet.getRange(r + 3, c + 1).setBackground('#f4cccc');
            matrixSheet.getRange(r + 3, c + 1).setNote(res.message);
            errorCount++;
            continue;
          }

          imageUrl = res.imageUrl;
          uploadedUrlMap.set(fileId, imageUrl);
          isNewUpload = true;
          console.log('   ✅ 新規アップロード成功: ' + imageUrl);
        }

        const targetColIdx = mColMap[targetColName];
        const writeRow = rowMap[rowKey];

        if (writeRow && targetColIdx !== undefined) {
          masterSheet.getRange(writeRow, targetColIdx + 1).setValue(imageUrl);
          console.log('      -> マスタ(' + writeRow + '行目, ' + targetColName + ')に保存');
        } else {
          console.warn('      -> ⚠️ マスタに行または列が見つかりません (Row:' + writeRow + ', Col:' + targetColName + ')');
        }

        if (targetColName === '楽天メイン画像1') {
          const whiteBgIdx = findMasterColumnIndexWhiteBg_(mColMap);
          if (writeRow && whiteBgIdx !== undefined) {
            masterSheet.getRange(writeRow, whiteBgIdx + 1).setValue(imageUrl);
            console.log('      -> 白背景列にも保存');
          }
        }

        if (isNewUpload && !processedFileIds.has(fileId)) {
          try {
            file.moveTo(archiveFolder);
          } catch (eM) {}
          processedFileIds.add(fileId);
        }

        matrixSheet.getRange(r + 3, c + 1).setBackground('#d9ead3');
        successCount++;

        if (isNewUpload) Utilities.sleep(200);
      } catch (e) {
        console.error('   ❌ システムエラー: ' + e.message);
        matrixSheet.getRange(r + 3, c + 1).setBackground('#f4cccc');
        errorCount++;
      }
    }
  }

  const resultMsg = '処理完了\n成功: ' + successCount + ' 件\n失敗: ' + errorCount + ' 件\nスキップ(ID取得不可など): ' + skipCount + ' 件';
  console.log(resultMsg);
  return { cancelled: false, blocked: null, successCount: successCount, errorCount: errorCount, skipCount: skipCount };
}

/**
 * 機能2: リネーム＆アップロード実行 (デバッグログ強化版)
 */
function executeRenameAndUploadFromMatrix() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const ui = SpreadsheetApp.getUi();
  const res = executeRenameAndUploadFromMatrixProgrammatic_(ss, { skipConfirm: false });
  if (res.cancelled) return;
  if (res.blocked === 'NO_MATRIX') {
    ui.alert('【エラー】画像マッチングシートが見つかりません');
    return;
  }
  if (res.blocked === 'NO_MASTER_SHEET') {
    ui.alert('【エラー】マスタシートが見つかりません');
    return;
  }
  if (res.blocked === 'NO_MASTER_HEADER') {
    ui.alert('マスタのヘッダーが見つかりません');
    return;
  }
  if (res.blocked === 'NO_MATRIX_DATA') {
    ui.alert('画像シートにデータがありません');
    return;
  }
  ui.alert('処理完了\n成功: ' + res.successCount + ' 件\n失敗: ' + res.errorCount + ' 件\nスキップ(ID取得不可など): ' + res.skipCount + ' 件');
}

// ------------------------------------------
// 共通関数
// ------------------------------------------
function pushToEmptySlot(array, val) {
  for (let k = 0; k < array.length; k++) {
    if (array[k] === '') {
      array[k] = val;
      return true;
    }
  }
  return false;
}
function extractNumbers(str) {
  // 文字列から数字のみを配列で抽出 ("3袋" -> ["3"])
  const matches = str.match(/\d+/g);
  return matches ? matches : [];
}
function getAnchorRowIndex(values) {
  const targetKey1 = COL_NAME_PARENT_SKU; 
  const targetKey2 = COL_NAME_CHECK;      
  for (let r = 0; r < 20; r++) { 
    if (!values[r]) continue;
    let has1 = false, has2 = false;
    for (let c = 0; c < values[r].length; c++) {
      const v = String(values[r][c]).trim();
      if(v === targetKey1) has1 = true;
      if(v === targetKey2) has2 = true;
    }
    if (has1 && has2) return r; 
  }
  return -1; 
}
function getColumnIndexMap(headers) {
  const m = {};
  headers.forEach((v, i) => {
    var key = String(v).trim();
    if (m[key] === undefined) m[key] = i;
  });
  return m;
}
function callGeminiVision(prompt, base64, mime) {
  const url = `https://generativelanguage.googleapis.com/v1beta/${GEMINI_VISION_MODEL}:generateContent?key=${getGeminiApiKey()}`;
  const payload = { contents: [{ parts: [{ text: prompt }, { inline_data: { mime_type: mime, data: base64 } }] }] };
  const res = UrlFetchApp.fetch(url, { method: 'post', contentType: 'application/json', payload: JSON.stringify(payload), muteHttpExceptions: true });
  return res.getContentText();
}

/** マスタヘッダー map から白背景列の 0-based インデックス */
function findMasterColumnIndexWhiteBg_(mColMap) {
  if (!mColMap) return undefined;
  if (mColMap['楽天白背景画像'] !== undefined) return mColMap['楽天白背景画像'];
  if (mColMap['楽天白背景画'] !== undefined) return mColMap['楽天白背景画'];
  return undefined;
}

/** Drive API エラー JSON からログ用1行（原因特定） */
function driveApiErrorSnippetForLog_(bodyText, maxLen) {
  var lim = maxLen != null ? maxLen : 400;
  var t = bodyText != null ? String(bodyText) : '';
  try {
    var j = JSON.parse(t);
    if (j.error) {
      var e = j.error;
      var reason = e.errors && e.errors[0] ? e.errors[0].reason : '';
      var msg = e.message || '';
      return 'Drive API error: ' + msg + (reason ? ' (' + reason + ')' : '');
    }
  } catch (ignore) {}
  return t.length > lim ? t.substring(0, lim) + '…' : t;
}

/**
 * アップロード直前の一本化: 可能なら JPEG に変換（ファイル名・MIME を揃える）。
 * 透過 PNG 等は背景が塗りつぶされることがある。
 */
function convertBlobToJpegForRakuten_(blob, targetFileName) {
  var rawIn = blob.getBytes().length;
  var ctIn = blob.getContentType ? blob.getContentType() || '' : '';
  var b = blob.copyBlob();
  var baseName = String(targetFileName || 'image.jpg').trim();
  if (!/\.jpe?g$/i.test(baseName)) {
    baseName = baseName.replace(/\.[^.]+$/, '') + '.jpg';
  }
  b.setName(baseName);
  try {
    var jpegBlob = b.getAs(MimeType.JPEG);
    jpegBlob.setName(baseName);
    if (jpegBlob.setContentType) jpegBlob.setContentType(MimeType.JPEG);
    var jLen = jpegBlob.getBytes().length;
    if (rawIn >= 150000 || jLen > RAKUTEN_CABINET_MAX_IMAGE_BYTES) {
      console.log(
        '   [R-Cabinet JPEG] raw=' +
          rawIn +
          'B ' +
          ctIn +
          ' → JPEG=' +
          jLen +
          'B (×' +
          (rawIn ? (jLen / rawIn).toFixed(2) : '?') +
          ')'
      );
    }
    return jpegBlob;
  } catch (e) {
    console.warn(
      '   [R-Cabinet JPEG] getAs 失敗 raw=' +
        rawIn +
        'B ct=' +
        ctIn +
        ' … ' +
        (e && e.message ? e.message : String(e)) +
        ' （元Blobで続行）'
    );
    if (b.setContentType) {
      var ct = b.getContentType() || '';
      if (ct.indexOf('image') === -1) b.setContentType(MimeType.JPEG);
    }
    return b;
  }
}

/**
 * Drive から縮小画像 Blob を取得。RAKUTEN_DRIVE_THUMB_FETCH_MODE で切替。
 */
function tryFetchDriveThumbnailBlobForRakuten_(fileId, targetFileName, maxBytes, capLongEdgePx) {
  console.log(
    '   [Driveサムネ] strategy=' +
      RAKUTEN_DRIVE_THUMB_FETCH_MODE +
      ' fileId=' +
      fileId +
      ' maxBytes=' +
      maxBytes +
      (capLongEdgePx ? ' capLongEdgePx≤' + capLongEdgePx : '')
  );
  if (RAKUTEN_DRIVE_THUMB_FETCH_MODE === 'legacy') {
    return tryFetchDriveThumbnailBlobLegacy_(fileId, targetFileName, maxBytes, capLongEdgePx);
  }
  return tryFetchDriveThumbnailBlobFromThumbnailLink_(fileId, targetFileName, maxBytes, capLongEdgePx);
}

/**
 * thumbnailLink から候補 URL を生成。=s / =w の数値が大きい順（maxBytes 以下で最初に成功 = 可能な最大解像度）。
 * @returns {{url: string, px: number}[]} px は長辺指定の目安（ソート用）
 */
function buildDriveThumbnailLinkCandidatesDesc_(thumbnailLink) {
  var sBase = String(thumbnailLink || '').trim();
  var longEdges = [2048, 1920, 1600, 1400, 1280, 1200, 1024, 1000, 800, 640, 480, 320, 220];
  var candidates = [];
  var seen = {};
  function add(u, px) {
    if (!u || seen[u]) return;
    seen[u] = true;
    candidates.push({ url: u, px: px != null ? px : 0 });
  }
  var mS = sBase.match(/=s([0-9]+)/i);
  var mW = sBase.match(/=w([0-9]+)/i);
  if (mS) {
    var origS = parseInt(mS[1], 10);
    var uniqueS = {};
    var i;
    for (i = 0; i < longEdges.length; i++) {
      uniqueS[longEdges[i]] = true;
    }
    uniqueS[origS] = true;
    var listS = Object.keys(uniqueS).map(function (x) {
      return parseInt(x, 10);
    });
    listS.sort(function (a, b) {
      return b - a;
    });
    for (i = 0; i < listS.length; i++) {
      add(sBase.replace(/=s[0-9]+/i, '=s' + listS[i]), listS[i]);
    }
  } else if (mW) {
    var origW = parseInt(mW[1], 10);
    var uniqueW = {};
    var j;
    for (j = 0; j < longEdges.length; j++) {
      uniqueW[longEdges[j]] = true;
    }
    uniqueW[origW] = true;
    var listW = Object.keys(uniqueW).map(function (x) {
      return parseInt(x, 10);
    });
    listW.sort(function (a, b) {
      return b - a;
    });
    for (j = 0; j < listW.length; j++) {
      add(sBase.replace(/=w[0-9]+/i, '=w' + listW[j]), listW[j]);
    }
  } else {
    add(sBase, 0);
  }
  candidates.sort(function (a, b) {
    return b.px - a.px;
  });
  console.log(
    '   [Driveサムネ/thumbnailLink] candidateCount=' +
      candidates.length +
      ' order=長辺px降順 firstPx=' +
      (candidates.length ? candidates[0].px : '—')
  );
  return candidates;
}

/**
 * files.get(thumbnailLink) → 各候補 URL を GET（公式の流れ）。supportsAllDrives で共有ドライブも参照。
 */
function tryFetchDriveThumbnailBlobFromThumbnailLink_(fileId, targetFileName, maxBytes, capLongEdgePx) {
  var token = ScriptApp.getOAuthToken();
  var metaUrl =
    'https://www.googleapis.com/drive/v3/files/' +
    encodeURIComponent(fileId) +
    '?fields=thumbnailLink&supportsAllDrives=true';
  var metaResp = UrlFetchApp.fetch(metaUrl, {
    headers: { Authorization: 'Bearer ' + token },
    muteHttpExceptions: true,
  });
  var metaCode = metaResp.getResponseCode();
  var metaText = metaResp.getContentText() || '';
  console.log('   [Driveサムネ/thumbnailLink] files.get HTTP ' + metaCode + ' bodyLen=' + metaText.length);
  if (metaCode !== 200) {
    console.warn('   [Driveサムネ/thumbnailLink] files.get 失敗詳細: ' + driveApiErrorSnippetForLog_(metaText, 500));
    return null;
  }
  var meta;
  try {
    meta = JSON.parse(metaText);
  } catch (eMeta) {
    console.warn('   [Driveサムネ/thumbnailLink] JSON 解析失敗 先頭=' + metaText.substring(0, 120));
    return null;
  }
  var link = meta.thumbnailLink;
  if (!link || String(link).trim() === '') {
    console.warn('   [Driveサムネ/thumbnailLink] thumbnailLink 空（Drive がこのファイルのサムネ URL を返していない） fileId=' + fileId);
    return null;
  }
  var linkHead = String(link).substring(0, Math.min(80, String(link).length));
  console.log('   [Driveサムネ/thumbnailLink] thumbnailLink 先頭=' + linkHead + '…');
  var candidates = buildDriveThumbnailLinkCandidatesDesc_(link);
  if (capLongEdgePx != null && capLongEdgePx > 0) {
    var filteredThumb = candidates.filter(function (c) {
      return c.px > 0 && c.px <= capLongEdgePx;
    });
    if (filteredThumb.length) {
      candidates = filteredThumb;
      console.log(
        '   [Driveサムネ/thumbnailLink] cap長辺≤' + capLongEdgePx + 'px に絞り込み → 候補 ' + candidates.length + ' 件'
      );
    } else {
      console.warn(
        '   [Driveサムネ/thumbnailLink] cap長辺≤' + capLongEdgePx + 'px で候補なし → この試行はスキップ'
      );
      return null;
    }
  }
  var ui;
  for (ui = 0; ui < candidates.length; ui++) {
    var cand = candidates[ui];
    var u = cand.url;
    var pxHint = cand.px;
    try {
      var resp = UrlFetchApp.fetch(u, {
        headers: { Authorization: 'Bearer ' + token },
        muteHttpExceptions: true,
        followRedirects: true,
      });
      var code = resp.getResponseCode();
      var usedAuth = true;
      if (code === 401 || code === 403) {
        resp = UrlFetchApp.fetch(u, { muteHttpExceptions: true, followRedirects: true });
        code = resp.getResponseCode();
        usedAuth = false;
      }
      var b = resp.getBlob();
      var rawLen = b ? b.getBytes().length : 0;
      var ct0 = b && b.getContentType ? (b.getContentType() || '') : '';
      var tail = u.length > 64 ? u.substring(u.length - 64) : u;
      console.log(
        '   [Driveサムネ/thumbnailLink] GET HTTP ' +
          code +
          ' bytes=' +
          rawLen +
          ' ct=' +
          (ct0 || '(なし)') +
          ' auth=' +
          usedAuth +
          ' …' +
          tail
      );
      if (code !== 200 || !b) continue;
      if (rawLen < 200) {
        console.log('   [Driveサムネ/thumbnailLink] スキップ: 200バイト未満（プレースホルダの可能性）');
        continue;
      }
      if (ct0.indexOf('text') >= 0 || ct0.indexOf('html') >= 0) {
        try {
          var htmlSnip = Utilities.newBlob(b.getBytes()).getDataAsString().replace(/\s+/g, ' ').substring(0, 220);
          console.warn('   [Driveサムネ/thumbnailLink] 却下: HTML/テキスト応答 抜粋=' + htmlSnip);
        } catch (eH) {
          console.warn('   [Driveサムネ/thumbnailLink] 却下: HTML/テキスト応答（本文ログ不可）');
        }
        continue;
      }
      var copy = b.copyBlob();
      copy.setName(targetFileName);
      var ct = copy.getContentType() || '';
      if (ct.indexOf('image') === -1) copy.setContentType('image/jpeg');
      var jpegBlob = convertBlobToJpegForRakuten_(copy, targetFileName);
      var n = jpegBlob.getBytes().length;
      if (n <= maxBytes) {
        console.log(
          '   📐 Driveサムネ(thumbnailLink) 長辺目安=' +
            pxHint +
            'px → JPEG ' +
            n +
            ' bytes（採用・' +
            maxBytes +
            ' 以内で最大解像度優先）'
        );
        return jpegBlob;
      }
      console.log(
        '   [Driveサムネ/thumbnailLink] スキップ: 生=' +
          rawLen +
          'B JPEG=' +
          n +
          'B > max ' +
          maxBytes +
          ' → 別候補へ'
      );
    } catch (e) {
      console.warn('   [Driveサムネ/thumbnailLink] 例外: ' + (e && e.message ? e.message : String(e)));
    }
  }
  console.warn('   [Driveサムネ/thumbnailLink] 全候補で採用不可（files.get は成功したが画像取得または maxBytes を満たせず） fileId=' + fileId);
  return null;
}

/** 旧 /files/{id}/thumbnail?sz=w…（RAKUTEN_DRIVE_THUMB_FETCH_MODE === 'legacy' のとき） */
function tryFetchDriveThumbnailBlobLegacy_(fileId, targetFileName, maxBytes, capLongEdgePx) {
  var token = ScriptApp.getOAuthToken();
  var widths = [2048, 1920, 1600, 1400, 1280, 1024, 800, 640, 480];
  if (capLongEdgePx != null && capLongEdgePx > 0) {
    widths = widths.filter(function (w) {
      return w <= capLongEdgePx;
    });
    if (!widths.length) {
      console.warn('   [Driveサムネ/legacy] cap長辺≤' + capLongEdgePx + 'px で幅候補なし');
      return null;
    }
    console.log('   [Driveサムネ/legacy] cap長辺≤' + capLongEdgePx + 'px → 試行幅 ' + widths.join(',') + 'px');
  }
  for (var wi = 0; wi < widths.length; wi++) {
    var w = widths[wi];
    var url = 'https://www.googleapis.com/drive/v3/files/' + encodeURIComponent(fileId) + '/thumbnail?sz=w' + w;
    try {
      var resp = UrlFetchApp.fetch(url, {
        headers: { Authorization: 'Bearer ' + token },
        muteHttpExceptions: true,
      });
      var code = resp.getResponseCode();
      var b = resp.getBlob();
      var rawLen = b ? b.getBytes().length : 0;
      var ct0 = b && b.getContentType ? (b.getContentType() || '') : '';
      console.log('   [Driveサムネ/legacy] sz=w' + w + ' HTTP ' + code + ' bytes=' + rawLen + ' ct=' + (ct0 || '(なし)'));
      if (code !== 200) {
        if (code === 404 && ct0.indexOf('html') >= 0 && rawLen > 0 && rawLen < 4000) {
          console.warn('   [Driveサムネ/legacy] HTTP 404 + HTML（/thumbnail エンドポイントが無効な可能性）抜粋=' + driveApiErrorSnippetForLog_(Utilities.newBlob(b.getBytes()).getDataAsString(), 200));
        }
        continue;
      }
      if (!b) continue;
      if (rawLen < 200) {
        console.log('   [Driveサムネ/legacy] スキップ: 200バイト未満');
        continue;
      }
      var copy = b.copyBlob();
      copy.setName(targetFileName);
      var ct = copy.getContentType() || '';
      if (ct.indexOf('image') === -1) copy.setContentType('image/jpeg');
      var jpegBlob = convertBlobToJpegForRakuten_(copy, targetFileName);
      var n = jpegBlob.getBytes().length;
      if (n <= maxBytes) {
        console.log('   📐 Driveサムネ(legacy) w=' + w + ' → JPEG ' + n + ' bytes（採用）');
        return jpegBlob;
      }
      console.log('   [Driveサムネ/legacy] スキップ: 生=' + rawLen + 'B JPEG=' + n + 'B > max ' + maxBytes);
    } catch (e) {
      console.warn('   [Driveサムネ/legacy] 例外 sz=w' + w + ': ' + (e && e.message ? e.message : String(e)));
    }
  }
  console.warn('   [Driveサムネ/legacy] 全幅で採用できず fileId=' + fileId);
  return null;
}

/**
 * オリジナルが生サイズで上限超ならサムネ経由に差し替えのうえ、必ず JPEG 化して上限再チェック。
 * 生サイズは上限内でも JPEG が膨らむ場合があるため、最終的に超えるときはサムネを追加試行する。
 */
function prepareBlobForRakutenCabinetUpload_(file, targetFileName) {
  var fileId = file.getId();
  var raw = file.getBlob().copyBlob();
  raw.setName(targetFileName);
  var rawLen = raw.getBytes().length;
  var blob = raw;
  if (rawLen > RAKUTEN_CABINET_MAX_IMAGE_BYTES) {
    var shrunk = tryFetchDriveThumbnailBlobForRakuten_(fileId, targetFileName, RAKUTEN_CABINET_MAX_IMAGE_BYTES);
    if (shrunk) blob = shrunk;
    else
      console.warn(
        '   ⚠️ 目安上限(' +
          RAKUTEN_CABINET_MAX_IMAGE_BYTES +
          ' bytes)超: サムネ縮小失敗。オリジナルから JPEG 化して続行（生 ' +
          rawLen +
          ' bytes）'
      );
  }
  var out = convertBlobToJpegForRakuten_(blob, targetFileName);
  var outLen = out.getBytes().length;
  var sourceTag = blob === raw ? 'original' : 'drive-thumb';
  if (outLen <= RAKUTEN_CABINET_MAX_IMAGE_BYTES) {
    console.log(
      '   [R-Cabinet準備完了] source=' +
        sourceTag +
        ' 生(max元)=' +
        rawLen +
        ' 送信JPEG=' +
        outLen +
        ' / 上限=' +
        RAKUTEN_CABINET_MAX_IMAGE_BYTES
    );
    return out;
  }
  var shrunk2 = tryFetchDriveThumbnailBlobForRakuten_(fileId, targetFileName, RAKUTEN_CABINET_MAX_IMAGE_BYTES);
  if (shrunk2) out = convertBlobToJpegForRakuten_(shrunk2, targetFileName);
  outLen = out.getBytes().length;
  console.log(
    '   [R-Cabinet準備完了] source=' +
      (shrunk2 ? '2nd-thumb' : 'retry-thumb-失敗→前段JPEGのまま') +
      ' 送信JPEG=' +
      outLen +
      ' / 上限=' +
      RAKUTEN_CABINET_MAX_IMAGE_BYTES +
      (outLen > RAKUTEN_CABINET_MAX_IMAGE_BYTES ? ' (OVER)' : '')
  );
  if (outLen > RAKUTEN_CABINET_MAX_IMAGE_BYTES) {
    console.warn(
      '   ⚠️ JPEG 後も目安上限超: ' +
        out.getBytes().length +
        ' bytes（R-Cabinet で拒否の可能性）。送信します。'
    );
  }
  return out;
}

function rakutenCabinetUploadShouldRetryWithShrunk_(message) {
  if (!message) return false;
  return /size|Capacity|capacity|Image|image|容量|サイズ/i.test(String(message));
}

/**
 * 楽天R-Cabinetへの画像アップロード関数 (完全版)
 * 1. マルチパート形式でアップロード
 * 2. 返却されたFileIdを使って検索APIを叩く
 * 3. 画像URL(FileUrl)を取得して返す
 */

function callRCabinetInsertFile(blob, name, folderId) {
  const authKey = Utilities.base64Encode(`${getRakutenServiceSecret()}:${getRakutenLicenseKey()}`);
  const headers = { 'Authorization': `ESA ${authKey}` };

  // Step 1. 画像のアップロード
  const uploadUrl = 'https://api.rms.rakuten.co.jp/es/1.0/cabinet/file/insert';
  
  const uploadXml = `<?xml version="1.0" encoding="UTF-8"?>
<request>
  <fileInsertRequest>
    <file>
      <fileName>${name}</fileName>
      <folderId>${folderId}</folderId>
      <overWrite>true</overWrite>
    </file>
  </fileInsertRequest>
</request>`;

  const uploadPayload = { "xml": uploadXml, "file": blob };
  let fileId = "";

  try {
    const res = UrlFetchApp.fetch(uploadUrl, {
      method: 'post',
      headers: headers,
      payload: uploadPayload,
      muteHttpExceptions: true
    });
    
    const text = res.getContentText();
    const code = res.getResponseCode();

    if (code === 200 && text.includes('<resultCode>0</resultCode>')) {
      const match = text.match(/<FileId>(\d+)<\/FileId>/);
      if (match) fileId = match[1];
      else return { success: false, message: "Upload OK but FileId not found" };
    } else {
      const errMatch = text.match(/<message>(.*?)<\/message>/) || text.match(/<faultstring>(.*?)<\/faultstring>/);
      return { success: false, message: errMatch ? errMatch[1] : text };
    }

  } catch (e) {
    return { success: false, message: "Upload Error: " + e.message };
  }

  Utilities.sleep(500);

  // Step 2. URLの取得
  const searchUrl = `https://api.rms.rakuten.co.jp/es/1.0/cabinet/files/search?fileId=${fileId}`;

  try {
    const res = UrlFetchApp.fetch(searchUrl, {
      method: 'get',
      headers: headers,
      muteHttpExceptions: true
    });

    const text = res.getContentText();
    const match = text.match(/<FileUrl>(.*?)<\/FileUrl>/);

    if (match) {
      let url = match[1];
      
      // ★修正箇所: /cabinet/ は消すが、先頭のスラッシュは残すため「+8」にする
      // 例: https://.../cabinet/123/img.jpg -> /123/img.jpg
      if (url.includes('/cabinet/')) {
        url = url.substring(url.indexOf('/cabinet/') + 8); 
      }
      
      return { success: true, imageUrl: url };
    } else {
      return { success: false, message: "Search OK but FileUrl not found" };
    }

  } catch (e) {
    return { success: false, message: "Search Error: " + e.message };
  }
}






