const RAKUTEN_SHOP_ID = "octas"; // 楽天店舗ID（必要に応じて設定シートから取得）

/** テスト用：反映確認・完了メールのログをシートに追記（後から確認できる） */
function logRakutenReflection(action, detail) {
  const detailStr = String(detail || '').substring(0, 500);
  try {
    const id = PropertiesService.getScriptProperties().getProperty('RAKUTEN_REFLECTION_LOG_SS_ID');
    let ss = null;
    if (id) {
      try { ss = SpreadsheetApp.openById(id); } catch (_) {}
    }
    if (!ss) ss = SpreadsheetApp.getActiveSpreadsheet();
    if (!ss) {
      console.warn('楽天反映ログ: スプレッドシートを特定できません。RAKUTEN_REFLECTION_LOG_SS_ID=' + (id || '未設定'));
      return;
    }
    let sheet = ss.getSheetByName(RAKUTEN_REFLECTION_LOG_SHEET);
    if (!sheet) {
      sheet = ss.insertSheet(RAKUTEN_REFLECTION_LOG_SHEET);
      sheet.getRange(1, 1, 1, 4).setValues([['日時', 'アクション', '詳細', '']]);
      sheet.getRange(1, 1, 1, 4).setFontWeight('bold').setBackground('#eee');
    }
    const now = Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyy-MM-dd HH:mm:ss');
    const nextRow = Math.max(sheet.getLastRow() + 1, 2);
    sheet.getRange(nextRow, 1, 1, 3).setValues([[now, String(action), detailStr]]);
  } catch (e) {
    console.warn('楽天反映ログ記録失敗: action=' + action + ', err=' + e.message);
  }
}

const REFLECTION_CHECK_INTERVAL_MIN = 5; // チェック間隔（分）
const REFLECTION_CHECK_MAX_DURATION_MIN = 30; // 最大チェック時間（分）

/**
 * 楽天商品ページの反映確認を開始する（5分おきにURLへアクセスして200なら反映済み。完了時にメール送信）
 * @param {Array<{code:string, name:string}>} products - 商品一覧（商品管理番号・商品名）
 * @param {string} shopId - 楽天店舗ID（商品URL・完了メール用）
 */
function startReflectionCheck(products, shopId) {
  if (!products || products.length === 0) {
    console.log("反映確認: 対象商品がありません");
    return;
  }
  
  const props = PropertiesService.getScriptProperties();
  const startTime = new Date().getTime();
  
  const checkData = {
    startTime: startTime,
    shopId: shopId || "",
    items: products.map(p => ({ url: p.code, name: p.name || "", reflected: false }))
  };
  props.setProperty('REFLECTION_CHECK_DATA', JSON.stringify(checkData));
  // トリガー実行時にログを書くため、スプレッドシートIDを保存
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    if (ss) props.setProperty('RAKUTEN_REFLECTION_LOG_SS_ID', ss.getId());
  } catch (_) {}

  console.log(`=== 反映確認を開始 ===`);
  console.log(`対象商品数: ${products.length}`);
  logRakutenReflection('反映確認開始', `商品数: ${products.length}、間隔: ${REFLECTION_CHECK_INTERVAL_MIN}分、最大: ${REFLECTION_CHECK_MAX_DURATION_MIN}分`);
  
  deleteReflectionCheckTriggers();
  try {
    ScriptApp.newTrigger('runReflectionCheck')
      .timeBased()
      .everyMinutes(REFLECTION_CHECK_INTERVAL_MIN)
      .create();
  } catch (e) {
    // 権限不足で自動作成できない場合。手動トリガーが1本あれば反映確認は動くため、シートには書かず console のみ
    console.warn('反映確認トリガー自動作成をスキップ: ' + e.message);
  }
  
  SpreadsheetApp.getActive().toast(
    `${products.length}件の反映確認を開始しました（${REFLECTION_CHECK_INTERVAL_MIN}分おき）。完了時にメール送信します。`,
    '楽天FTP'
  );
}

/**
 * 反映確認を実行（トリガーから呼び出される）
 */
function runReflectionCheck() {
  const props = PropertiesService.getScriptProperties();
  const checkDataStr = props.getProperty('REFLECTION_CHECK_DATA');
  
  if (!checkDataStr) {
    console.log("反映確認: データがありません。トリガーを削除します。");
    deleteReflectionCheckTriggers();
    return;
  }
  
  const checkData = JSON.parse(checkDataStr);
  const now = new Date().getTime();
  const elapsedMin = (now - checkData.startTime) / (1000 * 60);
  
  console.log(`=== 反映確認チェック (経過: ${Math.round(elapsedMin)}分) ===`);
  logRakutenReflection('チェック実行', `経過: ${Math.round(elapsedMin)}分`);
  
  // 最大時間を超えた場合は終了
  if (elapsedMin >= REFLECTION_CHECK_MAX_DURATION_MIN) {
    console.log("最大待機時間を超過。反映確認を終了します。");
    finishReflectionCheck(checkData, "timeout");
    return;
  }
  
  // 店舗IDを取得（設定シートから）
  let shopId = RAKUTEN_SHOP_ID;
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const settingSheet = ss.getSheetByName(SETTING_SHEET_NAME);
    if (settingSheet) {
      const settingRaw = settingSheet.getDataRange().getValues();
      if (settingRaw.length > 10 && settingRaw[10][1]) {
        shopId = String(settingRaw[10][1]).trim();
      }
    }
  } catch (e) {
    console.log("設定シートから店舗ID取得失敗、デフォルト使用: " + shopId);
  }
  
  let allReflected = true;
  let reflectedCount = 0;
  
  // 各商品をチェック
  checkData.items.forEach((item, index) => {
    if (item.reflected) {
      reflectedCount++;
      return; // 既に反映済み
    }
    
    const productUrl = `https://item.rakuten.co.jp/${shopId}/${item.url}/`;
    
    try {
      const response = UrlFetchApp.fetch(productUrl, {
        muteHttpExceptions: true,
        followRedirects: false
      });
      const statusCode = response.getResponseCode();
      
      if (statusCode === 200) {
        console.log(`✅ 反映確認: ${item.url} (HTTP ${statusCode})`);
        item.reflected = true;
        reflectedCount++;
        updateMasterSheetFtpStatus(item.url, "反映済");
        logRakutenReflection('URL確認OK', `${item.url} → 200`);
      } else {
        console.log(`⏳ 未反映: ${item.url} (HTTP ${statusCode})`);
        logRakutenReflection('URL未反映', `${item.url} → ${statusCode}`);
        allReflected = false;
      }
    } catch (e) {
      console.log(`❌ チェックエラー: ${item.url} - ${e.message}`);
      logRakutenReflection('URLチェックエラー', `${item.url} - ${e.message}`);
      allReflected = false;
    }
    
    // API制限対策: 少し待機
    Utilities.sleep(500);
  });
  
  console.log(`反映状況: ${reflectedCount}/${checkData.items.length} 件`);
  logRakutenReflection('反映状況', `${reflectedCount}/${checkData.items.length} 件`);
  
  // 全て反映済みなら終了
  if (allReflected) {
    console.log("全商品の反映を確認。反映確認を終了します。");
    finishReflectionCheck(checkData, "complete");
    return;
  }
  
  // データを更新して保存
  props.setProperty('REFLECTION_CHECK_DATA', JSON.stringify(checkData));
}

/**
 * マスタシートの楽天FTPステータスを更新
 * @param {string} itemUrl - 商品管理番号
 * @param {string} status - ステータス（送信済/反映済/Error）
 */
function updateMasterSheetFtpStatus(itemUrl, status) {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const masterSheet = ss.getSheetByName(MASTER_SHEET_NAME);
    if (!masterSheet) return;
    
    const data = masterSheet.getDataRange().getValues();
    const headers = data[0];
    
    // 楽天FTPステータス列を探す
    let ftpStatusCol = headers.indexOf('楽天FTP');
    if (ftpStatusCol === -1) {
      ftpStatusCol = headers.indexOf('楽天FTPステータス');
    }
    
    // 商品管理番号列を探す（複数の候補）
    let itemUrlCol = headers.indexOf('商品管理番号（商品URL）');
    if (itemUrlCol === -1) itemUrlCol = headers.indexOf('商品URL');
    if (itemUrlCol === -1) itemUrlCol = headers.indexOf('item_url');
    if (itemUrlCol === -1) itemUrlCol = headers.indexOf('親SKU');
    
    if (ftpStatusCol === -1 || itemUrlCol === -1) {
      console.log(`ステータス更新スキップ: 列が見つかりません (FTP列:${ftpStatusCol}, URL列:${itemUrlCol})`);
      return;
    }
    
    // 該当行を探して更新
    for (let i = 1; i < data.length; i++) {
      if (String(data[i][itemUrlCol]).trim() === String(itemUrl).trim()) {
        masterSheet.getRange(i + 1, ftpStatusCol + 1).setValue(status);
        console.log(`マスタ更新: 行${i + 1}, ${itemUrl} -> ${status}`);
        break;
      }
    }
  } catch (e) {
    console.error("マスタシート更新エラー: " + e.message);
  }
}

/**
 * 反映確認を終了する。トリガーを先に削除して実行を「完了」にし、メール送信後に即終了する。
 * @param {Object} checkData - チェックデータ
 * @param {string} reason - 終了理由（complete/timeout）
 */
function finishReflectionCheck(checkData, reason) {
  deleteReflectionCheckTriggers();

  const props = PropertiesService.getScriptProperties();
  props.deleteProperty('REFLECTION_CHECK_DATA');

  const reflectedCount = checkData.items.filter(i => i.reflected).length;
  const totalCount = checkData.items.length;

  let message = "";
  if (reason === "complete") {
    message = `✅ 全${totalCount}件の商品が楽天に反映されました`;
  } else {
    message = `⏱️ タイムアウト: ${reflectedCount}/${totalCount}件が反映済み`;
  }

  console.log(message);
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    if (ss) ss.toast(message, '楽天FTP反映確認', 8);
  } catch (_) {
    try {
      var id = props.getProperty('RAKUTEN_REFLECTION_LOG_SS_ID');
      if (id) SpreadsheetApp.openById(id).toast(message, '楽天FTP反映確認', 8);
    } catch (_) {}
  }
  logRakutenReflection(reason === 'complete' ? '反映確認完了' : '反映確認タイムアウト', `${reflectedCount}/${totalCount} 件`);

  if (reason === "timeout") {
    checkData.items.forEach(item => {
      if (!item.reflected) {
        updateMasterSheetFtpStatus(item.url, "未反映");
      }
    });
  }

  // 反映確認の結果を完了メールで送信（Yahoo同様の内容：一覧・商品ページURL・削除用URL・削除案内）
  sendRakutenCompletionEmailWithReflectionResult(checkData, reason);
}

/**
 * 反映確認用のトリガーを削除
 * トリガー実行時は script.scriptapp 権限がないため失敗する。その場合は try-catch で握りつぶし処理は継続する。
 */
function deleteReflectionCheckTriggers() {
  try {
    const triggers = ScriptApp.getProjectTriggers();
    triggers.forEach(trigger => {
      if (trigger.getHandlerFunction() === 'runReflectionCheck') {
        ScriptApp.deleteTrigger(trigger);
        console.log("反映確認トリガーを削除しました");
      }
    });
  } catch (e) {
    console.warn("反映確認トリガー削除をスキップ（権限不足。トリガー実行時は発生します）: " + e.message);
  }
}

/**
 * 反映確認を手動で停止する
 */
function stopReflectionCheck() {
  deleteReflectionCheckTriggers();
  const props = PropertiesService.getScriptProperties();
  props.deleteProperty('REFLECTION_CHECK_DATA');
  SpreadsheetApp.getActive().toast('反映確認を停止しました', '楽天FTP');
  console.log("反映確認を手動で停止しました");
}

/**
 * Google DriveのファイルをMAKE経由で楽天FTPにアップロードする
 * @param {string} fileId - Google DriveのファイルID
 * @param {string} fileName - アップロードするファイル名
 * @returns {boolean} - 成功時true、失敗時false
 */
function sendFileToRakutenFtpViaDrive(fileId, fileName) {
  const MAKE_WEBHOOK_URL = "https://hook.eu1.make.com/sbxvjnqvn7b23l673crdgkb7j1s4sl4w";
  
  const payload = {
    fileId: fileId,
    fileName: fileName,
    source: "googleDrive"  // MAKEにデータソースを伝える
  };
  
  const options = {
    method: "post",
    contentType: "application/json",
    payload: JSON.stringify(payload),
    muteHttpExceptions: true
  };
  
  console.log("=== 楽天FTPアップロード開始 (Google Drive経由) ===");
  console.log("ファイルID: " + fileId);
  console.log("ファイル名: " + fileName);
  
  try {
    const response = UrlFetchApp.fetch(MAKE_WEBHOOK_URL, options);
    const responseCode = response.getResponseCode();
    
    if (responseCode === 200) {
      console.log("✅ MAKEへの送信成功 - 楽天FTPにアップロードされます");
      SpreadsheetApp.getActive().toast('楽天FTPへアップロード中...', 'MAKE連携');
      return true;
    } else {
      console.error("⚠️ MAKEへの送信失敗 - ステータスコード: " + responseCode);
      console.error("レスポンス: " + response.getContentText());
      return false;
    }
  } catch (e) {
    console.error("❌ FTPアップロードエラー: " + e.message);
    return false;
  }
}

/**
 * CSVデータをMAKE経由で楽天FTPにアップロードする（旧方式・Base64）
 * @param {string} csvData - CSV形式の文字列データまたはBase64エンコード済みデータ
 * @param {string} fileName - アップロードするファイル名
 * @param {boolean} enableReflectionCheck - 反映確認を有効にするか（デフォルト: true）
 * @param {boolean} isBase64 - データがBase64エンコード済みか（デフォルト: false）
 * @returns {boolean} - 成功時true、失敗時false
 */
function sendCsvToRakutenFtp(csvData, fileName, enableReflectionCheck = true, isBase64 = false) {
  const MAKE_WEBHOOK_URL = "https://hook.eu1.make.com/sbxvjnqvn7b23l673crdgkb7j1s4sl4w";
  
  const payload = {
    csvData: csvData,
    fileName: fileName,
    isBase64: isBase64  // MAKEにBase64かどうかを伝える
  };
  
  const options = {
    method: "post",
    contentType: "application/json",
    payload: JSON.stringify(payload),
    muteHttpExceptions: true
  };
  
  console.log("=== 楽天FTPアップロード開始 ===");
  console.log("ファイル名: " + fileName);
  console.log("データサイズ: " + csvData.length + " 文字");
  console.log("エンコーディング: " + (isBase64 ? "Shift-JIS (Base64)" : "UTF-8"));
  
  try {
    const response = UrlFetchApp.fetch(MAKE_WEBHOOK_URL, options);
    const responseCode = response.getResponseCode();
    
    if (responseCode === 200) {
      console.log("✅ MAKEへの送信成功 - 楽天FTPにアップロードされます");
      SpreadsheetApp.getActive().toast('楽天FTPへアップロード中...', 'MAKE連携');
      
      // 反映確認を開始（Base64の場合はデコードしてからURL抽出）
      if (enableReflectionCheck) {
        let csvForParsing = csvData;
        if (isBase64) {
          // Base64デコードしてShift-JISからUTF-8に変換
          try {
            const decoded = Utilities.newBlob(Utilities.base64Decode(csvData)).getDataAsString('Shift_JIS');
            csvForParsing = decoded;
          } catch (e) {
            console.log("Base64デコード失敗、反映確認をスキップ: " + e.message);
            csvForParsing = null;
          }
        }
        
        if (csvForParsing) {
          const itemUrls = extractItemUrlsFromCsv(csvForParsing);
          if (itemUrls.length > 0) {
            const products = itemUrls.map(url => ({ code: url, name: "" }));
            let shopId = "";
            try {
              const ss = SpreadsheetApp.getActiveSpreadsheet();
              const settingSheet = ss.getSheetByName(SETTING_SHEET_NAME);
              if (settingSheet) {
                const raw = settingSheet.getDataRange().getValues();
                if (raw.length > 10 && raw[10][1]) shopId = String(raw[10][1]).trim();
              }
            } catch (e) {}
            startReflectionCheck(products, shopId);
          }
        }
      }
      
      return true;
    } else {
      console.error("⚠️ MAKEへの送信失敗 - ステータスコード: " + responseCode);
      console.error("レスポンス: " + response.getContentText());
      return false;
    }
  } catch (e) {
    console.error("❌ FTPアップロードエラー: " + e.message);
    return false;
  }
}

/**
 * CSVデータから商品管理番号（item_url）を抽出する
 * @param {string} csvData - CSV形式の文字列
 * @returns {string[]} - 商品管理番号の配列（重複なし）
 */
function extractItemUrlsFromCsv(csvData) {
  const lines = csvData.split(/\r\n|\n/);
  if (lines.length < 2) return [];
  
  // ヘッダー行から item_url（商品管理番号）の列インデックスを探す
  const headers = parseCSVLine(lines[0]);
  let itemUrlColIdx = headers.findIndex(h => 
    h === '商品管理番号（商品URL）' || 
    h === 'item_url' || 
    h === '商品URL' ||
    h === '商品管理番号'
  );
  
  if (itemUrlColIdx === -1) {
    console.log("商品管理番号列が見つかりません");
    return [];
  }
  
  // データ行から商品管理番号を抽出（重複除去）
  const itemUrls = new Set();
  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const row = parseCSVLine(lines[i]);
    const itemUrl = row[itemUrlColIdx];
    if (itemUrl && itemUrl.trim()) {
      itemUrls.add(itemUrl.trim());
    }
  }
  
  const result = Array.from(itemUrls);
  console.log(`抽出した商品管理番号: ${result.length}件`);
  return result;
}

/**
 * CSV行をパースする（カンマ区切り、ダブルクォート対応）
 * @param {string} line - CSV行
 * @returns {string[]} - フィールドの配列
 */
function parseCSVLine(line) {
  const result = [];
  let current = '';
  let inQuotes = false;
  
  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    
    if (inQuotes) {
      if (char === '"') {
        if (line[i + 1] === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        current += char;
      }
    } else {
      if (char === '"') {
        inQuotes = true;
      } else if (char === ',') {
        result.push(current);
        current = '';
      } else {
        current += char;
      }
    }
  }
  result.push(current);
  
  return result;
}

// =============================================================================
// 再③ 価格調整（v1）— docs/PRICING_V1_REQUIREMENTS.md ／ PROP_PRICING_ROUND3_ENABLED
// =============================================================================

function menuRunRound3PriceAdjustIntegrated_() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  runRound3PriceAdjustAllMalls_(ss, { integrated: true });
}

function menuRunRound3PriceAdjust() {
  var ui = SpreadsheetApp.getUi();
  if (!ui) return;
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var r = runRound3PriceAdjustAllMalls_(ss, { integrated: false });
  ui.alert('再③ 価格調整を完了しました。更新セル数（目安）: ' + (r && r.updated != null ? r.updated : 0));
}

/**
 * 税込価格の下限（利益額 minProfit 円以上）を返す。成立しないとき null。
 */
function round3MinPriceForProfit_(ctx, minProfit) {
  var f = (Number(ctx.feePct) || 0) + (Number(ctx.promoPct) || 0);
  var denom = 1 - f / 100;
  if (denom <= 0.01) return null;
  var C = (Number(ctx.cost) || 0) + (Number(ctx.shipping) || 0) + (Number(ctx.boxCost) || 0);
  return Math.ceil((C + Number(minProfit)) / denom);
}

/**
 * 再③: 当該モールで競合価格が1件もないJAN。利益200円未満の子行を税込売価の下限まで引き上げる。
 * 単価・総額の単調補正は行わない（送料・原価の前提が崩れ単価逆転が残る場合は許容し、送料を人手確認する想定）。
 * @param {GoogleAppsScript.Spreadsheet.Sheet} masterSheet
 * @param {Array<Object>} rows runRound3PriceAdjustForJanMall_ 内の rows（price を更新）
 * @param {Array<number>} profits
 * @param {number} colPrice
 * @param {string} mallKey
 * @param {string} jan
 * @return {number} 更新セル数
 */
function runRound3PriceAdjustNoCompAll_(masterSheet, rows, profits, colPrice, mallKey, jan) {
  var updated = 0;
  var i;
  for (i = 0; i < rows.length; i++) {
    if (profits[i] >= 200) continue;
    var ctx = {
      cost: rows[i].cost,
      shipping: rows[i].shipping,
      boxCost: rows[i].boxCost,
      feePct: rows[i].feePct,
      promoPct: rows[i].promoPct
    };
    var minP = round3MinPriceForProfit_(ctx, 200);
    if (minP === null) continue;
    var cur = isNaN(rows[i].price) ? 0 : rows[i].price;
    if (minP > cur) {
      masterSheet.getRange(rows[i].rowIdx + 1, colPrice + 1).setValue(minP);
      rows[i].price = minP;
      profits[i] = computeMallProfitAmount_(minP, rows[i].cost, rows[i].shipping, rows[i].boxCost, rows[i].feePct, rows[i].promoPct);
      updated++;
      logPricingV1_('round3', 'no_comp_raise', { mall: mallKey, jan: jan, row: rows[i].rowIdx + 1, set: rows[i].setNum, newP: minP });
    }
  }
  return updated;
}

function getAmazonFeePctForRound3_(masterColMap, childRow, parentRow, parseNum) {
  var keys = ['amazon手数料率', '手数料率'];
  for (var i = 0; i < keys.length; i++) {
    var c = masterColMap[keys[i]];
    if (c !== undefined && childRow[c] !== undefined && childRow[c] !== '') {
      var n = parseNum(childRow[c]);
      if (!isNaN(n) && n >= 0) return n;
    }
  }
  for (var j = 0; j < keys.length; j++) {
    var c2 = masterColMap[keys[j]];
    if (c2 !== undefined && parentRow[c2] !== undefined && parentRow[c2] !== '') {
      var n2 = parseNum(parentRow[c2]);
      if (!isNaN(n2) && n2 >= 0) return n2;
    }
  }
  return 0;
}

/**
 * @param {string} jan
 * @return {number} 更新セル数
 */
function runRound3PriceAdjustForJanMall_(masterSheet, masterValues, headerRowIdx, masterColMap, group, mallKey, colPrice, colComp, jan, parseNum) {
  var parentRow = masterValues[group.parentRowIdx] || [];
  var promoCol = masterColMap['販促費率'];
  var promoRateNum = 3;
  if (promoCol !== undefined && parentRow[promoCol] !== undefined && parentRow[promoCol] !== '') {
    var pr = parseNum(parentRow[promoCol]);
    if (!isNaN(pr)) promoRateNum = pr;
  }

  var children = group.children.slice().sort(function (a, b) { return a.setNum - b.setNum; });
  var rows = [];
  for (var i = 0; i < children.length; i++) {
    var ch = children[i];
    var row = masterValues[ch.rowIdx] || [];
    var price = parseNum(row[colPrice]);
    var comp = parseNum(row[colComp]);
    var feePct = 0;
    if (mallKey === 'amazon') {
      feePct = getAmazonFeePctForRound3_(masterColMap, row, parentRow, parseNum);
    } else {
      feePct = getMallFeePctForChildRow_(masterColMap, row, parentRow, mallKey === 'rakuten' ? 'rakuten' : 'yahoo');
    }
    rows.push({
      rowIdx: ch.rowIdx,
      setNum: ch.setNum,
      cost: ch.cost,
      shipping: ch.shipping,
      boxCost: ch.boxCost,
      price: price,
      comp: comp,
      feePct: feePct,
      promoPct: promoRateNum
    });
  }

  var profits = [];
  for (var j = 0; j < rows.length; j++) {
    var rr = rows[j];
    var p0 = isNaN(rr.price) ? 0 : rr.price;
    profits.push(computeMallProfitAmount_(p0, rr.cost, rr.shipping, rr.boxCost, rr.feePct, rr.promoPct));
  }

  var minCompSet = null;
  var hasAnyComp = false;
  for (var k = 0; k < rows.length; k++) {
    if (!isNaN(rows[k].comp) && rows[k].comp > 0) {
      hasAnyComp = true;
      if (minCompSet === null || rows[k].setNum < minCompSet) minCompSet = rows[k].setNum;
    }
  }
  if (!hasAnyComp || minCompSet === null) {
    return runRound3PriceAdjustNoCompAll_(masterSheet, rows, profits, colPrice, mallKey, jan);
  }

  var onlyCompBad = true;
  var hasNonComp = false;
  for (var k2 = 0; k2 < rows.length; k2++) {
    var hasC = !isNaN(rows[k2].comp) && rows[k2].comp > 0;
    if (!hasC) hasNonComp = true;
    if (hasC && profits[k2] >= 200) onlyCompBad = false;
    if (!hasC && profits[k2] < 200) onlyCompBad = false;
  }
  if (onlyCompBad && hasNonComp && hasAnyComp) {
    logPricingV1_('round3', 'skip_only_comp_bad', { mall: mallKey, jan: jan });
    return 0;
  }

  var downstreamLow = false;
  for (var k3 = 0; k3 < rows.length; k3++) {
    if (rows[k3].setNum > minCompSet && profits[k3] < 200) downstreamLow = true;
  }
  if (!downstreamLow) {
    return 0;
  }

  var updated = 0;
  for (var k4 = 0; k4 < rows.length; k4++) {
    if (rows[k4].setNum <= minCompSet) continue;
    if (profits[k4] >= 200) continue;
    var ctx = {
      cost: rows[k4].cost,
      shipping: rows[k4].shipping,
      boxCost: rows[k4].boxCost,
      feePct: rows[k4].feePct,
      promoPct: rows[k4].promoPct
    };
    var minP = round3MinPriceForProfit_(ctx, 200);
    if (minP === null) continue;
    var compv = rows[k4].comp;
    var newP = minP;
    if (!isNaN(compv) && compv > 0) {
      var cap = Math.floor(compv * 1.1);
      newP = Math.min(newP, cap);
    }
    var cur = isNaN(rows[k4].price) ? 0 : rows[k4].price;
    if (newP > cur) {
      masterSheet.getRange(rows[k4].rowIdx + 1, colPrice + 1).setValue(newP);
      rows[k4].price = newP;
      profits[k4] = computeMallProfitAmount_(newP, rows[k4].cost, rows[k4].shipping, rows[k4].boxCost, rows[k4].feePct, rows[k4].promoPct);
      updated++;
      logPricingV1_('round3', 'raise', { mall: mallKey, jan: jan, row: rows[k4].rowIdx + 1, set: rows[k4].setNum, newP: newP });
    }
  }

  var priceList = [];
  for (var p = 0; p < rows.length; p++) {
    priceList.push({ rowIdx: rows[p].rowIdx, setNum: rows[p].setNum, price: rows[p].price, colPrice: colPrice });
  }
  priceList.sort(function (a, b) { return a.setNum - b.setNum; });
  for (var pl = 1; pl < priceList.length; pl++) {
    var prev = priceList[pl - 1];
    var curr = priceList[pl];
    var pu = prev.price / prev.setNum;
    var cu = curr.price / curr.setNum;
    if (cu > pu) {
      var fixed = Math.max(1, Math.floor(pu * curr.setNum));
      if (fixed !== curr.price) {
        masterSheet.getRange(curr.rowIdx + 1, colPrice + 1).setValue(fixed);
        updated++;
        logPricingV1_('round3', 'mono_unit', { mall: mallKey, jan: jan, row: curr.rowIdx + 1, fixed: fixed });
        curr.price = fixed;
      }
    }
    if (curr.price < prev.price) {
      masterSheet.getRange(curr.rowIdx + 1, colPrice + 1).setValue(prev.price);
      updated++;
      logPricingV1_('round3', 'mono_total', { mall: mallKey, jan: jan, row: curr.rowIdx + 1, fixed: prev.price });
      curr.price = prev.price;
    }
  }

  return updated;
}

/**
 * 再③：同一JAN・レ点行について Amazon→楽天→Yahoo の順で価格を調整。
 * @param {{ integrated?: boolean }} opts
 * @return {{ updated: number, skipped?: boolean, error?: string }}
 */
function runRound3PriceAdjustAllMalls_(ss, opts) {
  opts = opts || {};
  if (!getBoolScriptProperty_(PROP_PRICING_ROUND3_ENABLED, true)) {
    logPricingV1_('round3', 'skipped', { reason: 'PRICING_ROUND3_ENABLED=false' });
    return { updated: 0, skipped: true };
  }
  var masterSheet = ss.getSheetByName(MASTER_SHEET_NAME);
  if (!masterSheet) {
    logPricingV1_('round3', 'error', { reason: 'no_master' });
    return { updated: 0, error: 'no_master' };
  }
  var masterValues = masterSheet.getDataRange().getValues();
  var headerRowIdx = -1;
  for (var hr = 0; hr < Math.min(masterValues.length, 25); hr++) {
    if ((masterValues[hr] || []).indexOf(ANCHOR_HEADER_NAME) !== -1) { headerRowIdx = hr; break; }
  }
  if (headerRowIdx === -1) return { updated: 0, error: 'no_header' };
  var masterColMap = getColumnIndexMap(masterValues[headerRowIdx]);
  var colCheckbox = masterColMap[CHECKBOX_HEADER_NAME];
  var colJan = masterColMap['JANコード'];
  var colSetQty = masterColMap[COL_MASTER_TOTAL_QTY];
  var colChildSku = masterColMap['子SKU'];
  var colCost = masterColMap[COL_COST_SET_TAX_IN] !== undefined ? masterColMap[COL_COST_SET_TAX_IN] : masterColMap[COL_COST_TAX_IN];
  var colShipping = masterColMap[COL_SHIPPING_FIXED] !== undefined ? masterColMap[COL_SHIPPING_FIXED] : masterColMap[COL_SHIPPING];
  var colBoxCost = masterColMap['梱包箱コスト'];
  if (!colCheckbox || colJan === undefined || colSetQty === undefined || colChildSku === undefined || colCost === undefined || colShipping === undefined) {
    return { updated: 0, error: 'columns' };
  }

  var parseNum = function (v) {
    if (v === undefined || v === null || v === '') return NaN;
    var n = Number(String(v).replace(/,/g, ''));
    return isNaN(n) ? NaN : n;
  };

  var janToGroup = {};
  var bScopeR3 = getBRunScope_(ss);
  for (var r = headerRowIdx + 1; r < masterValues.length; r++) {
    var row = masterValues[r];
    if (!bRunAllowMasterRow_(r, row[colCheckbox], bScopeR3)) continue;
    var jan = String(row[colJan] || '').trim();
    if (jan === '') continue;
    var isParent = (row[colChildSku] === undefined || row[colChildSku] === null || String(row[colChildSku]).trim() === '');
    var cost = parseNum(row[colCost]);
    if (isNaN(cost) || cost < 0) cost = 0;
    var setVal = String(row[colSetQty] || '').trim();
    var setNum = (setVal !== '') ? parseInt(setVal, 10) : 1;
    if (isNaN(setNum) || setNum < 1) setNum = 1;
    var shipNum = parseNum(row[colShipping]);
    if (isNaN(shipNum)) shipNum = 0;
    var boxVal = (colBoxCost !== undefined && row[colBoxCost] !== undefined && row[colBoxCost] !== '') ? parseNum(row[colBoxCost]) : 0;
    if (isNaN(boxVal)) boxVal = 0;
    if (isParent) {
      if (!janToGroup[jan]) janToGroup[jan] = { parentRowIdx: r, children: [] };
      else if (janToGroup[jan].parentRowIdx === undefined) janToGroup[jan].parentRowIdx = r;
    } else {
      if (!janToGroup[jan]) janToGroup[jan] = { parentRowIdx: undefined, children: [] };
      janToGroup[jan].children.push({
        rowIdx: r,
        setNum: setNum,
        cost: cost,
        shipping: shipNum,
        boxCost: boxVal
      });
    }
  }

  var malls = [
    { key: 'amazon', colPrice: COL_PRICE_AMAZON, colComp: COL_COMPETITIVE_PRICE_AMAZON },
    { key: 'rakuten', colPrice: COL_PRICE_RAKUTEN, colComp: COL_COMPETITIVE_PRICE_RAKUTEN },
    { key: 'yahoo', colPrice: COL_PRICE_YAHOO, colComp: COL_COMPETITIVE_PRICE_YAHOO }
  ];

  var totalUpdated = 0;
  for (var mi = 0; mi < malls.length; mi++) {
    var mall = malls[mi];
    var colPrice = masterColMap[mall.colPrice];
    var colComp = masterColMap[mall.colComp];
    if (colPrice === undefined || colComp === undefined) continue;
    for (var jk in janToGroup) {
      var grp = janToGroup[jk];
      if (grp.parentRowIdx === undefined || !grp.children || grp.children.length === 0) continue;
      var n = runRound3PriceAdjustForJanMall_(masterSheet, masterValues, headerRowIdx, masterColMap, grp, mall.key, colPrice, colComp, jk, parseNum);
      totalUpdated += n;
    }
    masterValues = masterSheet.getDataRange().getValues();
  }

  logPricingV1_('round3', 'done', { updated: totalUpdated });
  if (!opts.integrated) {
    try {
      SpreadsheetApp.getActiveSpreadsheet().toast('再③ 完了（更新セル目安 ' + totalUpdated + '）', '2.6 再③', 6);
    } catch (te) {}
  }
  return { updated: totalUpdated, skipped: false };
}

// =============================================================================
// 楽天ジャンルID NavigationAPI 疎通診断（書込なし・CSV非改変）
// Script Property: RAKUTEN_NAV_GENRE_DIAG_ENABLED（既定 true。false でメニュー実行を拒否）
// docs/RAKUTEN_NAV_GENRE_DIAG.md
// =============================================================================

/** @const {string} */
var RAKUTEN_NAV_GENRE_DIAG_PROP = 'RAKUTEN_NAV_GENRE_DIAG_ENABLED';

/** 疎通用固定ジャンルID（マスタへは書かない） */
var RAKUTEN_NAV_GENRE_DIAG_TEST_IDS = [
  { genreId: '101888', expectHint: 'ダイエット・健康 > 健康グッズ > その他' },
  { genreId: '101535', expectHint: '食品 > 魚介類・水産加工品 > セット・詰め合わせ' }
];

/**
 * メニュー: 既知ジャンルIDで Navigation genres.get 相当を呼び、Logger のみに結果を出す。
 * 商品マスタ・AI情報取得data・出品CSVへの書き込みは行わない。
 */
function menuDiagnoseRakutenNavigationGenreGet() {
  if (!getBoolScriptProperty_(RAKUTEN_NAV_GENRE_DIAG_PROP, true)) {
    var msgOff = '診断は無効です。Script Properties の ' + RAKUTEN_NAV_GENRE_DIAG_PROP + ' を true にしてください。';
    Logger.log('[RakutenNavGenreDiag] ' + msgOff);
    try { SpreadsheetApp.getUi().alert(msgOff); } catch (e0) {}
    return;
  }
  var secret = (getRakutenServiceSecret() || '').trim();
  var license = (getRakutenLicenseKey() || '').trim();
  if (!secret || !license) {
    var msgAuth = 'RAKUTEN_SERVICE_SECRET / RAKUTEN_LICENSE_KEY が未設定です（値はログに出しません）。';
    Logger.log('[RakutenNavGenreDiag] FAIL authMissing=true');
    try { SpreadsheetApp.getUi().alert(msgAuth); } catch (e1) {}
    return;
  }

  Logger.log('[RakutenNavGenreDiag] start runId=navGenreDiag_' + Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyyMMdd_HHmmss') +
    ' state=RUNNING testCount=' + RAKUTEN_NAV_GENRE_DIAG_TEST_IDS.length);

  var okCount = 0;
  var lines = [];
  for (var i = 0; i < RAKUTEN_NAV_GENRE_DIAG_TEST_IDS.length; i++) {
    var t = RAKUTEN_NAV_GENRE_DIAG_TEST_IDS[i];
    var result = diagnoseRakutenNavigationGenreGetOne_(t.genreId, t.expectHint);
    if (result && result.ok) okCount++;
    lines.push(result && result.summaryLine ? result.summaryLine : ('genreId=' + t.genreId + ' unknown'));
  }

  Logger.log('[RakutenNavGenreDiag] done state=DONE okCount=' + okCount + '/' + RAKUTEN_NAV_GENRE_DIAG_TEST_IDS.length);
  for (var j = 0; j < lines.length; j++) {
    Logger.log('[RakutenNavGenreDiag] result[' + j + '] ' + lines[j]);
  }

  try {
    SpreadsheetApp.getUi().alert(
      '楽天ジャンル NavigationAPI 疎通',
      '完了: 成功 ' + okCount + '/' + RAKUTEN_NAV_GENRE_DIAG_TEST_IDS.length +
        '\n詳細は「実行数」→該当関数のログを確認してください。\n' +
        '（マスタ等への書き込みはしていません）',
      SpreadsheetApp.getUi().ButtonSet.OK
    );
  } catch (e2) {}
}

/**
 * 1ジャンルID分の疎通（最大2エンドポイント試行）。シークレットはログに出さない。
 * @param {string} genreId
 * @param {string} expectHint
 * @return {{ok:boolean, summaryLine:string, genreId:string, httpStatus:(number|string), endpointKey:string, nameJa:string, nameJaPath:string, expectedHint:string, nameOk:boolean, errorSummary:string}}
 */
function diagnoseRakutenNavigationGenreGetOne_(genreId, expectHint) {
  var id = String(genreId || '').trim();
  var hint = String(expectHint || '');
  // NavigationAPI 2.0 genres.get の実パスは path パラメータ型（コミュニティ実装・公式命名 genres.get 相当）
  // 誤: /es/2.0/navigation/genres?genreId= → GF0002 Not Found
  // 正: /es/2.0/navigation/genres/{genreId}
  var endpoints = [
    {
      label: 'nav2_genres_byId_showAncestors',
      url: 'https://api.rms.rakuten.co.jp/es/2.0/navigation/genres/' + encodeURIComponent(id) +
        '?showAncestors=true'
    },
    {
      label: 'nav2_genres_byId',
      url: 'https://api.rms.rakuten.co.jp/es/2.0/navigation/genres/' + encodeURIComponent(id)
    }
  ];

  var authKey = Utilities.base64Encode(getRakutenServiceSecret() + ':' + getRakutenLicenseKey());
  var headers = { Authorization: 'ESA ' + authKey, Accept: 'application/json, application/xml, text/xml, */*' };
  var lastErr = '';
  var lastHttp = '';
  var lastEndpoint = '';

  for (var ei = 0; ei < endpoints.length; ei++) {
    var ep = endpoints[ei];
    try {
      Logger.log('[RakutenNavGenreDiag] fetch genreId=' + id + ' endpoint=' + ep.label + ' state=RUNNING');
      var res = UrlFetchApp.fetch(ep.url, {
        method: 'get',
        headers: headers,
        muteHttpExceptions: true,
        followRedirects: true
      });
      var code = res.getResponseCode();
      var body = res.getContentText() || '';
      var parsed = parseRakutenNavigationGenreResponse_(body);
      var namePath = parsed.namePath || parsed.genreName || '';
      var nameJa = String(parsed.genreName || '').trim();
      var bodyLen = body.length;
      var errSnippet = '';
      lastHttp = code;
      lastEndpoint = ep.label;
      if (code < 200 || code >= 300) {
        errSnippet = String(body).replace(/\s+/g, ' ').substring(0, 160);
        lastErr = 'http=' + code + ' endpoint=' + ep.label + ' bodySnippet=' + errSnippet;
        Logger.log('[RakutenNavGenreDiag] genreId=' + id + ' endpoint=' + ep.label +
          ' http=' + code + ' bodyLen=' + bodyLen + ' state=FAILED err=' + errSnippet);
        continue;
      }
      // ok=名称取得できたか。nameOk=期待ヒント一致（ヒント空なら名称非空で true）
      var pathNorm = String(namePath || '').replace(/\s+/g, '');
      var hintNorm = hint.replace(/\s+/g, '');
      var hasName = !!pathNorm;
      var nameOk = hasName && (!hintNorm || pathNorm === hintNorm);
      var ok = (code >= 200 && code < 300) && hasName;
      var summary = 'genreId=' + id +
        ' http=' + code +
        ' endpoint=' + ep.label +
        ' namePath=' + (namePath || '(empty)') +
        ' genreName=' + (nameJa || '(empty)') +
        ' nameOk=' + nameOk +
        ' expectHint=' + hint +
        ' bodyLen=' + bodyLen +
        ' ok=' + ok;
      Logger.log('[RakutenNavGenreDiag] ' + summary + ' state=' + (ok ? 'DONE' : 'FAILED'));
      return {
        ok: ok,
        summaryLine: summary,
        genreId: id,
        httpStatus: code,
        endpointKey: ep.label,
        nameJa: nameJa,
        nameJaPath: namePath || '',
        expectedHint: hint,
        nameOk: nameOk,
        errorSummary: ok ? '' : 'namePathEmpty'
      };
    } catch (e) {
      lastErr = 'exception endpoint=' + ep.label + ' msg=' + ((e && e.message) || e);
      lastEndpoint = ep.label;
      Logger.log('[RakutenNavGenreDiag] genreId=' + id + ' ' + lastErr + ' state=FAILED');
    }
  }

  var failLine = 'genreId=' + id + ' ok=false lastErr=' + lastErr;
  Logger.log('[RakutenNavGenreDiag] ' + failLine + ' state=FAILED');
  return {
    ok: false,
    summaryLine: failLine,
    genreId: id,
    httpStatus: lastHttp,
    endpointKey: lastEndpoint,
    nameJa: '',
    nameJaPath: '',
    expectedHint: hint,
    nameOk: false,
    errorSummary: String(lastErr || 'unknown').substring(0, 200)
  };
}

/**
 * NavigationAPI 2.0 応答からジャンル名を拾う。秘匿値は扱わない。
 * 2.0 の名称フィールドは nameJa / nameJaPath（genreName ではない）。
 * @param {string} body
 * @return {{genreId:string, genreName:string, namePath:string}}
 */
function parseRakutenNavigationGenreResponse_(body) {
  var out = { genreId: '', genreName: '', namePath: '' };
  var text = String(body || '');
  if (!text) return out;

  var joinNameList_ = function (list) {
    if (!list || Object.prototype.toString.call(list) !== '[object Array]') return '';
    var parts = [];
    for (var i = 0; i < list.length; i++) {
      var item = list[i];
      if (item === null || item === undefined) continue;
      if (typeof item === 'string' || typeof item === 'number') {
        var s0 = String(item).trim();
        if (s0) parts.push(s0);
      } else if (typeof item === 'object') {
        var sn = String(item.nameJa || item.genreName || item.name || '').trim();
        if (sn) parts.push(sn);
      }
    }
    return parts.join(' > ');
  };

  var pickGenreNode_ = function (obj) {
    if (!obj || typeof obj !== 'object') return null;
    if (obj.genre && typeof obj.genre === 'object') return obj.genre;
    if (obj.Genre && typeof obj.Genre === 'object') return obj.Genre;
    if (obj.navigationGenreResult && obj.navigationGenreResult.genre) {
      return obj.navigationGenreResult.genre;
    }
    if (obj.nameJa || obj.genreName || obj.genreId != null) return obj;
    return null;
  };

  var trimmed = text.replace(/^\uFEFF/, '').trim();
  if (trimmed.charAt(0) === '{' || trimmed.charAt(0) === '[') {
    try {
      var json = JSON.parse(trimmed);
      var node = pickGenreNode_(json);
      if (node) {
        out.genreId = String(
          node.genreId != null ? node.genreId : (node.genreID != null ? node.genreID : (node.id != null ? node.id : ''))
        );
        out.genreName = String(node.nameJa || node.genreName || node.name || '').trim();
        // 公式2.0: nameJaPath がパンくず（文字列配列）
        out.namePath = joinNameList_(node.nameJaPath);
        if (!out.namePath && node.ancestors) {
          out.namePath = joinNameList_(node.ancestors);
          if (out.genreName) {
            out.namePath = out.namePath ? (out.namePath + ' > ' + out.genreName) : out.genreName;
          }
        }
        if (!out.namePath && out.genreName) out.namePath = out.genreName;
      }
      if (!out.namePath && typeof json === 'object') {
        var blob = JSON.stringify(json);
        var mPath = blob.match(/"nameJaPath"\s*:\s*\[([^\]]*)\]/);
        if (mPath) {
          var inner = mPath[1];
          var names = [];
          var reStr = /"((?:\\.|[^"\\])*)"/g;
          var mm;
          while ((mm = reStr.exec(inner)) !== null) {
            names.push(mm[1]);
          }
          if (names.length) out.namePath = names.join(' > ');
        }
        if (!out.genreName) {
          var mName = blob.match(/"nameJa"\s*:\s*"((?:\\.|[^"\\])*)"/);
          if (mName) out.genreName = mName[1];
        }
        if (!out.namePath && out.genreName) out.namePath = out.genreName;
      }
      return out;
    } catch (eJson) {
      // fall through to XML/regex
    }
  }

  var xmId = text.match(/<genreId>\s*([^<]+)\s*<\/genreId>/i);
  var xmName = text.match(/<nameJa>\s*([^<]+)\s*<\/nameJa>/i) ||
    text.match(/<genreName>\s*([^<]+)\s*<\/genreName>/i);
  if (xmId) out.genreId = String(xmId[1]).trim();
  if (xmName) out.genreName = String(xmName[1]).trim();
  if (out.genreName) out.namePath = out.genreName;
  return out;
}

// =============================================================================
// 楽天ジャンル Nav Stage1（テストシート追記のみ・マスタ/CSV非書込）
// Script Property: RAKUTEN_NAV_GENRE_STAGE1_WRITE_ENABLED（既定 false）
// docs/RAKUTEN_NAV_GENRE_STAGE1.md
// =============================================================================

/** @const {string} */
var RAKUTEN_NAV_GENRE_STAGE1_WRITE_PROP = 'RAKUTEN_NAV_GENRE_STAGE1_WRITE_ENABLED';
/** @const {string} 書込先シート名（この名前以外には書かない） */
var RAKUTEN_NAV_GENRE_STAGE1_SHEET_NAME = '▼診断(楽天ジャンルNav)';
/** @const {string} */
var RAKUTEN_NAV_GENRE_STAGE1_SCRIPT_VERSION = 'stage1-20260717';
/** @const {string[]} ヘッダー（完全一致） */
var RAKUTEN_NAV_GENRE_STAGE1_HEADERS = [
  'runId', 'ranAt', 'genreId', 'httpStatus', 'endpointKey',
  'nameJa', 'nameJaPath', 'expectedHint', 'nameOk', 'ok', 'errorSummary', 'scriptVersion'
];

/**
 * メニュー: NavigationAPI 結果を専用テストシートへ追記する（商品マスタ等へは書かない）。
 */
function menuDiagnoseRakutenNavigationGenreStage1Write() {
  var stepName = 'RakutenNavGenreStage1';
  var functionName = 'menuDiagnoseRakutenNavigationGenreStage1Write';
  if (!getBoolScriptProperty_(RAKUTEN_NAV_GENRE_STAGE1_WRITE_PROP, false)) {
    var msgOff = 'Stage1書込は無効です。Script Properties の ' + RAKUTEN_NAV_GENRE_STAGE1_WRITE_PROP +
      ' を true にしてください（既定は無効）。';
    Logger.log('[' + stepName + '] runId=- stepName=' + stepName + ' functionName=' + functionName +
      ' state=FAILED ' + msgOff);
    try { SpreadsheetApp.getUi().alert(msgOff); } catch (e0) {}
    return;
  }
  var secret = (getRakutenServiceSecret() || '').trim();
  var license = (getRakutenLicenseKey() || '').trim();
  if (!secret || !license) {
    Logger.log('[' + stepName + '] state=FAILED authMissing=true');
    try {
      SpreadsheetApp.getUi().alert('RAKUTEN_SERVICE_SECRET / RAKUTEN_LICENSE_KEY が未設定です（値はログに出しません）。');
    } catch (e1) {}
    return;
  }

  var runId = 'navS1_' + Utilities.formatDate(new Date(), 'Asia/Tokyo', 'yyyyMMdd_HHmmss') +
    '_' + String(Utilities.getUuid()).replace(/-/g, '').substring(0, 8);
  var ranAt = Utilities.formatDate(new Date(), 'Asia/Tokyo', "yyyy-MM-dd'T'HH:mm:ssXXX");
  Logger.log('[' + stepName + '] runId=' + runId + ' stepName=' + stepName +
    ' functionName=' + functionName + ' state=RUNNING testCount=' + RAKUTEN_NAV_GENRE_DIAG_TEST_IDS.length);

  var rows = [];
  var okCount = 0;
  for (var i = 0; i < RAKUTEN_NAV_GENRE_DIAG_TEST_IDS.length; i++) {
    var t = RAKUTEN_NAV_GENRE_DIAG_TEST_IDS[i];
    var result = diagnoseRakutenNavigationGenreGetOne_(t.genreId, t.expectHint);
    if (result && result.ok) okCount++;
    rows.push([
      runId,
      ranAt,
      result && result.genreId != null ? result.genreId : t.genreId,
      result && result.httpStatus !== '' && result.httpStatus != null ? result.httpStatus : '',
      result && result.endpointKey ? result.endpointKey : '',
      result && result.nameJa ? result.nameJa : '',
      result && result.nameJaPath ? result.nameJaPath : '',
      result && result.expectedHint != null ? result.expectedHint : (t.expectHint || ''),
      !!(result && result.nameOk),
      !!(result && result.ok),
      result && result.errorSummary ? String(result.errorSummary).substring(0, 200) : '',
      RAKUTEN_NAV_GENRE_STAGE1_SCRIPT_VERSION
    ]);
  }

  try {
    appendRakutenNavGenreStage1Rows_(rows);
    Logger.log('[' + stepName + '] runId=' + runId + ' stepName=' + stepName +
      ' functionName=' + functionName + ' state=DONE okCount=' + okCount + '/' + rows.length +
      ' sheet=' + RAKUTEN_NAV_GENRE_STAGE1_SHEET_NAME + ' appended=' + rows.length);
    try {
      SpreadsheetApp.getUi().alert(
        '楽天ジャンル Nav Stage1',
        '完了: 成功 ' + okCount + '/' + rows.length +
          '\nシート「' + RAKUTEN_NAV_GENRE_STAGE1_SHEET_NAME + '」に追記しました。' +
          '\nrunId=' + runId +
          '\n（商品マスタ等への書き込みはしていません）',
        SpreadsheetApp.getUi().ButtonSet.OK
      );
    } catch (eUi) {}
  } catch (eWrite) {
    var wmsg = (eWrite && eWrite.message) || eWrite;
    Logger.log('[' + stepName + '] runId=' + runId + ' state=FAILED writeError=' + wmsg);
    try { SpreadsheetApp.getUi().alert('Stage1書込失敗: ' + wmsg); } catch (e2) {}
  }
}

/**
 * 専用シートのみへ追記。シート名が定数と一致しない場合は例外。
 * @param {Array<Array<*>>} rows
 */
function appendRakutenNavGenreStage1Rows_(rows) {
  if (!rows || !rows.length) {
    throw new Error('追記行が空です');
  }
  var sheetName = RAKUTEN_NAV_GENRE_STAGE1_SHEET_NAME;
  if (sheetName !== '▼診断(楽天ジャンルNav)') {
    throw new Error('Stage1: シート名定数が不正です（安全停止）');
  }
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  if (!ss) throw new Error('アクティブなスプレッドシートがありません');
  var sh = ss.getSheetByName(sheetName);
  var headers = RAKUTEN_NAV_GENRE_STAGE1_HEADERS;
  if (!sh) {
    sh = ss.insertSheet(sheetName);
    Logger.log('[RakutenNavGenreStage1] created sheet name=' + sheetName + ' state=RUNNING');
    sh.getRange(1, 1, 1, headers.length).setValues([headers]);
  } else {
    if (sh.getName() !== sheetName) {
      throw new Error('Stage1: 取得シート名不一致（書込中止）');
    }
    var h1 = String(sh.getRange(1, 1).getValue() || '').trim();
    if (h1 !== 'runId') {
      if (sh.getLastRow() === 0) {
        sh.getRange(1, 1, 1, headers.length).setValues([headers]);
      } else {
        throw new Error('Stage1: ヘッダー行が runId ではありません（誤シート書込防止のため中止）');
      }
    }
  }
  var startRow = sh.getLastRow() + 1;
  if (startRow < 2) startRow = 2;
  // getRange(row, column, numRows, numColumns) ※第3・4は行数・列数
  sh.getRange(startRow, 1, rows.length, headers.length).setValues(rows);
  Logger.log('[RakutenNavGenreStage1] append startRow=' + startRow + ' numRows=' + rows.length +
    ' numCols=' + headers.length + ' state=DONE');
}
